INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('pm-kisan','{"department":"कृषि एवं किसान कल्याण विभाग","documents":["भूमि और परिवार संबंधी विवरण की पुष्टि राज्य के अभिलेखों से कराएं।","पंजीकृत किसानों के लिए e-KYC अनिवार्य है।"],"steps":["सरकारी पोर्टल पर अपात्रता की श्रेणियां पढ़ें।","New Farmer Registration से पंजीकरण करें या अधिकृत केंद्र की सहायता लें।","Know Your Status से भुगतान और सत्यापन की स्थिति देखें।"],"sourceNotes":"PM-KISAN के योजना विवरण और अपात्रता सूची की 14 सितंबर 2026 को समीक्षा। आयकरदाता, संस्थागत भूमिधारक और निर्दिष्ट सरकारी कर्मचारी/पेशेवर सहित अपात्रता श्रेणियां लागू हैं। परिवार में पति, पत्नी और नाबालिग बच्चे शामिल हैं।","applicationUrl":"https://pmkisan.gov.in/","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"pm-kisan","title":"प्रधानमंत्री किसान सम्मान निधि","english":"PM Kisan Samman Nidhi","category":"kisan","state":"central","summary":"भूमिधारक पात्र किसान परिवारों को सालाना ₹6,000 की आय सहायता, तीन बराबर किस्तों में सीधे बैंक खाते में।","benefit":"₹6,000 प्रति वर्ष · ₹2,000 की 3 किस्तें","sourceUrl":"https://pmkisan.gov.in/","priority":true,"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"भूमिधारक किसान परिवार; भूमि और अन्य शर्तों की अलग जाँच होगी"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('ladli-behna','{"department":"महिला एवं बाल विकास विभाग, मध्य प्रदेश","documents":["समग्र परिवार / सदस्य आईडी","आधार कार्ड और समग्र में दर्ज मोबाइल नंबर","स्वयं का आधार-लिंक, DBT सक्रिय बैंक खाता; संयुक्त खाता मान्य नहीं"],"steps":["समग्र e-KYC और बैंक खाते की DBT स्थिति पूरी करें।","ग्राम पंचायत / वार्ड कार्यालय से नए आवेदन की उपलब्धता पूछें।","अधिकृत कार्यालय में आवेदन दर्ज होने पर पावती लें।"],"sourceNotes":"आधिकारिक पोर्टल पर मासिक लाभ ₹1,500 दर्ज है। आवेदन वर्ष की 1 जनवरी को आयु 21 वर्ष पूरी और 60 से कम होना आवश्यक है। इस तारीख-आधारित शर्त का स्वचालित मिलान नहीं किया गया है। आय, संपत्ति और अन्य अपात्रता शर्तें भी लागू हैं। नए आवेदन खुले होने की पुष्टि स्थानीय कार्यालय से करें।","applicationUrl":"https://cmladlibahna.mp.gov.in/","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"ladli-behna","title":"मुख्यमंत्री लाड़ली बहना योजना","english":"Mukhyamantri Ladli Behna Yojana","category":"mahila","state":"madhya-pradesh","summary":"मध्य प्रदेश की पात्र महिलाओं के अपने आधार-लिंक, DBT सक्रिय बैंक खाते में मासिक आर्थिक सहायता।","benefit":"पात्र महिलाओं के लिए ₹1,500 प्रति माह","sourceUrl":"https://cmladlibahna.mp.gov.in/","priority":true,"rules":[{"field":"gender","op":"eq","value":"female","label":"विवाहित महिला; विधवा, तलाकशुदा और परित्यक्ता भी शामिल"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('ayushman-bharat','{"department":"स्वास्थ्य एवं परिवार कल्याण मंत्रालय / राष्ट्रीय स्वास्थ्य प्राधिकरण","documents":["आयुष्मान कार्ड / लाभार्थी पहचान और जरूरी दस्तावेजों की सूची अधिकृत केंद्र से लें।"],"steps":["अधिकृत आयुष्मान केंद्र से लाभार्थी सूची में अपनी पात्रता की पुष्टि कराएं।","अस्पताल के सूचीबद्ध होने और उपचार पैकेज की उपलब्धता की जाँच कराएं।"],"sourceNotes":"स्वास्थ्य मंत्रालय की 4 अगस्त 2026 की PIB विज्ञप्ति से लाभ और 70+ विस्तार की पुष्टि। ₹5 लाख नकद भुगतान नहीं, अस्पताल उपचार का कवर है। लाभार्थी पहचान और कवर की शर्तें विभाग तय करता है।","applicationUrl":"","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"ayushman-bharat","title":"आयुष्मान भारत – प्रधानमंत्री जन आरोग्य योजना","english":"Ayushman Bharat PM JAY","category":"swasthya","state":"central","summary":"पात्र परिवारों के अस्पताल में भर्ती उपचार के लिए स्वास्थ्य कवर। 70 वर्ष और अधिक आयु के वरिष्ठ नागरिकों तक भी योजना का विस्तार किया गया है।","benefit":"पात्र परिवार के लिए सालाना ₹5 लाख तक स्वास्थ्य कवर","sourceUrl":"https://www.pib.gov.in/PressReleasePage.aspx?PRID=2294278&lang=1&reg=6","priority":true,"rules":[]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('pm-awas-gramin','{"department":"ग्रामीण विकास मंत्रालय","documents":["सर्वे और आवास संबंधी अभिलेखों की सूची ग्राम पंचायत से लें।"],"steps":["ग्राम पंचायत से आवास+ सर्वे और प्रतीक्षा सूची की स्थिति पूछें।","ग्राम सभा सत्यापन और लागू अपात्रता शर्तें समझें।","स्वीकृति और किस्तों की जानकारी संबंधित कार्यालय से लें।"],"sourceNotes":"ग्रामीण विकास मंत्रालय की 11 फरवरी 2025 की PIB विज्ञप्ति: मौजूदा इकाई सहायता के साथ मार्च 2029 तक विस्तार। पात्र सूची और अपात्रता मानदंड लागू हैं; केवल ग्रामीण निवासी होना पर्याप्त नहीं है।","applicationUrl":"","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"pm-awas-gramin","title":"प्रधानमंत्री आवास योजना – ग्रामीण","english":"PM Awas Yojana Gramin Housing","category":"awas","state":"central","summary":"ग्रामीण क्षेत्र में पात्र कच्चे घर वाले परिवारों को पक्का घर बनाने के लिए सहायता। चयन सत्यापित प्रतीक्षा / आवास+ सूची से होता है।","benefit":"मैदानी क्षेत्रों में ₹1.20 लाख · निर्दिष्ट पहाड़ी क्षेत्रों में ₹1.30 लाख","sourceUrl":"https://www.pib.gov.in/Pressreleaseshare.aspx?PRID=2101871&lang=2&reg=48","priority":false,"rules":[{"field":"rural","op":"eq","value":true,"label":"ग्रामीण परिवार; आवास की स्थिति और चयन सूची का सत्यापन आवश्यक"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mp-scholarship','{"department":"संबंधित सरकारी विभाग","documents":["दस्तावेजों की सूची official portal पर जाँचें।"],"steps":["पहले official source पर वर्तमान शर्तें पढ़ें।","दस्तावेजों और आवेदन के तरीके की पुष्टि करें।","आवेदन केवल संबंधित सरकारी पोर्टल या अधिकृत केंद्र पर करें।"],"sourceNotes":"दतिया जिला प्रशासन से पोर्टल का संदर्भ मिला है। यह एकल छात्रवृत्ति का सत्यापित रिकॉर्ड नहीं है; पाठ्यक्रम, श्रेणी, राशि और वर्तमान आवेदन अवधि की समीक्षा बाकी है।","applicationUrl":"","status":"REQUIRES_OFFICIAL_VERIFICATION","isSample":false,"verifiedAt":null,"nextReviewAt":null,"slug":"mp-scholarship","title":"मध्य प्रदेश छात्रवृत्ति सहायता","english":"MP Scholarship Students Education","category":"shiksha","state":"madhya-pradesh","summary":"मध्य प्रदेश छात्रवृत्ति पोर्टल का आधिकारिक जिला-प्रशासन संदर्भ। राशि, श्रेणी और आवेदन की तारीखें संबंधित छात्रवृत्ति के अनुसार अलग हैं।","benefit":"पढ़ाई के लिए सहायता की जानकारी","sourceUrl":"https://datia.nic.in/en/service/scholarship-portal/","priority":false,"rules":[{"field":"occupation","op":"eq","value":"student","label":"विद्यार्थी; पाठ्यक्रम और छात्रवृत्ति की अन्य शर्तें लागू"}]}','REQUIRES_OFFICIAL_VERIFICATION',NULL,'2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('social-pension','{"department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["दो फोटो और आयु प्रमाण","लागू श्रेणी के अनुसार निर्धनता, दिव्यांगता या कल्याणी / परित्यक्ता प्रमाण"],"steps":["ग्रामीण क्षेत्र में ग्राम / जनपद पंचायत या शहर में नगर निकाय से संपर्क करें।","अपनी श्रेणी के लागू प्रमाणों के साथ निर्धारित फॉर्म जमा करें।"],"sourceNotes":"विभाग के योजना पृष्ठ पर ₹600 प्रतिमाह दर्ज है। पात्रता की अलग श्रेणियां हैं; केवल 60+ आयु का फ़िल्टर लगाने से अन्य पात्र लोग छूट सकते हैं, इसलिए यहाँ ऐसा फ़िल्टर नहीं लगाया गया है।","applicationUrl":"","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"social-pension","title":"समग्र सामाजिक सुरक्षा पेंशन योजना","english":"Social Security Old Age Pension","category":"pension","state":"madhya-pradesh","summary":"मध्य प्रदेश के पात्र निराश्रित वृद्ध, कल्याणी, परित्यक्ता और दिव्यांग हितग्राहियों के लिए सामाजिक सुरक्षा पेंशन।","benefit":"पात्र हितग्राहियों के लिए ₹600 प्रति माह","sourceUrl":"https://socialjustice.mp.gov.in/schemes/view/WlFNUHFJc2dpRHFIcVI1RlEyb3Q1UT09","priority":false,"rules":[]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('employment-support','{"department":"सूक्ष्म, लघु एवं मध्यम उद्यम विभाग, मध्य प्रदेश","documents":["आयु, आठवीं उत्तीर्ण और पारिवारिक आय संबंधी प्रमाण की सूची जिला उद्योग केंद्र से लें।"],"steps":["जिला व्यापार एवं उद्योग केंद्र से परियोजना और पात्रता की जाँच कराएं।","आधिकारिक आवेदन पोर्टल पर प्रक्रिया पूरी करें।","ऋण का निर्णय बैंक की जाँच और स्वीकृति पर निर्भर है।"],"sourceNotes":"CM Helpline योजना विवरण, अपडेट 7 अगस्त 2024, की समीक्षा। न्यूनतम आठवीं उत्तीर्ण, पारिवारिक वार्षिक आय अधिकतम ₹12 लाख, वित्तीय संस्था का डिफॉल्टर न होना और अन्य स्वरोजगार योजना का वर्तमान हितग्राही न होना आवश्यक है। यह ऋण है, मुफ्त नकद सहायता नहीं।","applicationUrl":"https://samast.mponline.gov.in/","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"employment-support","title":"मुख्यमंत्री उद्यम क्रांति योजना","english":"Mukhyamantri Udyam Kranti Self Employment","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के पात्र युवाओं को स्वयं का उद्यम शुरू करने के लिए बैंक ऋण और ब्याज अनुदान सहायता।","benefit":"3% वार्षिक ब्याज अनुदान और ऋण गारंटी फीस · अधिकतम 7 वर्ष","sourceUrl":"https://cmhelpline.mp.gov.in/Schmedetail.aspx?Schemeid=915","priority":false,"rules":[{"field":"age","op":"gte","value":18,"label":"कम से कम 18 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('ration-support','{"department":"खाद्य एवं सार्वजनिक वितरण विभाग","documents":["राशन कार्ड और राज्य की श्रेणी-विशिष्ट दस्तावेज सूची की पुष्टि करें।"],"steps":["स्थानीय खाद्य कार्यालय से राशन कार्ड की श्रेणी और पात्रता पूछें।","नाम जुड़वाने या सुधार की राज्य-विशिष्ट प्रक्रिया पूरी करें।"],"sourceNotes":"NFSA पोर्टल से PHH और AAY की खाद्यान्न मात्रा की पुष्टि। परिवारों की पहचान और राशन कार्ड प्रक्रिया राज्य / केंद्रशासित प्रदेश के नियमों से संचालित होती है।","applicationUrl":"","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"ration-support","title":"राष्ट्रीय खाद्य सुरक्षा अधिनियम के तहत राशन","english":"Food Security Ration Support","category":"khadya","state":"central","summary":"NFSA के पात्र प्राथमिकता परिवार और अंत्योदय अन्न योजना परिवारों को निर्धारित मात्रा में खाद्यान्न सहायता।","benefit":"PHH: 5 किलो प्रति व्यक्ति / माह · AAY: 35 किलो प्रति परिवार / माह","sourceUrl":"https://nfsa.gov.in/portal/Coverage_Entitlements_NFSA_AA","priority":false,"rules":[]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('seekho-kamao','{"department":"कौशल विकास एवं रोज़गार विभाग, मध्य प्रदेश","documents":["📋 समग्र आईडी (Samagra ID) — 9 अंकों की","🪪 आधार कार्ड — मोबाइल नंबर से लिंक होना जरूरी","🎓 शैक्षणिक प्रमाण पत्र — 12वीं / ITI / डिप्लोमा / स्नातक की मार्कशीट","🏦 बैंक पासबुक — DBT सक्रिय खाता (आधार लिंक)","📸 पासपोर्ट साइज फोटो (हाल की)","📍 निवास प्रमाण पत्र — MP का स्थायी निवासी होने का प्रमाण","📱 मोबाइल नंबर — OTP सत्यापन के लिए"],"steps":["mmsky.mp.gov.in पर जाएं → \"अभ्यर्थी पंजीयन\" पर क्लिक करें।","समग्र आईडी दर्ज करें → OTP से मोबाइल सत्यापन करें।","अपनी योग्यता के अनुसार कोर्स और प्रतिष्ठान चुनें (700+ कोर्स उपलब्ध)।","चुने हुए प्रतिष्ठान में ट्रेनिंग शुरू करें — स्टाइपेंड सीधे खाते में आएगा।","ट्रेनिंग पूर्ण होने पर MMSKY प्रमाण पत्र मिलेगा जो नौकरी में मान्य होगा।"],"sourceNotes":"MMSKY पोर्टल (mmsky.mp.gov.in) से 14 सितंबर 2026 को समीक्षा। स्टाइपेंड राशि शैक्षणिक योग्यता के अनुसार है: 12वीं पास ₹8,000, ITI ₹8,500, डिप्लोमा ₹9,000, स्नातक ₹10,000। यह रोज़गार की गारंटी नहीं है।","applicationUrl":"https://mmsky.mp.gov.in/","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"seekho-kamao","title":"मुख्यमंत्री सीखो कमाओ योजना","english":"Mukhyamantri Seekho Kamao Yojana Skill Training","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के 18–29 वर्ष के युवाओं को मान्यता प्राप्त प्रतिष्ठानों में ऑन-जॉब ट्रेनिंग के दौरान ₹8,000–10,000 प्रति माह स्टाइपेंड और प्रशिक्षण प्रमाण पत्र।","benefit":"₹8,000–₹10,000 प्रति माह स्टाइपेंड · MMSKY प्रशिक्षण प्रमाण पत्र","sourceUrl":"https://mmsky.mp.gov.in/","priority":true,"rules":[{"field":"state","op":"eq","value":"madhya-pradesh","label":"मध्य प्रदेश का स्थायी निवासी"},{"field":"age","op":"gte","value":18,"label":"न्यूनतम 18 वर्ष"},{"field":"age","op":"lte","value":29,"label":"अधिकतम 29 वर्ष"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('kisan-kalyan','{"department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["📋 PM-KISAN पंजीयन संख्या — अनिवार्य (पहले PM-KISAN में रजिस्ट्रेशन जरूरी)","🪪 आधार कार्ड — बैंक खाते से लिंक","🌾 खसरा / खतौनी (भूमि रिकॉर्ड) — ऑनलाइन MP Bhulekh से निकालें","🏦 बैंक पासबुक — DBT सक्रिय, आधार-लिंक खाता","📱 मोबाइल नंबर — PM-KISAN में दर्ज नंबर","📸 पासपोर्ट साइज फोटो","📍 निवास प्रमाण — समग्र ID या मतदाता पहचान पत्र"],"steps":["सबसे पहले pmkisan.gov.in पर PM-KISAN e-KYC पूरी करें।","MP Kisan App या स्थानीय कृषि विभाग कार्यालय से Kisan Kalyan पंजीयन की स्थिति जांचें।","अगर नाम सूची में नहीं है तो ग्राम पंचायत / जनपद पंचायत में आवेदन दें।","किस्त की जानकारी PM-KISAN पोर्टल के \"Know Your Status\" से देखें।"],"sourceNotes":"मुख्यमंत्री किसान कल्याण योजना PM-KISAN की पात्रता पर आधारित है। PM-KISAN अपात्र किसान इस योजना के भी अपात्र हैं। दोनों योजनाओं से कुल ₹12,000/वर्ष मिल सकते हैं।","applicationUrl":"https://pmkisan.gov.in/","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"kisan-kalyan","title":"मुख्यमंत्री किसान कल्याण योजना","english":"Mukhyamantri Kisan Kalyan Yojana Financial Support","category":"kisan","state":"madhya-pradesh","summary":"मध्य प्रदेश के PM-KISAN पंजीकृत किसानों को राज्य सरकार की ओर से अतिरिक्त ₹6,000 प्रति वर्ष सहायता — दो किस्तों में सीधे बैंक खाते में।","benefit":"₹6,000 प्रति वर्ष अतिरिक्त · दो किस्तों में (PM-KISAN के अतिरिक्त)","sourceUrl":"https://mpwcdmis.gov.in/","priority":true,"rules":[{"field":"state","op":"eq","value":"madhya-pradesh","label":"मध्य प्रदेश का कृषक"},{"field":"occupation","op":"eq","value":"farmer","label":"भूमिधारक किसान परिवार (PM-KISAN पंजीकृत)"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('gaon-ki-beti','{"department":"उच्च शिक्षा विभाग, मध्य प्रदेश","documents":["🎓 12वीं की मार्कशीट — 60% या अधिक अंक (ग्रामीण विद्यालय से उत्तीर्ण)","📋 समग्र आईडी (Samagra ID)","🪪 आधार कार्ड","📍 निवास प्रमाण — ग्रामीण क्षेत्र का (राशन कार्ड / समग्र से पुष्टि)","🏦 बैंक पासबुक — DBT सक्रिय खाता","🏫 कॉलेज प्रवेश प्रमाण — वर्तमान सत्र की फीस रसीद / ID","📸 पासपोर्ट साइज फोटो","📜 जाति प्रमाण पत्र (यदि SC/ST/OBC हों)"],"steps":["scholarshipportal.mp.nic.in पर जाएं → \"Student Login\" से पंजीयन करें।","समग्र ID और आधार से प्रोफ़ाइल बनाएं।","\"Gaon Ki Beti\" योजना चुनें और दस्तावेज़ अपलोड करें।","कॉलेज के प्राचार्य से ऑनलाइन सत्यापन कराएं।","छात्रवृत्ति स्वीकृति के बाद DBT खाते में राशि आएगी।"],"sourceNotes":"MP छात्रवृत्ति पोर्टल (scholarshipportal.mp.nic.in) से 14 सितंबर 2026 को समीक्षा। ग्रामीण क्षेत्र की पुष्टि समग्र ID से होती है। आवेदन की तिथि अकादमिक सत्र के अनुसार बदलती है।","applicationUrl":"https://scholarshipportal.mp.nic.in/","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"gaon-ki-beti","title":"गांव की बेटी योजना","english":"Gaon Ki Beti Yojana Rural Girl Scholarship","category":"shiksha","state":"madhya-pradesh","summary":"मध्य प्रदेश के ग्रामीण क्षेत्र की 12वीं में 60% या अधिक अंक पाने वाली छात्राओं को उच्च शिक्षा के लिए ₹500 प्रति माह 10 माह तक छात्रवृत्ति।","benefit":"₹500 प्रति माह · 10 माह · कुल ₹5,000 प्रति वर्ष","sourceUrl":"https://scholarshipportal.mp.nic.in/","priority":true,"rules":[{"field":"state","op":"eq","value":"madhya-pradesh","label":"मध्य प्रदेश के ग्रामीण क्षेत्र की निवासी"},{"field":"gender","op":"eq","value":"female","label":"केवल छात्राओं के लिए"},{"field":"occupation","op":"eq","value":"student","label":"उच्च शिक्षा में प्रवेश लिया हो"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sambal-yojana','{"department":"श्रम विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड — मोबाइल नंबर लिंक होना जरूरी","📋 समग्र आईडी (Samagra ID) — परिवार ID और सदस्य ID दोनों","🏦 बैंक पासबुक — DBT सक्रिय खाता","📱 मोबाइल नंबर (OTP सत्यापन के लिए)","💼 स्व-घोषणा — असंगठित श्रमिक होने का (ग्राम पंचायत / नगर निकाय से सत्यापित)","📸 पासपोर्ट साइज फोटो","⚡ बिजली कनेक्शन नंबर (यदि बिजली माफी चाहते हों)","📜 मृत्यु / दुर्घटना प्रमाण (दावे के समय — FIR / मृत्यु प्रमाण पत्र)"],"steps":["sambal.mp.gov.in पर जाएं या नजदीकी लोक सेवा केंद्र / ग्राम पंचायत जाएं।","समग्र ID और आधार से \"संबल कार्ड\" के लिए पंजीयन करें।","असंगठित श्रमिक की श्रेणी चुनें (मजदूर, किसान मजदूर, घरेलू कामगार आदि)।","पंजीयन के बाद संबल कार्ड मिलेगा — इसे सुरक्षित रखें।","दुर्घटना या मातृत्व जैसे लाभ के लिए संबल पोर्टल पर दावा करें।"],"sourceNotes":"sambal.mp.gov.in से 14 सितंबर 2026 को समीक्षा। पात्रता: असंगठित श्रमिक जो आयकरदाता न हों। संबल कार्ड धारकों को बिजली बिल माफी के लिए अलग से आवेदन नहीं करना — स्वतः लाभ मिलता है।","applicationUrl":"https://sambal.mp.gov.in/","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"sambal-yojana","title":"मुख्यमंत्री जन कल्याण संबल योजना","english":"Mukhyamantri Jan Kalyan Sambal Yojana Unorganized Workers","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के असंगठित श्रमिकों को संबल कार्ड के माध्यम से — दुर्घटना बीमा, मातृत्व सहायता, बच्चों की छात्रवृत्ति, अंत्येष्टि सहायता और बिजली बिल माफी जैसी अनेक सुविधाएं।","benefit":"दुर्घटना मृत्यु: ₹4 लाख · मातृत्व: ₹16,000 · अंत्येष्टि: ₹5,000 · बिजली बिल माफी","sourceUrl":"https://sambal.mp.gov.in/","priority":true,"rules":[{"field":"state","op":"eq","value":"madhya-pradesh","label":"मध्य प्रदेश के निवासी"},{"field":"occupation","op":"eq","value":"worker","label":"असंगठित क्षेत्र के श्रमिक"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('ladli-laxmi','{"department":"महिला एवं बाल विकास विभाग, मध्य प्रदेश","documents":["👶 बालिका का जन्म प्रमाण पत्र (नगर निकाय / ग्राम पंचायत से जारी)","🪪 माता-पिता का आधार कार्ड","📋 परिवार की समग्र आईडी","📍 निवास प्रमाण पत्र (मध्य प्रदेश का)","🏦 माता के नाम बैंक पासबुक — DBT सक्रिय","📸 बालिका और माता की फोटो","📜 आंगनवाड़ी पंजीयन प्रमाण (1–5 वर्ष में पंजीकृत होना जरूरी)","🏥 टीकाकरण कार्ड (आंगनवाड़ी से)","⚠️ परिवार नियोजन प्रमाण (यदि तीसरी संतान हो तो विशेष शर्त)"],"steps":["जन्म के 1 वर्ष के भीतर नजदीकी आंगनवाड़ी केंद्र में बालिका को पंजीकृत कराएं।","ladlilaxmi.mp.gov.in पर जाएं → \"आवेदन करें\" पर क्लिक करें।","समग्र ID और आधार से लॉगिन करें, बालिका की जानकारी भरें।","दस्तावेज़ अपलोड करें → आंगनवाड़ी कार्यकर्ता या ऑनलाइन सत्यापन होगा।","स्वीकृति पर लाड़ली लक्ष्मी प्रमाण पत्र (Certificate) मिलेगा — इसे संभाल कर रखें।","6वीं, 9वीं, 11वीं, 12वीं में प्रवेश पर पोर्टल से किस्त के लिए आवेदन करें।"],"sourceNotes":"ladlilaxmi.mp.gov.in से 14 सितंबर 2026 को समीक्षा। लाड़ली लक्ष्मी 2.0 के तहत उच्च शिक्षा में प्रवेश पर ₹25,000 अतिरिक्त। 21 वर्ष की आयु और 12वीं उत्तीर्ण होने पर ₹1 लाख की राशि विवाह के समय मिलती है।","applicationUrl":"https://ladlilaxmi.mp.gov.in/","status":"ACTIVE","isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-13T00:00:00.000Z","slug":"ladli-laxmi","title":"लाड़ली लक्ष्मी योजना","english":"Ladli Laxmi Yojana Girl Child Certificate Education","category":"mahila","state":"madhya-pradesh","summary":"मध्य प्रदेश में 1 जनवरी 2006 के बाद जन्मी बालिकाओं के नाम ₹1,43,000 का लाड़ली लक्ष्मी प्रमाण पत्र — पढ़ाई के विभिन्न चरणों में किस्तें और विवाह पर अंतिम राशि।","benefit":"₹1,43,000 का प्रमाण पत्र · 6वीं से 12वीं तक किस्तें · 21 वर्ष पर ₹1 लाख","sourceUrl":"https://ladlilaxmi.mp.gov.in/","priority":true,"rules":[{"field":"state","op":"eq","value":"madhya-pradesh","label":"मध्य प्रदेश में जन्मी / निवासी बालिका"},{"field":"gender","op":"eq","value":"female","label":"केवल बालिकाओं के लिए"}]}','ACTIVE','2026-12-13T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('surajdhara-yojana','{"slug":"surajdhara-yojana","title":"सूरजधारा योजना","english":"Surajdhara Yojana SC ST Seed Subsidy","category":"kisan","state":"madhya-pradesh","summary":"मध्य प्रदेश के अनुसूचित जाति (SC) और अनुसूचित जनजाति (ST) के लघु व सीमांत कृषकों को अलाभकारी फसलों के स्थान पर दलहनी व तिलहनी फसलों के उन्नत बीज उपलब्ध कराने की योजना।","benefit":"दलहन व तिलहन के प्रमाणित बीज पर 75% तक अनुदान एवं बीज अदला-बदली","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 भू-स्वामित्व प्रमाण (खसरा/खतौनी B1)","📜 जाति प्रमाण पत्र (SC/ST)","🏦 बैंक खाता पासबुक (DBT सक्रिय)","🖼️ पासपोर्ट साइज फोटो"],"steps":["ग्राम के कृषि विस्तार अधिकारी (RAEO) या विकासखंड कृषि कार्यालय से संपर्क करें।","बीज वितरण सत्र के समय निर्धारित प्रपत्र में आवेदन प्रस्तुत करें।","पात्रता सत्यापन के बाद कृषि विभाग द्वारा 75% अनुदान पर उन्नत बीज मिनीकिट प्राप्त करें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"SC/ST वर्ग के लघु एवं सीमांत किसान"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"किसान कल्याण तथा कृषि विकास विभाग MP द्वारा SC/ST किसानों के लिए बीज प्रतिस्थापन दर बढ़ाने हेतु संचालित।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('madhya-pradesh-ladli-laxmi-yojana','{"slug":"madhya-pradesh-ladli-laxmi-yojana","title":"मध्य प्रदेश मुख्यमंत्री लाड़ली लक्ष्मी योजना","english":"Mukhyamantri Ladli Laxmi Yojana Girl Child Education","category":"mahila","state":"madhya-pradesh","summary":"बालिकाओं के जन्म के प्रति सकारात्मक सोच, उनके शैक्षणिक स्तर और स्वास्थ्य में सुधार तथा बाल विवाह रोकने के लिए मध्य प्रदेश की सबसे प्रतिष्ठित योजना।","benefit":"बालिका के नाम ₹1,43,000 का प्रमाण पत्र, 6वीं से 12वीं तक छात्रवृत्ति एवं 21 वर्ष पर ₹1 लाख","department":"महिला एवं बाल विकास विभाग, मध्य प्रदेश","documents":["🪪 माता-पिता और बालिका का आधार कार्ड","📋 समग्र परिवार एवं सदस्य ID","👶 बालिका का जन्म प्रमाण पत्र","🏠 मध्य प्रदेश मूल निवास प्रमाण पत्र","🖼️ बालिका के साथ माता/पिता का फोटो","📜 परिवार नियोजन प्रमाण पत्र (द्वितीय संतान पर)"],"steps":["आंगनवाड़ी कार्यकर्ता के माध्यम से या ladlilaxmi.mp.gov.in पोर्टल पर ऑनलाइन पंजीयन करें।","जन्म के 1 वर्ष के भीतर आवेदन करना अनिवार्य है।","परियोजना अधिकारी द्वारा स्वीकृति उपरांत लाड़ली लक्ष्मी प्रमाण पत्र जारी होता है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"मध्य प्रदेश में जन्मी पात्र बालिकाएं"}],"sourceUrl":"https://ladlilaxmi.mp.gov.in/","applicationUrl":"https://ladlilaxmi.mp.gov.in/","sourceNotes":"WCD MP द्वारा संचालित। 1.43 लाख रुपये का कुल वित्तीय आश्वासन।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-arthik-kalyan-yojana','{"slug":"mukhyamantri-arthik-kalyan-yojana","title":"मुख्यमंत्री आर्थिक कल्याण योजना","english":"Mukhyamantri Arthik Kalyan Yojana Micro Enterprise","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के अत्यंत गरीब व बीपीएल परिवारों के सदस्यों को स्वयं का छोटा व्यवसाय, ठेला, दुकान या सेवा कार्य शुरू करने के लिए कम ब्याज पर ऋण और सब्सिडी।","benefit":"नया व्यवसाय/उपकरण हेतु ₹50,000 तक ऋण एवं 50% (अधिकतम ₹15,000) मार्जिन मनी अनुदान","department":"सूक्ष्म, लघु एवं मध्यम उद्यम विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏠 मूल निवास प्रमाण पत्र","💰 BPL राशन कार्ड / आय प्रमाण पत्र","🏦 बैंक पासबुक","📝 व्यवसाय/उपकरण का कोटेशन"],"steps":["MP Online SAMAST पोर्टल (samast.mponline.gov.in) पर ऑनलाइन पंजीयन करें।","योजना चयन कर आधार व समग्र e-KYC पूरा करें।","परियोजना विवरण और दस्तावेज अपलोड कर जिला उद्योग केंद्र को प्रेषित करें।","बैंक स्वीकृति के पश्चात मार्जिन मनी सब्सिडी सहित ऋण प्राप्त करें।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 55 वर्ष"},{"field":"age","op":"lte","value":55,"label":"अधिकतम 55 वर्ष"}],"sourceUrl":"https://msme.mponline.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"MSME विभाग मध्य प्रदेश द्वारा BPL वर्ग के लिए उपकरण व कार्यशील पूंजी सहायता।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-kanya-vivah-yojana','{"slug":"mukhyamantri-kanya-vivah-yojana","title":"मध्य प्रदेश मुख्यमंत्री कन्या विवाह योजना","english":"Mukhyamantri Kanya Vivah Yojana Financial Aid","category":"mahila","state":"madhya-pradesh","summary":"मध्य प्रदेश के निर्धन, निराश्रित परिवारों की कन्याओं, विधवाओं और परित्यक्ताओं के विवाह हेतु आर्थिक सहायता प्रदान करने वाली प्रमुख सामूहिक विवाह योजना।","benefit":"₹55,000 की कुल सहायता (₹49,000 कन्या के बैंक खाते में DBT + ₹6,000 सामूहिक विवाह आयोजन)","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 वर और वधू का आधार कार्ड","📋 समग्र परिवार ID","🏠 मध्य प्रदेश मूल निवास प्रमाण पत्र","💰 गरीबी रेखा (BPL) कार्ड या आय प्रमाण पत्र","🎂 वर-वधू का आयु प्रमाण (जन्म प्रमाण पत्र/10वीं अंकसूची)","🏦 वधू का स्वयं का बैंक खाता (आधार लिंक)"],"steps":["सामूहिक विवाह सम्मेलन की निर्धारित तिथि से 15 दिन पूर्व ग्राम पंचायत या जनपद/नगर निकाय में आवेदन करें।","वर की आयु 21 वर्ष और वधू की आयु 18 वर्ष पूर्ण होने के दस्तावेज संलग्न करें।","सामूहिक विवाह सम्मेलन में शामिल होकर विवाह संपन्न कराएं।","सत्यापन उपरांत ₹49,000 वधू के बैंक खाते में अंतरित किए जाते हैं।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"कन्या विवाह सहायता"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा सामूहिक विवाह में ₹55,000 कुल सहायता प्रावधानित।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-teerth-darshan-yojana','{"slug":"mukhyamantri-teerth-darshan-yojana","title":"मध्यप्रदेश मुख्यमंत्री तीर्थ दर्शन योजना","english":"Mukhyamantri Teerth Darshan Yojana Free Pilgrimage","category":"pension","state":"madhya-pradesh","summary":"मध्य प्रदेश के 60 वर्ष या अधिक आयु के वरिष्ठ नागरिकों (महिलाओं के लिए 2 वर्ष की छूट) को राज्य के बाहर स्थित तीर्थ स्थानों की निःशुल्क सुखद यात्रा कराने की योजना।","benefit":"देश के प्रमुख तीर्थ स्थलों की निःशुल्क विशेष ट्रेन/हवाई यात्रा, भोजन, आवास व सुरक्षा","department":"धार्मिक न्यास एवं धर्मस्व विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏠 मूल निवास प्रमाण पत्र","🏥 शासकीय चिकित्सक द्वारा जारी स्वास्थ्य/फिटनेस प्रमाण पत्र","🖼️ 2 पासपोर्ट साइज फोटो"],"steps":["तहसील, जनपद पंचायत या नगर पालिका कार्यालय से तीर्थ दर्शन फॉर्म प्राप्त करें या ऑनलाइन डाउनलोड करें।","यात्रा स्थल और विवरण भरकर डॉक्टर से स्वास्थ्य प्रमाण पत्र बनवाएं।","आवेदन पत्र स्थानीय निकाय में जमा करें; चयन लॉटरी/कलेक्टर समिति द्वारा किया जाता है।","चयनित होने पर विशेष ट्रेन द्वारा निःशुल्क यात्रा कराई जाती है।"],"rules":[{"field":"age","op":"gte","value":60,"label":"आयु 60 वर्ष या अधिक (आयकरदाता न हों)"}],"sourceUrl":"https://tirthdarshan.mp.gov.in/","applicationUrl":"https://tirthdarshan.mp.gov.in/","sourceNotes":"धार्मिक न्यास विभाग MP द्वारा वरिष्ठ नागरिकों के लिए सम्पूर्ण निःशुल्क तीर्थ यात्रा।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mausam-aadharit-fasal-bima-yojana','{"slug":"mausam-aadharit-fasal-bima-yojana","title":"मौसम आधारित फसल बीमा योजना","english":"Mausam Aadharit Fasal Bima Yojana RWBCIS","category":"kisan","state":"madhya-pradesh","summary":"फसल के प्रतिकूल मौसम घटकों जैसे तापमान, वर्षा, नमी और हवा की गति के कारण होने वाले आर्थिक नुकसान से किसानों को सुरक्षा प्रदान करने वाली पुनर्गठित मौसम आधारित फसल बीमा योजना।","benefit":"प्रतिकूल मौसम (अतिवृष्टि, ओलावृष्टि, सूखा, पाला) से बागवानी व फसलों के नुकसान पर प्रत्यक्ष बीमा क्षतिपूर्ति","department":"उद्यानिकी एवं खाद्य प्रसंस्करण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 भूमि अभिलेख (खसरा/खतौनी B1)","🌱 बुवाई प्रमाण पत्र / पटवारी प्रतिवेदन","🏦 बैंक पासबुक (KCC/बैंक खाता)"],"steps":["अधिसूचित फसलों के लिए बैंक, CSC सेंटर या PMFBY पोर्टल के माध्यम से बीमा कराएं।","अधिसूचित कट-ऑफ डेट से पहले निर्धारित प्रीमियम (1.5% से 5%) जमा करें।","मौसम केंद्र द्वारा प्रतिकूल मौसम दर्ज होने पर बीमा क्लेम स्वतः बैंक खाते में भेजा जाता है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"अधिसूचित फल/मसाला/सब्जी उत्पादक किसान"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://pmfby.gov.in/","sourceNotes":"उद्यानिकी विभाग MP व भारत सरकार द्वारा मौसम जोखिम सुरक्षा।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('aushadhiya-fasal-vistar-yojana','{"slug":"aushadhiya-fasal-vistar-yojana","title":"औषधीय एवं सुगन्धित फसल क्षेत्र विस्तार योजना","english":"Aushadhiya Evam Sugandhit Fasal Vistar Yojana","category":"kisan","state":"madhya-pradesh","summary":"अश्वगंधा, कालमेघ, ईसबगोल, लेमनग्रास जैसी औषधीय व सगंध फसलों की खेती को बढ़ावा देने के लिए रोपण सामग्री व उत्पादन लागत पर वित्तीय अनुदान सहायता।","benefit":"औषधीय व सगंध पौधों की खेती पर लागत का 40% से 50% तक सरकारी अनुदान","department":"उद्यानिकी एवं खाद्य प्रसंस्करण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा/खतौनी की नकल","📜 जाति प्रमाण पत्र (लागू होने पर)","🏦 बैंक खाता पासबुक","🖼️ कृषक का फोटो"],"steps":["उद्यानिकी विभाग के MPFSTS पोर्टल (mpfsts.mponline.gov.in) पर पंजीयन करें।","औषधीय फसल का चयन कर पौधरोपण प्रस्ताव दर्ज करें।","विभाग के अधिकारी द्वारा स्थल सत्यापन उपरांत अनुदान सीधे खाते में भेजा जाता है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"कृषि भूमि धारक कृषक"}],"sourceUrl":"https://horticulture.mponline.gov.in/","applicationUrl":"https://mpfsts.mponline.gov.in/","sourceNotes":"उद्यानिकी विभाग MP द्वारा औषधीय फसलों के विविधीकरण हेतु सब्सिडी।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('phal-paudh-ropan-yojana','{"slug":"phal-paudh-ropan-yojana","title":"फल पौध रोपण योजना","english":"Phal Paudh Ropan Yojana Fruit Plantation Subsidy","category":"kisan","state":"madhya-pradesh","summary":"मध्य प्रदेश में फलदार बगीचों की स्थापना को प्रोत्साहित करने हेतु कृषकों को गुणवत्तापूर्ण पौधों, खाद और ड्रिप सिंचाई पर तीन वर्षों में किस्तों में अनुदान दिया जाता है।","benefit":"आम, अमरूद, नीम्बू, अनार, संतरा आदि फलदार बाग लगाने पर 3 वर्षों में 40% से 50% अनुदान","department":"उद्यानिकी एवं खाद्य प्रसंस्करण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 सिंचित भूमि का खसरा B1","📜 जाति प्रमाण पत्र (SC/ST/OBC)","🏦 बैंक पासबुक","🖼️ पासपोर्ट साइज फोटो"],"steps":["MPFSTS पोर्टल पर फल पौध रोपण योजना के तहत ऑनलाइन आवेदन करें।","कृषि/उद्यानिकी नर्सरी से प्रमाणित फल पौधे क्रय करने की स्वीकृति प्राप्त करें।","वृक्षारोपण उपरांत जियो-टैगिंग सत्यापन होने पर अनुदान की पहली किस्त जारी होती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"न्यूनतम 0.25 हेक्टेयर से 4 हेक्टेयर भूमिधारक"}],"sourceUrl":"https://horticulture.mponline.gov.in/","applicationUrl":"https://mpfsts.mponline.gov.in/","sourceNotes":"उद्यानिकी विभाग MP द्वारा प्रति हेक्टेयर निर्धारित लागत पर 40-50% सब्सिडी।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('masala-kshetra-vistar-yojana','{"slug":"masala-kshetra-vistar-yojana","title":"मसाला क्षेत्र विस्तार योजना","english":"Masala Kshetra Vistar Yojana Spices Farming","category":"kisan","state":"madhya-pradesh","summary":"मसाला फसलों के उत्पादन और उत्पादकता में वृद्धि के लिए किसानों को प्रमाणित बीज, कंद और आधुनिक तकनीकी इनपुट्स पर आर्थिक सहायता।","benefit":"लहसुन, धनिया, मिर्च, मेथी, अदरक आदि मसाला फसलों के प्रमाणित बीज/सामग्री पर 40% से 50% अनुदान","department":"उद्यानिकी एवं खाद्य प्रसंस्करण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा-खतौनी","🏦 बैंक पासबुक","📝 बीज/इनपुट खरीद बिल"],"steps":["MPFSTS उद्यानिकी पोर्टल पर लक्ष्य खुलने पर आवेदन करें।","विभाग द्वारा जारी परमिट के आधार पर अधिकृत विक्रेता से बीज/खाद खरीदें।","सत्यापन के उपरांत अनुदान की राशि किसान के DBT खाते में जमा होती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"मध्य प्रदेश के मसाला उत्पादक कृषक"}],"sourceUrl":"https://horticulture.mponline.gov.in/","applicationUrl":"https://mpfsts.mponline.gov.in/","sourceNotes":"उद्यानिकी मिशन MP अंतर्गत मसाला क्षेत्र विस्तार प्रोत्साहन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sabzi-kshetra-vistar-yojana','{"slug":"sabzi-kshetra-vistar-yojana","title":"सब्ज़ी क्षेत्र विस्तार योजना","english":"Sabzi Kshetra Vistar Yojana Hybrid Vegetable Farming","category":"kisan","state":"madhya-pradesh","summary":"टमाटर, बैंगन, गोभी, शिमला मिर्च आदि हाइब्रिड सब्जियों की खेती करने वाले किसानों को उन्नत पौध, मल्चिंग और पोषण प्रबंधन हेतु सहायता।","benefit":"संकर (हाइब्रिड) सब्जी उत्पादन हेतु लागत पर ₹20,000 प्रति हेक्टेयर तक सरकारी अनुदान","department":"उद्यानिकी एवं खाद्य प्रसंस्करण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 जमीन का खसरा","🏦 बैंक खाता विवरण","🖼️ फोटो"],"steps":["उद्यानिकी विभाग की वेबसाइट पर ऑनलाइन पंजीयन करें।","अनुमोदित नर्सरी से प्लग प्लांट/हाइब्रिड पौधे खरीदें।","फील्ड सत्यापन के बाद सहायता राशि किसान के बैंक खाते में अंतरित की जाती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"सब्जी उत्पादक किसान"}],"sourceUrl":"https://horticulture.mponline.gov.in/","applicationUrl":"https://mpfsts.mponline.gov.in/","sourceNotes":"उद्यानिकी विभाग MP द्वारा हाइब्रिड सब्जी खेती पर 40% अनुदान।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sanrakshit-kheti-protsahan-yojana','{"slug":"sanrakshit-kheti-protsahan-yojana","title":"संरक्षित खेती प्रोत्साहन योजना","english":"Sanrakshit Kheti Protsahan Polyhouse Shednet Subsidy","category":"kisan","state":"madhya-pradesh","summary":"बेमौसम उच्च मूल्य वाली फसलों की सुरक्षित खेती के लिए पॉलीहाउस और शेडनेट स्थापना पर 50% पूंजीगत सब्सिडी।","benefit":"ग्रीनहाउस (पॉलीहाउस) और शेडनेट हाउस निर्माण पर 50% सरकारी अनुदान (लाखों रुपये तक)","department":"उद्यानिकी एवं खाद्य प्रसंस्करण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 भूमि का खसरा (कम से कम 1000 वर्ग मीटर)","💧 सिंचाई जल स्रोत उपलब्धता प्रमाण","🏦 बैंक स्वीकृति पत्र / स्व-वित्तीय प्रमाण"],"steps":["MPFSTS पोर्टल पर पॉलीहाउस/शेडनेट स्थापना घटक में आवेदन करें।","पैनलबद्ध एजेंसी से तकनीकी एस्टीमेट बनवाएं।","विभागीय स्वीकृति के उपरांत संरचना निर्माण कराएं।","भौतिक सत्यापन उपरांत सब्सिडी सीधे बैंक या एजेंसी खाते में अंतरित होती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"कृषक जिनके पास निजी सिंचित भूमि हो"}],"sourceUrl":"https://horticulture.mponline.gov.in/","applicationUrl":"https://mpfsts.mponline.gov.in/","sourceNotes":"राष्ट्रीय बागवानी मिशन एवं राज्य योजना अंतर्गत 50% अनुदान प्रावधान।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('udyaniki-yantrikaran-yojana','{"slug":"udyaniki-yantrikaran-yojana","title":"उद्यानिकी विकास हेतु यंत्रीकरण योजना","english":"Udyaniki Yantrikaran Farm Equipment Subsidy","category":"kisan","state":"madhya-pradesh","summary":"बागवानी फसलों में श्रम की बचत और दक्षता बढ़ाने के लिए छोटे किसानों को पावर टिलर (8 BHP से अधिक) व पौध संरक्षण यंत्रों की खरीद पर सब्सिडी।","benefit":"पावर टिलर, ट्रैक्टर माउंटेड स्प्रेयर व आधुनिक उद्यानिकी उपकरणों पर 40% से 50% अनुदान","department":"उद्यानिकी एवं खाद्य प्रसंस्करण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा बी-1 प्रति","📜 जाति प्रमाण पत्र","🏦 बैंक पासबुक"],"steps":["पोर्टल पर यंत्रवार लॉटरी/टारगेट खुलने पर ऑनलाइन आवेदन करें।","डीलर चयन कर अधिकृत यंत्र का कोटेशन संलग्न करें।","स्वीकृति उपरांत यंत्र खरीदें और विभाग से भौतिक सत्यापन कराएं।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"उद्यानिकी कृषक"}],"sourceUrl":"https://horticulture.mponline.gov.in/","applicationUrl":"https://mpfsts.mponline.gov.in/","sourceNotes":"उद्यानिकी यंत्रीकरण योजना में अनुसूचित जाति/जनजाति व महिला कृषकों को 50% तक छूट।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('golden-kitchen-garden-yojana','{"slug":"golden-kitchen-garden-yojana","title":"घरेलू बागवानी की आदर्श योजना (गोल्डन किचन)","english":"Golden Kitchen Garden Domestic Gardening Scheme","category":"kisan","state":"madhya-pradesh","summary":"ग्रामीण व अर्ध-शहरी परिवारों में कुपोषण दूर करने और ताजी हरी सब्जियां उपलब्ध कराने हेतु घर के आंगन/छत पर पोषण वाटिका (किचन गार्डन) स्थापना सहायता।","benefit":"सब्जी बीज मिनीकिट एवं पोषण वाटिका उपकरण किट नाममात्र शुल्क पर","department":"उद्यानिकी एवं खाद्य प्रसंस्करण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏠 निवास का प्रमाण"],"steps":["स्थानीय उद्यानिकी अधिकारी या आंगनवाड़ी केंद्र से संपर्क करें।","मौसम अनुसार सब्जी बीज किट प्राप्त करें।","घर के आसपास जैविक पोषण वाटिका तैयार कर ताजी सब्जियों का लाभ लें।"],"rules":[],"sourceUrl":"https://horticulture.mponline.gov.in/","applicationUrl":"https://horticulture.mponline.gov.in/","sourceNotes":"उद्यानिकी विभाग MP द्वारा पारिवारिक पोषण सुधार हेतु संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('bhavantar-bhugtan-yojana','{"slug":"bhavantar-bhugtan-yojana","title":"भावान्तर भुगतान योजना (मूल्य अंतर भुगतान योजना)","english":"Bhavantar Bhugtan Yojana Price Deficit Payment","category":"kisan","state":"madhya-pradesh","summary":"कृषि उत्पादों के बाजार भाव गिरने पर किसानों को आर्थिक सुरक्षा देने वाली देश की पहली मूल्य अंतर भुगतान योजना।","benefit":"न्यूनतम समर्थन मूल्य (MSP) और मंडी के मॉडल विक्रय मूल्य के अंतर की राशि सीधे बैंक खाते में","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा/गिरदावरी पंजीयन पावती","🏦 आधार लिंक बैंक खाता","🧾 कृषि उपज मंडी विक्रय अनुबंध व भुगतान पर्ची"],"steps":["ई-उपार्जन पोर्टल पर फसल बोवनी की अवधि में अपना पंजीयन कराएं।","अधिसूचित अवधि में अधिकृत कृषि उपज मंडी में फसल बेचें।","मंडी द्वारा दर्ज तौल व भुगतान पर्ची के आधार पर भावान्तर राशि DBT से बैंक खाते में आएगी।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"पंजीकृत कृषक जिन्होंने अधिसूचित मंडी में उपज बेची"}],"sourceUrl":"https://saara.mp.gov.in/","applicationUrl":"https://saara.mp.gov.in/","sourceNotes":"मध्य प्रदेश कृषि विभाग द्वारा किसानों को मंडी मूल्य घाटे से बचाने हेतु योजना।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('krishak-prashikshan-bhraman-yojana','{"slug":"krishak-prashikshan-bhraman-yojana","title":"कृषक प्रशिक्षण तथा भ्रमण कार्यक्रम","english":"Krishak Prashikshan Tatha Bhraman Yojana Farmers Training","category":"kisan","state":"madhya-pradesh","summary":"किसानों को आधुनिक कृषि पद्धतियों, जैविक खेती, नई किस्मों और उन्नत तकनीकों से अवगत कराने हेतु कृषि विश्वविद्यालयों व शोध संस्थानों में निःशुल्क प्रशिक्षण व भ्रमण।","benefit":"निःशुल्क आवासीय कृषि प्रशिक्षण, राज्य व अंतर्राज्यीय भ्रमण, यात्रा भत्ता व मानदेय","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 भूमि अभिलेख खसरा","🖼️ पासपोर्ट फोटो"],"steps":["विकासखंड स्तर पर वरिष्ठ कृषि विकास अधिकारी (SADO) या आत्मा (ATMA) परियोजना से संपर्क करें।","प्रशिक्षण दल में अपना नाम दर्ज करवाएं।","चयनित होने पर कृषि विज्ञान केंद्र (KVK) या अन्य राज्यों के सफल फार्मों का निःशुल्क अध्ययन भ्रमण करें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"सक्रिय कृषक"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"आत्मा (ATMA) एवं कृषि विस्तार सुधार कार्यक्रम MP द्वारा वित्तपोषित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('krishi-mela-pradarshani-yojana','{"slug":"krishi-mela-pradarshani-yojana","title":"प्रदर्शनी, मेला एवं प्रचार प्रसार योजना","english":"Krishi Mela Pradarshani Prachar Prasar Yojana","category":"kisan","state":"madhya-pradesh","summary":"जिला व राज्य स्तरीय कृषि विज्ञान मेलों का आयोजन कर किसानों को नवीनतम कृषि यंत्रों, बीजों, उर्वरकों और विभागीय योजनाओं की सीधी जानकारी देना।","benefit":"कृषि मेलों में निःशुल्क स्टॉल, नई मशीनरी का जीवंत प्रदर्शन एवं उत्कृष्ट कृषक पुरस्कार","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 किसान क्रेडिट कार्ड या भूमि प्रमाण"],"steps":["जिले में आयोजित होने वाले कृषि महोत्सव/मेले की तिथि की जानकारी ग्राम पंचायत से लें।","मेले में उपस्थित होकर विभागीय स्टॉल्स पर योजनाओं में सीधे ऑन-स्पॉट पंजीयन कराएं।"],"rules":[],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"कृषि विभाग MP द्वारा समय-समय पर जिला एवं संभाग स्तर पर आयोजित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mahila-krishi-bhagidari-yojana','{"slug":"mahila-krishi-bhagidari-yojana","title":"मध्य प्रदेश कृषि में महिलाओं की भागीदारी योजना","english":"Mahila Krishi Bhagidari Women in Agriculture MP","category":"mahila","state":"madhya-pradesh","summary":"कृषि क्षेत्र में महिला किसानों की कार्यकुशलता बढ़ाने, ड्रजरी (शारीरिक श्रम) कम करने वाले छोटे हस्तचलित यंत्र उपलब्ध कराने और उन्हें निर्णय लेने में सक्षम बनाने की योजना।","benefit":"महिला कृषक समूहों को विशेष प्रशिक्षण, महिला-अनुकूल कृषि यंत्र किट एवं वित्तीय संबल","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 परिवार/स्वयं की कृषि भूमि प्रमाण","🏦 महिला का बैंक खाता"],"steps":["गांव के महिला स्व-सहायता समूह (SHG) या कृषि मित्र से संपर्क करें।","महिला कृषक प्रशिक्षण कार्यक्रम में नाम दर्ज कराएं।","प्रशिक्षण उपरांत महिला-अनुकूल कृषि उपकरण किट प्राप्त करें।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"महिला कृषक / कृषि मजदूर"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"कृषि में महिलाओं की भागीदारी बढ़ाने हेतु विशेष राज्य पोषित योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('kisan-mitra-prashikshan-yojana','{"slug":"kisan-mitra-prashikshan-yojana","title":"किसान मित्र प्रशिक्षण योजना","english":"Kisan Mitra Prashikshan Yojana Community Extension","category":"kisan","state":"madhya-pradesh","summary":"प्रत्येक दो आबाद गांवों के लिए एक प्रगतिशील किसान को ''किसान मित्र'' के रूप में प्रशिक्षित करना, जो सरकारी योजनाओं और उन्नत तकनीकों को अंतिम छोर तक पहुंचा सके।","benefit":"प्रशिक्षण, प्रमाण पत्र एवं किसानों को परामर्श देने पर प्रोत्साहन राशि/मानदेय","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 10वीं/12वीं अंकसूची","🌾 कृषि भूमि रिकॉर्ड","🏦 बैंक पासबुक"],"steps":["ग्राम सभा की बैठक में किसान मित्र चयन की प्रक्रिया में भाग लें।","कृषि विभाग द्वारा आयोजित आवासीय प्रशिक्षण सफलतापूर्वक पूर्ण करें।","गांव में विस्तार गतिविधियों के संचालन पर विभागीय प्रोत्साहन प्राप्त करें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"प्रगतिशील किसान (न्यूनतम 10वीं पास)"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"मध्य प्रदेश कृषि विस्तार सुधार (ATMA) नियम अंतर्गत चयन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('jaivik-kheti-protsahan-yojana','{"slug":"jaivik-kheti-protsahan-yojana","title":"जैविक खेती प्रोत्साहन योजना","english":"Jaivik Kheti Protsahan Yojana Organic Farming MP","category":"kisan","state":"madhya-pradesh","summary":"रसायन मुक्त प्राकृतिक व जैविक खेती को बढ़ावा देने के लिए कृषकों के समूह बनाकर वर्मी कम्पोस्ट पिट निर्माण, जैव-उर्वरक और PGS प्रमाणीकरण में पूरी मदद।","benefit":"जैविक खाद इकाई (वर्मी कम्पोस्ट), जैविक कीटनाशक बनाने पर ₹8,000 तक अनुदान एवं निःशुल्क प्रमाणीकरण","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा नकल","🏦 बैंक खाता पासबुक"],"steps":["कृषि कार्यालय में परम्परागत कृषि विकास योजना (PKVY) के क्लस्टर में नाम जुड़वाएं।","वर्मी कम्पोस्ट यूनिट का निर्माण कर विभाग से सत्यापन कराएं।","जैविक प्रमाणीकरण प्रमाण पत्र प्राप्त कर जैविक उपज को प्रीमियम मूल्य पर बेचें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"जैविक/प्राकृतिक खेती करने वाले किसान"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"MP में जैविक खेती क्षेत्र विस्तार हेतु PKVY एवं राज्य योजना का समन्वय।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('balram-tal-yojana','{"slug":"balram-tal-yojana","title":"बलराम ताल योजना","english":"Balram Tal Yojana Farm Pond Construction Subsidy","category":"kisan","state":"madhya-pradesh","summary":"वर्षा जल संचयन और भू-जल स्तर बढ़ाने के लिए किसानों को अपने खेतों में बलराम ताल (खेत तालाब) बनाने हेतु भारी वित्तीय अनुदान देने की अत्यंत लोकप्रिय योजना।","benefit":"खेत में पक्का/कच्चा तालाब निर्माण पर सामान्य वर्ग को 40% (₹80,000) तथा SC/ST को 75% (₹1,00,000 तक) अनुदान","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 भूमि का खसरा B1 (ड्रिप/स्प्रिंकलर लगा होना अनिवार्य)","📜 जाति प्रमाण पत्र (SC/ST के लिए)","🏦 बैंक पासबुक (DBT लिंक)"],"steps":["कृषि अभियांत्रिकी पोर्टल (dbt.mpdage.org) पर ऑनलाइन आवेदन करें।","लॉटरी में नाम आने पर स्थल का लेआउट बनवाएं और निर्धारित माप का तालाब खुदवाएं।","विभागीय उप-यंत्री द्वारा स्थल माप व सत्यापन के बाद सब्सिडी सीधे बैंक खाते में जमा होती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"न्यूनतम भूमिधारक कृषक जिनके पास सिंचाई उपकरण हो"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"कृषि अभियांत्रिकी संचालनालय MP द्वारा वर्षा जल संचयन हेतु अनुदान।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('annapurna-beej-yojana','{"slug":"annapurna-beej-yojana","title":"अन्नपूर्णा योजना","english":"Annapurna Yojana Seed Exchange Scheme","category":"kisan","state":"madhya-pradesh","summary":"अनुसूचित जाति एवं अनुसूचित जनजाति के किसानों को उनके पुराने बीजों के बदले प्रमाणित उच्च उपज वाले बीज उपलब्ध कराकर पैदावार बढ़ाने की योजना।","benefit":"खाद्यान्न फसलों (गेहूं, चना, धान) के बीज की अदला-बदली पर 75% तक अनुदान","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा नकल","📜 SC/ST जाति प्रमाण पत्र","🏦 बैंक खाता पासबुक"],"steps":["कृषि विस्तार अधिकारी या सेवा सहकारी समिति से संपर्क करें।","बोवनी से पूर्व अपना पुराना बीज जमा कर नया प्रमाणित बीज प्राप्त करें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"SC/ST वर्ग के लघु व सीमांत किसान"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"कृषि विभाग MP द्वारा बीज प्रतिस्थापन दर में वृद्धि हेतु संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('bailgadi-anudan-yojana','{"slug":"bailgadi-anudan-yojana","title":"बैलगाड़ी अनुदान योजना","english":"Bailgadi Anudan Yojana Bull Cart Subsidy","category":"kisan","state":"madhya-pradesh","summary":"लघु एवं सीमांत कृषकों को कृषि उपज व खाद-बीज के सुगम परिवहन हेतु परंपरागत बैलगाड़ी क्रय करने पर वित्तीय सहायता।","benefit":"बैलगाड़ी एवं बैलों की खरीद पर 50% सरकारी अनुदान (अधिकतम ₹10,000 तक)","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 लघु/सीमांत किसान प्रमाण पत्र (खसरा B1)","📜 जाति प्रमाण पत्र","🏦 बैंक पासबुक"],"steps":["विकासखंड कृषि कार्यालय में निर्धारित फॉर्म भरकर प्रस्तुत करें।","सत्यापन उपरांत बैलगाड़ी क्रय करने हेतु अनुदान राशि जारी होती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"लघु एवं सीमांत किसान"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"कृषि विभाग MP द्वारा छोटे किसानों के परिवहन संबल हेतु योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('ambedkar-medhavi-vidyarthi-puraskar','{"slug":"ambedkar-medhavi-vidyarthi-puraskar","title":"डॉ भीम राव अम्बेडकर मेधावी विद्यार्थी पुरुस्कार योजना","english":"Dr BR Ambedkar Medhavi Vidyarthi Puraskar","category":"shiksha","state":"madhya-pradesh","summary":"अनुसूचित जाति के प्रतिभाशाली छात्र-छात्राओं को उत्कृष्ट शैक्षणिक प्रदर्शन के लिए राज्य व जिला स्तर पर नकद प्रोत्साहन।","benefit":"10वीं और 12वीं बोर्ड में टॉप करने वाले SC छात्रों को ₹10,000 से ₹30,000 तक नकद पुरस्कार व प्रशस्ति पत्र","department":"अनुसूचित जाति कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 SC डिजिटल जाति प्रमाण पत्र","🎓 10वीं/12वीं की अंकसूची","🏦 छात्र का बैंक खाता"],"steps":["बोर्ड परीक्षा परिणाम घोषित होने पर विद्यालय के प्राचार्य के माध्यम से आवेदन अग्रेषित होता है।","मेरिट सूची अनुसार पुरस्कार राशि सीधे बैंक खाते में अंतरित होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"SC वर्ग के मेधावी छात्र"}],"sourceUrl":"https://scdevelopmentmp.nic.in/","applicationUrl":"https://scdevelopmentmp.nic.in/","sourceNotes":"अनुसूचित जाति कल्याण विभाग MP द्वारा प्रतिवर्ष मेधावी छात्रों को सम्मानित किया जाता है।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('krishi-jalvayu-pilot-project','{"slug":"krishi-jalvayu-pilot-project","title":"कृषि जलवायु क्षेत्र हेतु पायलेट प्रोजेक्ट","english":"Krishi Jalvayu Pilot Project Agro Climatic Zone","category":"kisan","state":"madhya-pradesh","summary":"मध्य प्रदेश के 11 कृषि जलवायु क्षेत्रों में मौसम बदलाव के अनुसार अनुकूलित फसलें लेने हेतु चयनित गांवों में प्रदर्शन कार्यक्रम।","benefit":"जलवायु-अनुकूल फसल चक्र तकनीक, बीज किट व विशेष फसल संरक्षण पर 100% तकनीकी मार्गदर्शन","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 किसान खसरा अभिलेख"],"steps":["पायलेट प्रोजेक्ट अधिसूचित गांवों में कृषि विभाग की टीम से संपर्क करें।","प्रदर्शन प्रक्षेत्र में शामिल होकर तकनीक का लाभ लें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"अधिसूचित जलवायु क्षेत्र के किसान"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"जलवायु परिवर्तन अनुकूलन रणनीति MP कृषि विभाग।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sinchai-kshamta-vikas-yojana','{"slug":"sinchai-kshamta-vikas-yojana","title":"सिंचाई क्षमता विकास योजना","english":"Sinchai Kshamta Vikas Yojana Drip Sprinkler Subsidy","category":"kisan","state":"madhya-pradesh","summary":"सूक्ष्म सिंचाई तकनीकों को अपनाकर पानी की 50% बचत और पैदावार में 30-40% वृद्धि के लिए उपकरण अनुदान योजना।","benefit":"ड्रिप और स्प्रिंकलर (फव्वारा) सिंचाई संयंत्र स्थापना पर 55% तक अनुदान (SC/ST/महिला को अतिरिक्त लाभ)","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 भूमि का खसरा B1","💧 सिंचाई जल स्रोत (कुआं/बोरवेल/तालाब) प्रमाण","🏦 बैंक खाता पासबुक"],"steps":["ई-कृषि यंत्र अनुदान पोर्टल (dbt.mpdage.org) पर ऑनलाइन पंजीयन करें।","लॉटरी में नाम आने पर पंजीकृत डीलर से ड्रिप/स्प्रिंकलर लगवाएं।","विभागीय भौतिक सत्यापन उपरांत अनुदान सीधे बैंक खाते में अंतरित होगा।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"सिंचित जल स्रोत धारक कृषक"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"प्रधानमंत्री कृषि सिंचाई योजना एवं राज्य घटक अंतर्गत संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('satat-ganna-vikas-yojana','{"slug":"satat-ganna-vikas-yojana","title":"सतत गन्ना विकास योजना","english":"Satat Ganna Vikas Yojana Sugarcane Development MP","category":"kisan","state":"madhya-pradesh","summary":"चीनी मिल क्षेत्रों और नर्मदा कछार में गन्ने की उत्पादकता बढ़ाने हेतु आधुनिक रोपण तकनीकों व उर्वरक प्रबंधन पर वित्तीय प्रोत्साहन।","benefit":"टिशू कल्चर गन्ना पौध, चौड़ी कतार बुवाई व मल्चिंग पर ₹12,000 प्रति हेक्टेयर तक अनुदान","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा खतौनी","🏭 चीनी मिल आपूर्ति पर्ची/अनुबंध पत्र","🏦 बैंक पासबुक"],"steps":["स्थानीय गन्ना विकास अधिकारी या चीनी मिल के गन्ना विभाग में आवेदन दर्ज करें।","प्रमाणित नर्सरी से पौध प्राप्त कर आधुनिक विधि से रोपण करें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"गन्ना उत्पादक कृषक"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"गन्ना बहुल जिलों में उत्पादकता वृद्धि हेतु विशेष योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-videsh-krishi-yatra','{"slug":"mukhyamantri-videsh-krishi-yatra","title":"मुख्यमंत्री विदेश अध्ययन यात्रा","english":"Mukhyamantri Videsh Adhyayan Yatra Krishi","category":"kisan","state":"madhya-pradesh","summary":"मध्य प्रदेश के प्रगतिशील किसानों को विश्वस्तरीय आधुनिक कृषि तकनीकें, ड्रिप इरिगेशन, संरक्षित खेती और पोस्ट-हार्वेस्ट मैनेजमेंट सीखने हेतु विदेश अध्ययन दल में भेजना।","benefit":"विदेशों (जैसे इजराइल, नीदरलैंड्स, ऑस्ट्रेलिया) में आधुनिक खेती तकनीक सीखने का पूर्णतः निःशुल्क भ्रमण","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","🛂 पासपोर्ट (वैधता न्यूनतम 1 वर्ष)","🌾 स्वयं के नाम कृषि भूमि प्रमाण","🏆 कृषि क्षेत्र में नवाचार/उत्कृष्टता प्रमाण पत्र"],"steps":["जिला उप-संचालक कृषि कार्यालय में विज्ञप्ति जारी होने पर निर्धारित प्रारूप में आवेदन करें।","राज्य स्तरीय चयन समिति द्वारा साक्षात्कार उपरांत दल का चयन होता है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"मध्य प्रदेश के प्रगतिशील नवाचारी कृषक"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"कृषि विभाग MP द्वारा राज्य के किसानों को वैश्विक तकनीक से जोड़ने हेतु संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mitti-parikshan-yojana','{"slug":"mitti-parikshan-yojana","title":"मिटटी परीक्षण योजना","english":"Mitti Parikshan Yojana Soil Health Card MP","category":"kisan","state":"madhya-pradesh","summary":"संतुलित रासायनिक व जैविक खाद उपयोग की सलाह देकर खाद की लागत घटाने और भूमि की उर्वरा शक्ति सुरक्षित रखने की योजना।","benefit":"खेत की मिट्टी की निःशुल्क 12 मापदंडों पर जांच एवं मृदा स्वास्थ्य कार्ड (Soil Health Card)","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खेत का खसरा नंबर","📱 मोबाइल नंबर"],"steps":["कृषि विस्तार अधिकारी को अपने खेत की मिट्टी का नमूना सौंपें या प्रयोगशाला ले जाएं।","जांच के उपरांत निःशुल्क मृदा स्वास्थ्य कार्ड प्राप्त करें जिसमें फसलवार खाद की सिफारिश होगी।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"समस्त भूमिधारक कृषक"}],"sourceUrl":"https://soilhealth.dac.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"सॉयल हेल्थ कार्ड योजना के तहत हर 3 वर्ष में निःशुल्क परीक्षण।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('beej-gram-yojana','{"slug":"beej-gram-yojana","title":"बीज ग्राम योजना","english":"Beej Gram Yojana Certified Seed Production","category":"kisan","state":"madhya-pradesh","summary":"गांव स्तर पर किसानों का समूह बनाकर उन्हें स्वयं के लिए उन्नत व प्रमाणित बीज उत्पादक बनाने की योजना, जिससे उत्तम बीज सस्ते में मिल सके।","benefit":"फाउंडेशन बीज पर 50% अनुदान, बीज भंडारण कोठी अनुदान एवं सीड ग्रेडर सुविधा","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 कृषि भूमि रिकॉर्ड खसरा","🏦 बैंक पासबुक"],"steps":["गांव में 25-50 किसानों का समूह बनाकर कृषि कार्यालय में आवेदन करें।","प्रशिक्षण व फाउंडेशन बीज प्राप्त कर निर्धारित मानकों पर बीज तैयार करें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"बीज उत्पादक कृषक समूह"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"राष्ट्रीय बीज मिशन अंतर्गत ग्राम स्तर पर बीज आत्मनिर्भरता हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('macro-management-scheme-krishi','{"slug":"macro-management-scheme-krishi","title":"मैक्रो मैनेजमेंट स्कीम","english":"Macro Management Scheme Agriculture","category":"kisan","state":"madhya-pradesh","summary":"राज्य की विशिष्ट स्थानीय कृषि आवश्यकताओं के अनुसार किसानों को उन्नत कृषि उपकरण, पौध संरक्षण रसायन और बीज उपलब्ध कराने का एकीकृत कार्यक्रम।","benefit":"कृषि विकास के विभिन्न घटकों (भूमि सुधार, कीट प्रबंधन, फसल विविधीकरण) पर वित्तीय सहायता","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा B1","🏦 बैंक खाता"],"steps":["वरिष्ठ कृषि विकास अधिकारी कार्यालय से चल रहे घटक की जानकारी प्राप्त कर आवेदन करें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"मध्य प्रदेश के कृषक"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"कृषि मंत्रालय एवं राज्य सरकार का समन्वित कार्यक्रम।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('gramin-engineer-yojana','{"slug":"gramin-engineer-yojana","title":"ग्रामीण इंजीनियर योजना","english":"Gramin Engineer Yojana Rural Youth Technical Skill","category":"shiksha","state":"madhya-pradesh","summary":"ग्रामीण युवाओं को स्थानीय स्तर पर तकनीकी कौशल सिखाकर उन्हें ''ग्रामीण इंजीनियर'' के रूप में स्वरोज़गार स्थापित करने के योग्य बनाना।","benefit":"ग्रामीण युवाओं को इलेक्ट्रीशियन, प्लंबिंग, सोलर व कृषि यंत्र रिपेयरिंग का निःशुल्क प्रमाणिक प्रशिक्षण व टूलकिट","department":"पंचायत एवं ग्रामीण विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 10वीं/12वीं/ITI अंकसूची","🏠 ग्रामीण निवास प्रमाण पत्र","🏦 बैंक पासबुक"],"steps":["जनपद पंचायत या कौशल विकास केंद्र पर संपर्क कर पंजीयन कराएं।","3 माह का व्यावहारिक प्रशिक्षण पूरा करने पर टूलकिट व प्रमाण पत्र प्राप्त करें।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 35 वर्ष"},{"field":"age","op":"lte","value":35,"label":"अधिकतम 35 वर्ष"}],"sourceUrl":"https://prd.mp.gov.in/","applicationUrl":"https://skill.mponline.gov.in/","sourceNotes":"पंचायत एवं ग्रामीण विकास विभाग MP द्वारा ग्रामीण स्वरोज़गार हेतु पहल।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('apradh-pidit-pratikar-yojana','{"slug":"apradh-pidit-pratikar-yojana","title":"मध्य प्रदेश अपराध पीड़ित प्रतिकर योजना","english":"Apradh Pidit Pratikar Crime Victim Compensation","category":"pension","state":"madhya-pradesh","summary":"गंभीर अपराध, यौन हिंसा, एसिड अटैक या हत्या के पीड़ितों और उनके परिवारों को चिकित्सा, पुनर्वास और त्वरित आर्थिक राहत प्रदान करने की विधिक योजना।","benefit":"अपराध से पीड़ित/घायल या उनके आश्रितों को ₹2 लाख से ₹10 लाख तक अंतरिम व अंतिम मुआवजा सहायता","department":"गृह विभाग, मध्य प्रदेश / राज्य विधिक सेवा प्राधिकरण","documents":["🪪 आधार कार्ड","📋 समग्र ID","📑 FIR / पुलिस विवेचना रिपोर्ट की प्रति","🏥 मेडिकल रिपोर्ट / मृत्यु प्रमाण पत्र","🏦 बैंक खाता पासबुक"],"steps":["जिला विधिक सेवा प्राधिकरण (DLSA) कार्यालय या न्यायालय में सचिव के समक्ष आवेदन प्रस्तुत करें।","जांच समिति द्वारा 30 से 60 दिन के भीतर प्रतिकर राशि स्वीकृत कर बैंक खाते में अंतरित की जाती है।"],"rules":[],"sourceUrl":"https://mpslsa.gov.in/","applicationUrl":"https://mpslsa.gov.in/","sourceNotes":"MP राज्य विधिक सेवा प्राधिकरण एवं गृह विभाग द्वारा संचालित वैधानिक योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('swarna-jayanti-gram-swarojgar-yojana','{"slug":"swarna-jayanti-gram-swarojgar-yojana","title":"स्वर्ण जयंती ग्राम स्वरोज़गार योजना","english":"Swarna Jayanti Gram Swarojgar Self Help Group","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश राज्य ग्रामीण आजीविका मिशन (MPSRLM) के अंतर्गत ग्रामीण निर्धन परिवारों को महिला स्व-सहायता समूहों से जोड़कर आजीविका संवर्धन।","benefit":"ग्रामीण स्व-सहायता समूहों (SHG) को रिवॉल्विंग फंड, प्रशिक्षण एवं ₹5 लाख तक बैंक लिंकेज व सब्सिडी","department":"पंचायत एवं ग्रामीण विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","💰 BPL राशन कार्ड","🏦 समूह का बैंक खाता व खाता विवरण","📝 समूह का संकल्प पत्र"],"steps":["गांव की आजीविका सखी या ग्राम संगठन से संपर्क कर SHG समूह बनाएं।","नियमित बचत और बैठक के 3 माह बाद रिवाल्विंग फंड और कम ब्याज पर ऋण प्राप्त करें।"],"rules":[{"field":"rural","op":"eq","value":true,"label":"ग्रामीण क्षेत्र के निवासी"}],"sourceUrl":"https://aajeevika.mp.gov.in/","applicationUrl":"https://aajeevika.mp.gov.in/","sourceNotes":"DAY-NRLM एवं राज्य ग्रामीण आजीविका मिशन अंतर्गत संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-kaushal-samvardhan-yojana','{"slug":"mukhyamantri-kaushal-samvardhan-yojana","title":"मुख्यमंत्री कौशल संवर्धन योजना","english":"Mukhyamantri Kaushal Samvardhan Yojana MMKSY","category":"shiksha","state":"madhya-pradesh","summary":"मध्य प्रदेश के 15 से 35 वर्ष के युवाओं को बाजार मांग अनुरूप आधुनिक ट्रेड्स में दक्ष बनाना।","benefit":"NSQF मानकों पर निःशुल्क अल्पकालीन आवासीय/गैर-आवासीय तकनीकी कौशल प्रशिक्षण व रोज़गार सहायता","department":"तकनीकी शिक्षा, कौशल विकास एवं रोज़गार विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 न्यूनतम 8वीं/10वीं/12वीं अंकसूची","🏠 मूल निवास प्रमाण पत्र","🏦 स्वयं का बैंक खाता"],"steps":["मध्य प्रदेश राज्य कौशल विकास मिशन पोर्टल पर ऑनलाइन पंजीयन करें।","पसंदीदा ट्रेड व प्रशिक्षण केंद्र का चयन करें।","प्रशिक्षण एवं मूल्यांकन उपरांत राष्ट्रीय प्रमाण पत्र व जॉब फेयर में रोज़गार पाएं।"],"rules":[{"field":"age","op":"gte","value":15,"label":"आयु 15 से 35 वर्ष"},{"field":"age","op":"lte","value":35,"label":"अधिकतम 35 वर्ष"}],"sourceUrl":"https://ssdm.mp.gov.in/","applicationUrl":"https://ssdm.mp.gov.in/","sourceNotes":"कौशल विकास विभाग MP द्वारा युवाओं को रोजगारपरक हुनर देने हेतु निःशुल्क योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-yuva-udyami-yojana','{"slug":"mukhyamantri-yuva-udyami-yojana","title":"मध्यप्रदेश मुख्यमंत्री युवा उद्यमी योजना","english":"Mukhyamantri Yuva Udyami Yojana Enterprise Loan","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के 10वीं पास युवाओं को नए विनिर्माण या सेवा उद्यम स्थापित करने हेतु बड़ा ऋण और वित्तीय प्रोत्साहन।","benefit":"विनिर्माण एवं सेवा उद्योग हेतु ₹10 लाख से ₹2 करोड़ तक बैंक ऋण, 5% ब्याज अनुदान एवं 15% मार्जिन मनी सब्सिडी","department":"सूक्ष्म, लघु एवं मध्यम उद्यम विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 न्यूनतम 10वीं पास अंकसूची","🏠 MP मूल निवास प्रमाण पत्र","📑 विस्तृत प्रोजेक्ट रिपोर्ट (DPR)","🏦 बैंक सहमति पत्र"],"steps":["SAMAST पोर्टल पर विस्तृत DPR और कोटेशन के साथ ऑनलाइन आवेदन करें।","टास्क फोर्स समिति द्वारा साक्षात्कार उपरांत बैंक को प्रकरण भेजा जाता है।","ऋण स्वीकृति के बाद 5 वर्षों तक प्रतिवर्ष 5% ब्याज अनुदान मिलता है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 40 वर्ष"},{"field":"age","op":"lte","value":40,"label":"अधिकतम 40 वर्ष"}],"sourceUrl":"https://msme.mponline.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"MSME विभाग MP द्वारा युवा उद्यमियों को उद्योग स्थापना हेतु वित्तीय सहायता।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-mazdoor-suraksha-yojana','{"slug":"mukhyamantri-mazdoor-suraksha-yojana","title":"मुख्यमंत्री मज़दूर सुरक्षा योजना","english":"Mukhyamantri Mazdoor Suraksha Yojana Landless Labor","category":"rojgar","state":"madhya-pradesh","summary":"भूमिहीन ग्रामीण कृषि श्रमिकों और उनके परिवार के सदस्यों को सामाजिक सुरक्षा और संकट के समय आर्थिक संबल प्रदान करने वाली योजना।","benefit":"ग्रामीण खेतिहर मजदूरों को विवाह सहायता, मातृत्व अवकाश लाभ, छात्रवृत्ति एवं मृत्यु उपरांत अंत्येष्टि सहायता","department":"श्रम विभाग / पंचायत एवं ग्रामीण विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 मजदूर सुरक्षा कार्ड / पंजीयन","🏦 बैंक खाता विवरण","🏠 निवास प्रमाण पत्र"],"steps":["ग्राम पंचायत सचिव के माध्यम से मजदूर सुरक्षा पंजीयन फॉर्म जमा करें।","कार्ड बनने के बाद मातृत्व सहायता, विवाह या छात्रवृत्ति के लिए संबंधित आवेदन करें।"],"rules":[{"field":"occupation","op":"eq","value":"worker","label":"भूमिहीन ग्रामीण कृषि मजदूर"}],"sourceUrl":"https://labour.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"श्रम विभाग MP द्वारा असंगठित ग्रामीण मजदूरों के लिए कल्याणकारी योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('nishaktjan-vivah-protsahan-yojana','{"slug":"nishaktjan-vivah-protsahan-yojana","title":"नि:शक्तजनों हेतु विवाह प्रोत्साहन योजना","english":"Nishaktjan Vivah Protsahan Disabled Marriage Aid","category":"mahila","state":"madhya-pradesh","summary":"यदि विवाह में वर या वधू में से कोई एक अथवा दोनों 40% या अधिक दिव्यांग हैं, तो उन्हें सुखद दांपत्य जीवन प्रारंभ करने हेतु ₹2 लाख का प्रोत्साहन।","benefit":"दिव्यांग दंपति के विवाह पर ₹2,00,000 (दो लाख रुपये) की एकमुश्त आर्थिक सहायता","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 वर-वधू दोनों का आधार कार्ड","📋 समग्र परिवार ID","🦽 40% या अधिक दिव्यांगता प्रमाण पत्र (UDID कार्ड)","💍 विवाह प्रमाण पत्र / सामूहिक विवाह प्रमाण","🏦 संयुक्त या लाभार्थी का बैंक खाता"],"steps":["विवाह संपन्न होने के 1 वर्ष के भीतर जनपद पंचायत या जिला दिव्यांग पुनर्वास केंद्र में आवेदन करें।","उप-संचालक सामाजिक न्याय द्वारा भौतिक सत्यापन के बाद ₹2 लाख की राशि सीधे खाते में अंतरित होती है।"],"rules":[],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा दिव्यांग पुनर्वास एवं सामाजिक समावेशन हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-bal-hriday-upchar-yojana','{"slug":"mukhyamantri-bal-hriday-upchar-yojana","title":"मुख्य मंत्री बाल ह्रदय उपचार योजना","english":"Mukhyamantri Bal Hriday Upchar Child Heart Surgery","category":"swasthya","state":"madhya-pradesh","summary":"0 से 18 वर्ष तक के बच्चों में दिल में छेद या अन्य गंभीर हृदय विकारों के लिए देश के प्रतिष्ठित सुपर स्पेशलिटी अस्पतालों में निःशुल्क ऑपरेशन।","benefit":"जन्मजात हृदय रोग से पीड़ित बच्चों की ₹1.5 लाख से ₹2 लाख तक की सर्जरी/उपचार पूरी तरह निःशुल्क","department":"लोक स्वास्थ्य एवं परिवार कल्याण विभाग, मध्य प्रदेश","documents":["🪪 बच्चे और माता-पिता का आधार कार्ड","📋 समग्र परिवार ID","🏥 सरकारी बाल रोग विशेषज्ञ या मेडिकल कॉलेज की 2D इको रिपोर्ट","🏠 मूल निवास प्रमाण पत्र","💰 आय प्रमाण पत्र (BPL या ₹1.5 लाख तक)"],"steps":["जिला मुख्य चिकित्सा एवं स्वास्थ्य अधिकारी (CMHO) कार्यालय में आवेदन और इको रिपोर्ट जमा करें।","विशेषज्ञ समिति द्वारा परीक्षण के बाद सूचीबद्ध हृदय अस्पताल में ऑपरेशन हेतु रेफरल दिया जाता है।","अस्पताल में भर्ती, जांच, सर्जरी, दवाएं और भोजन सब निःशुल्क रहता है।"],"rules":[{"field":"age","op":"lte","value":18,"label":"जन्म से 18 वर्ष तक के बच्चे"}],"sourceUrl":"https://health.mp.gov.in/","applicationUrl":"https://health.mp.gov.in/","sourceNotes":"स्वास्थ्य विभाग MP द्वारा बाल मृत्यु दर घटाने हेतु सुपर-स्पेशलिटी योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('iklauti-beti-scholarship-yojana','{"slug":"iklauti-beti-scholarship-yojana","title":"मध्य प्रदेश इकलौती बेटी छात्रवृत्ति योजना","english":"MP Iklauti Beti Chatravriti Single Girl Child","category":"shiksha","state":"madhya-pradesh","summary":"माता-पिता की एकमात्र संतान (इकलौती बेटी) होने पर उच्च शिक्षा निरंतर जारी रखने हेतु प्रोत्साहन व सहायता राशि।","benefit":"उच्च शिक्षा, कॉलेज और विश्वविद्यालय में प्रवेश लेने वाली इकलौती बेटियों को वित्तीय छात्रवृत्ति सहायता","department":"उच्च शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 कॉलेज प्रवेश रसीद व पूर्व कक्षा अंकसूची","📜 माता-पिता का शपथ पत्र (एकमात्र संतान होने का प्रमाण)","🏦 छात्रा का स्वयं का बैंक खाता"],"steps":["मध्य प्रदेश स्टेट स्कॉलरशिप पोर्टल (scholarshipportal.mp.nic.in) पर ऑनलाइन पंजीयन करें।","संबंधित कॉलेज प्राचार्य से दस्तावेज सत्यापित कराएं।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"माता-पिता की इकलौती बेटी (छात्रा)"},{"field":"occupation","op":"eq","value":"student","label":"कॉलेज/उच्च शिक्षा में अध्ययनरत"}],"sourceUrl":"https://scholarshipportal.mp.nic.in/","applicationUrl":"https://scholarshipportal.mp.nic.in/","sourceNotes":"उच्च शिक्षा विभाग MP द्वारा बालिका शिक्षा को प्रोत्साहन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('gopal-protsahan-yojana','{"slug":"gopal-protsahan-yojana","title":"मध्य प्रदेश गोपाल प्रोत्साहन योजना","english":"Gopal Protsahan Yojana Milk Production Competition","category":"kisan","state":"madhya-pradesh","summary":"देसी नस्ल (गीर, साहीवाल, थारपारकर, मालवी, निमाड़ी) की गायों व उन्नत भैंसों के संरक्षण व दुग्ध उत्पादन क्षमता वृद्धि हेतु प्रतियोगिता पुरस्कार।","benefit":"अधिक दुग्ध उत्पादन वाली भारतीय नस्ल की गाय/भैंस पालकों को ₹10,000 से ₹50,000 तक नकद पुरस्कार","department":"पशुपालन एवं डेयरी विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🐄 पशु का टैग नंबर व पशु आरोग्य प्रमाण","🏦 बैंक पासबुक"],"steps":["विकासखंड पशु चिकित्सा अधिकारी के पास दुग्ध उत्पादन प्रतियोगिता हेतु पंजीयन कराएं।","विभागीय समिति द्वारा 3 समय दुग्ध दोहन माप के आधार पर विजेता घोषित होने पर पुरस्कार राशि पाएं।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"देसी दुधारू पशुपालक कृषक"}],"sourceUrl":"https://mpdairyfed.mp.gov.in/","applicationUrl":"https://dahd.nic.in/","sourceNotes":"पशुपालन विभाग MP द्वारा भारतीय गोवंश संवर्धन हेतु वार्षिक योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-avivahit-pension-yojana','{"slug":"mukhyamantri-avivahit-pension-yojana","title":"मुख्यमंत्री अविवाहित पेंशन योजना","english":"Mukhyamantri Avivahit Pension Yojana Single Women","category":"pension","state":"madhya-pradesh","summary":"मध्य प्रदेश की 50 वर्ष से अधिक आयु की अविवाहित कल्याणी महिलाओं को वित्तीय संबल और गरिमापूर्ण जीवन जीने के लिए पेंशन सहायता।","benefit":"50 वर्ष या अधिक आयु की अविवाहित महिलाओं को ₹600 प्रति माह नियमित सामाजिक सुरक्षा पेंशन","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏠 मूल निवास प्रमाण पत्र","📜 अविवाहित होने का स्व-घोषणा पत्र / पटवारी रिपोर्ट","🏦 स्वयं का बैंक खाता"],"steps":["ग्राम पंचायत या नगरीय निकाय में आवेदन जमा करें।","सत्यापन उपरांत ₹600 प्रतिमाह सीधे DBT द्वारा बैंक खाते में जमा होते हैं।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"50 वर्ष से अधिक आयु की अविवाहित महिला"},{"field":"age","op":"gte","value":50,"label":"न्यूनतम आयु 50 वर्ष"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा महिलाओं की सामाजिक सुरक्षा हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-asangathit-mazdoor-yojana','{"slug":"mukhyamantri-asangathit-mazdoor-yojana","title":"मुख्यमंत्री असंगठित मजदूर योजना","english":"Mukhyamantri Asangathit Mazdoor Suraksha Yojana","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के निर्माण, कृषि, घरेलू कामकाज और असंगठित क्षेत्र में कार्य करने वाले श्रमिकों को बहुआयामी सामाजिक सुरक्षा कवर।","benefit":"असंगठित श्रमिकों को दुर्घटना बीमा, चिकित्सा सहायता, प्रसूति सहायता और बच्चों की शिक्षा सहायता","department":"श्रम विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 असंगठित श्रमिक पंजीयन कार्ड","🏦 आधार लिंक बैंक खाता"],"steps":["संबल पोर्टल पर असंगठित श्रमिक के रूप में पंजीयन कराएं।","पावती और कार्ड प्राप्त कर विभागीय लाभ हेतु आवेदन करें।"],"rules":[{"field":"occupation","op":"eq","value":"worker","label":"असंगठित क्षेत्र के श्रमिक"}],"sourceUrl":"https://labour.mp.gov.in/","applicationUrl":"https://sambal.mp.gov.in/","sourceNotes":"श्रम विभाग MP द्वारा असंगठित वर्ग के लिए प्रमुख योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-swarojgar-yojana','{"slug":"mukhyamantri-swarojgar-yojana","title":"मध्य प्रदेश मुख्यमंत्री स्वरोज़गार योजना","english":"Mukhyamantri Swarojgar Yojana Self Employment Loan","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के सभी वर्गों के नागरिकों को स्वरोज़गार स्थापित करने के लिए वित्तीय ऋण और 5 वर्षों तक 5% ब्याज अनुदान।","benefit":"नया उद्यम शुरू करने हेतु ₹50,000 से ₹10 लाख तक बैंक ऋण एवं 30% (अधिकतम ₹2 लाख) मार्जिन मनी सब्सिडी","department":"सूक्ष्म, लघु एवं मध्यम उद्यम विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 न्यूनतम 5वीं पास अंकसूची","🏠 मूल निवास प्रमाण पत्र","📑 प्रोजेक्ट प्रोफाइल / कोटेशन","🏦 बैंक खाता पासबुक"],"steps":["SAMAST पोर्टल पर ऑनलाइन आवेदन प्रस्तुत करें।","जिला उद्योग केंद्र द्वारा जांच उपरांत बैंक को प्रकरण स्वीकृत हेतु भेजा जाता है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 45 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}],"sourceUrl":"https://msme.mponline.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"MSME विभाग MP द्वारा स्वरोज़गार संवर्धन योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-medhavi-vidyarthi-yojana','{"slug":"mukhyamantri-medhavi-vidyarthi-yojana","title":"मध्य प्रदेश मुख्यमंत्री मेधावी विद्यार्थी योजना","english":"Mukhyamantri Medhavi Vidyarthi Yojana MMVY","category":"shiksha","state":"madhya-pradesh","summary":"12वीं में MP बोर्ड में 70% या CBSE/ICSE में 85% अंक लाने वाले विद्यार्थियों की उच्च शिक्षा की पूरी फीस (लाखों रुपये) राज्य सरकार सीधे कॉलेज को देती है।","benefit":"इंजीनियरिंग, मेडिकल, लॉ और उच्च शिक्षा की पूरी शिक्षण शुल्क (ट्यूशन फीस) सरकार द्वारा वहन","department":"तकनीकी शिक्षा एवं कौशल विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 10वीं व 12वीं की अंकसूची","💰 आय प्रमाण पत्र (वार्षिक आय ₹6 लाख से कम)","📑 कॉलेज प्रवेश व फीस रसीद","🏦 छात्र का बैंक खाता"],"steps":["मेधावी विद्यार्थी पोर्टल पर ऑनलाइन आवेदन करें।","संस्थान द्वारा सत्यापन के बाद फीस सीधे संस्थान के खाते में अंतरित होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"12वीं में 70% (MPBSE) या 85% (CBSE) प्राप्त विद्यार्थी"}],"sourceUrl":"https://scholarshipportal.mp.nic.in/MedhaviChhatra/","applicationUrl":"https://scholarshipportal.mp.nic.in/MedhaviChhatra/","sourceNotes":"उच्च शिक्षा व तकनीकी शिक्षा विभाग MP द्वारा प्रमुख फ्लैगशिप योजना।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('kisan-kalyan-yojana','{"slug":"kisan-kalyan-yojana","title":"मध्य प्रदेश मुख्यमंत्री किसान कल्याण योजना","english":"Mukhyamantri Kisan Kalyan Yojana Financial Support","category":"kisan","state":"madhya-pradesh","summary":"मध्य प्रदेश के भू-अभिलेख पोर्टल SAARA पर पंजीकृत PM-KISAN पात्र किसान परिवारों को ₹2,000 की 3 समान किस्तों में सालाना ₹6,000 की सहायता।","benefit":"PM-KISAN लाभार्थी किसानों को ₹6,000 प्रति वर्ष अतिरिक्त (कुल ₹12,000 प्रति वर्ष दोनों योजनाओं से)","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 भूमि खसरा/खतौनी","🏦 बैंक पासबुक (DBT सक्रिय)"],"steps":["SAARA पोर्टल (saara.mp.gov.in) पर हल्का पटवारी द्वारा सत्यापन कराया जाता है।","पात्र पाए जाने पर राशि सीधे बैंक खाते में जमा होती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"PM-KISAN पंजीकृत किसान परिवार"}],"sourceUrl":"https://saara.mp.gov.in/","applicationUrl":"https://saara.mp.gov.in/","sourceNotes":"राजस्व एवं कृषि विभाग MP द्वारा किसानों को आर्थिक संबल।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('krishak-jeevan-kalyan-yojana','{"slug":"krishak-jeevan-kalyan-yojana","title":"मुख्यमंत्री कृषक जीवन कल्याण योजना","english":"Krishak Jeevan Kalyan Yojana Accident Compensation","category":"kisan","state":"madhya-pradesh","summary":"खेत में जुताई, थ्रेशिंग, कीटनाशक छिड़काव, बिजली का करंट लगने या कुएं में गिरने से दुर्घटना होने पर त्वरित वित्तीय राहत।","benefit":"कृषि कार्य के दौरान दुर्घटना/मृत्यु होने पर किसान या कृषि मजदूर के आश्रितों को ₹4 लाख तक आर्थिक सहायता","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 खसरा नकल / कृषि मजदूर प्रमाण","🏥 डॉक्टर की मेडिकल रिपोर्ट / पोस्टमार्टम रिपोर्ट","📑 पुलिस पंचनामा / FIR"],"steps":["दुर्घटना के 30 दिन के भीतर तहसील कार्यालय या उप-संचालक कृषि को आवेदन प्रस्तुत करें।","जांच उपरांत अनुग्रह राशि सीधे नामिनी के खाते में अंतरित होती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"कृषक अथवा कृषि मजदूर"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://mpkrishi.mp.gov.in/","sourceNotes":"कृषि विभाग MP द्वारा खेत-खलिहान दुर्घटना सुरक्षा योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-yuva-internship-yojana','{"slug":"mukhyamantri-yuva-internship-yojana","title":"मुख्यमंत्री युवा इंटर्नशिप योजना","english":"Mukhyamantri Yuva Internship Yojana Jan Sewa Mitra","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के प्रत्येक विकासखंड में युवाओं को शासन की फ्लैगशिप योजनाओं के क्रियान्वयन और आमजन तक पहुंचाने हेतु इंटर्नशिप अवसर।","benefit":"युवाओं को मुख्यमंत्री जनसेवा मित्र के रूप में ₹8,000 प्रति माह स्टाइपेंड एवं सरकारी योजनाओं का फील्ड अनुभव","department":"योजना, आर्थिक एवं सांख्यिकी विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 स्नातक/स्नातकोत्तर डिग्री अंकसूची","🏠 MP मूल निवास प्रमाण पत्र","🏦 बैंक खाता पासबुक"],"steps":["MP e-Service पोर्टल पर इंटर्नशिप विज्ञप्ति आने पर ऑनलाइन आवेदन करें।","मेरिट व साक्षात्कार आधार पर चयन होने पर 6 माह से 1 वर्ष के लिए जनसेवा मित्र बनें।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 29 वर्ष"},{"field":"age","op":"lte","value":29,"label":"अधिकतम 29 वर्ष"}],"sourceUrl":"https://mmsky.mp.gov.in/","applicationUrl":"https://mmsky.mp.gov.in/","sourceNotes":"राज्य नीति एवं योजना आयोग MP द्वारा युवा नेतृत्व विकास कार्यक्रम।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('madhya-pradesh-ladli-behna-yojana','{"slug":"madhya-pradesh-ladli-behna-yojana","title":"मध्यप्रदेश मुख्यमंत्री लाड़ली बहना योजना","english":"Mukhyamantri Ladli Behna Yojana Monthly DBT","category":"mahila","state":"madhya-pradesh","summary":"मध्य प्रदेश की 21 से 60 वर्ष आयु की विवाहित, विधवा, तलाकशुदा और परित्यक्ता बहनों को आर्थिक रूप से स्वावलंबी बनाने की ऐतिहासिक योजना।","benefit":"पात्र विवाहित महिलाओं को ₹1,250 से ₹1,500 प्रति माह सीधे आधार-लिंक बैंक खाते में DBT","department":"महिला एवं बाल विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड (मोबाइल नंबर लिंक)","📋 समग्र परिवार एवं सदस्य ID (e-KYC पूर्ण)","🏦 स्वयं का बैंक खाता (DBT इनेबल्ड)","🏠 मूल निवास प्रमाण"],"steps":["ग्राम पंचायत या वार्ड स्तर पर आयोजित विशेष शिविर में उपस्थित हों।","लाइव फोटो और बायोमेट्रिक सत्यापन के साथ फॉर्म भराएं।","पावती प्राप्त करें और हर माह की 10 तारीख को खाते में राशि प्राप्त करें।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"विवाहित, विधवा या परित्यक्ता महिला"},{"field":"age","op":"gte","value":21,"label":"न्यूनतम आयु 21 वर्ष"},{"field":"age","op":"lte","value":60,"label":"अधिकतम आयु 60 वर्ष"}],"sourceUrl":"https://cmladlibahna.mp.gov.in/","applicationUrl":"https://cmladlibahna.mp.gov.in/","sourceNotes":"WCD MP की फ्लैगशिप योजना। राज्य की 1.29 करोड़ से अधिक बहनें लाभान्वित।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sambal-do-yojana','{"slug":"sambal-do-yojana","title":"मुख्यमंत्री जन कल्याण (संबल 2.0) योजना","english":"Mukhyamantri Jan Kalyan Sambal 2 Yojana","category":"rojgar","state":"madhya-pradesh","summary":"असंगठित क्षेत्र के लाखों श्रमिकों को जन्म से लेकर मृत्यु तक हर संकट की घड़ी में सामाजिक व वित्तीय सुरक्षा कवच देने वाला संबल कार्ड।","benefit":"संबल कार्ड: दुर्घटना मृत्यु पर ₹4 लाख, सामान्य मृत्यु पर ₹2 लाख, मातृत्व सहायता ₹16,000, अंत्येष्टि ₹5,000","department":"श्रम विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID (e-KYC पूर्ण)","📱 समग्र लिंक मोबाइल नंबर","🏦 बैंक खाता पासबुक","📜 असंगठित श्रमिक होने का स्व-घोषणा पत्र"],"steps":["संबल 2.0 पोर्टल (sambal.mp.gov.in) पर समग्र ID से आवेदन दर्ज करें।","ग्राम पंचायत सचिव या वार्ड प्रभारी द्वारा सत्यापन उपरांत डिजिटल संबल कार्ड डाउनलोड करें।"],"rules":[{"field":"occupation","op":"eq","value":"worker","label":"असंगठित क्षेत्र के मजदूर (आयकरदाता न हों)"}],"sourceUrl":"https://sambal.mp.gov.in/","applicationUrl":"https://sambal.mp.gov.in/","sourceNotes":"श्रम विभाग MP की सबसे व्यापक सामाजिक सुरक्षा योजना।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('pratibha-kiran-yojana','{"slug":"pratibha-kiran-yojana","title":"मध्य प्रदेश प्रतिभा किरण योजना","english":"Pratibha Kiran Yojana Urban Girl Scholarship","category":"shiksha","state":"madhya-pradesh","summary":"शहरी गरीब परिवारों की होनहार बेटियों को उच्च शिक्षा और स्नातक की पढ़ाई निर्बाध जारी रखने हेतु छात्रवृत्ति सहायता।","benefit":"शहरी क्षेत्र की BPL छात्राओं को 12वीं में 60% अंक लाने पर कॉलेज पढ़ाई हेतु ₹5,000 प्रति वर्ष","department":"उच्च शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 12वीं की अंकसूची (न्यूनतम 60%)","💰 शहरी BPL राशन कार्ड","🏦 छात्रा का बैंक खाता"],"steps":["स्टेट स्कॉलरशिप पोर्टल पर प्रतिभा किरण योजना का चयन कर आवेदन करें।","कॉलेज प्राचार्य से सत्यापन के बाद छात्रवृत्ति बैंक खाते में आती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"शहरी क्षेत्र की BPL छात्राएं"},{"field":"occupation","op":"eq","value":"student","label":"कॉलेज में अध्ययनरत"}],"sourceUrl":"https://scholarshipportal.mp.nic.in/","applicationUrl":"https://scholarshipportal.mp.nic.in/","sourceNotes":"उच्च शिक्षा विभाग MP द्वारा शहरी बालिकाओं के लिए संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('yuva-swabhimaan-yojana','{"slug":"yuva-swabhimaan-yojana","title":"मध्य प्रदेश युवा स्वाभिमान योजना","english":"Yuva Swabhimaan Yojana Urban Youth Employment","category":"rojgar","state":"madhya-pradesh","summary":"शहरी कमजोर वर्ग के युवाओं को एक वर्ष में 100 दिन का अस्थायी रोज़गार और भविष्य के लिए व्यावसायिक प्रशिक्षण देने की योजना।","benefit":"शहरी बेरोजगार युवाओं को 100 दिन का मानदेय रोज़गार (₹4,000/माह स्टाइपेंड) एवं निःशुल्क कौशल प्रशिक्षण","department":"नगरीय विकास एवं आवास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏠 शहरी निकाय का निवास प्रमाण","💰 परिवार की वार्षिक आय ₹2 लाख से कम प्रमाण","🏦 बैंक पासबुक"],"steps":["युवा स्वाभिमान पोर्टल पर पंजीयन करें।","नगरीय निकाय द्वारा नगर पालिका/निगम के कार्यों में 100 दिन का कार्य व कौशल प्रशिक्षण दिया जाता है।"],"rules":[{"field":"age","op":"gte","value":21,"label":"आयु 21 से 30 वर्ष"},{"field":"age","op":"lte","value":30,"label":"अधिकतम 30 वर्ष"}],"sourceUrl":"https://mpurban.gov.in/","applicationUrl":"https://yuvaswabhimaan.mp.gov.in/","sourceNotes":"नगरीय विकास विभाग MP द्वारा शहरी युवाओं के संबल हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-scooty-yojana','{"slug":"mukhyamantri-scooty-yojana","title":"मध्य प्रदेश मुख्यमंत्री स्कूटी योजना","english":"Mukhyamantri Scooty Yojana School Topper Award","category":"shiksha","state":"madhya-pradesh","summary":"प्रत्येक सरकारी हायर सेकेंडरी स्कूल में 12वीं में प्रथम स्थान प्राप्त करने वाले एक छात्र और एक छात्रा को कॉलेज आवागमन हेतु स्कूटी प्रदान करना।","benefit":"शासकीय उच्चतर माध्यमिक विद्यालयों में 12वीं कक्षा में सर्वोच्च अंक (टॉप) लाने वाले छात्र-छात्राओं को निःशुल्क ई-स्कूटी/पेट्रोल स्कूटी","department":"स्कूल शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 12वीं बोर्ड अंकसूची (स्कूल टॉपर प्रमाण)","🪪 ड्राइविंग लाइसेंस या लर्नर लाइसेंस","🏦 बैंक पासबुक"],"steps":["स्कूल के प्राचार्य द्वारा टॉपर विद्यार्थियों की सूची विभाग को भेजी जाती है।","स्कूटी क्रय हेतु निर्धारित राशि (₹90,000 से ₹1,20,000) सीधे छात्र के बैंक खाते में DBT होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"शासकीय हायर सेकेंडरी स्कूल के 12वीं टॉपर छात्र-छात्रा"}],"sourceUrl":"https://educationportal.mp.gov.in/","applicationUrl":"https://educationportal.mp.gov.in/","sourceNotes":"स्कूल शिक्षा विभाग MP द्वारा मेधावी विद्यार्थियों को गतिशीलता प्रोत्साहन।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-solar-pump-yojana','{"slug":"mukhyamantri-solar-pump-yojana","title":"मध्य प्रदेश मुख्यमंत्री सोलर पंप योजना","english":"Mukhyamantri Solar Pump Yojana Farmers Subsidy","category":"kisan","state":"madhya-pradesh","summary":"बिजली विहीन या कम वोल्टेज वाले क्षेत्रों में किसानों को डीजल पंप के महंगे खर्च से मुक्ति दिलाकर सौर ऊर्जा आधारित सिंचाई सुविधा देना।","benefit":"खेतों में सिंचाई हेतु 90% तक सरकारी अनुदान पर 2 HP से 7.5 HP तक सोलर पंप स्थापना","department":"नवीन एवं नवकरणीय ऊर्जा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 सिंचित/असिंचित भूमि खसरा B1","💧 जल स्रोत उपलब्धता का प्रमाण","🏦 बैंक खाता पासबुक"],"steps":["cmsolarpump.mp.gov.in पोर्टल पर ऑनलाइन पंजीयन करें और कृषक अंश राशि जमा करें।","विभागीय दल द्वारा स्थल निरीक्षण के बाद सोलर पैनल और सबमर्सिबल पंप स्थापित किया जाता है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"कृषक जिनके पास निजी जल स्रोत हो"}],"sourceUrl":"https://cmsolarpump.mp.gov.in/","applicationUrl":"https://cmsolarpump.mp.gov.in/","sourceNotes":"MP ऊर्जा विकास निगम एवं नवीन एवं नवकरणीय ऊर्जा विभाग द्वारा संचालित।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-kaushal-apprentice-yojana','{"slug":"mukhyamantri-kaushal-apprentice-yojana","title":"मध्य प्रदेश मुख्यमंत्री कौशल अपरेंटिस योजना","english":"Mukhyamantri Kaushal Apprentice Yojana Skill","category":"rojgar","state":"madhya-pradesh","summary":"ITI, डिप्लोमा, इंजीनियरिंग और सामान्य स्नातकों को औद्योगिक प्रतिष्ठानों में वास्तविक कार्य अनुभव और मानदेय देकर स्थाई नौकरी के योग्य बनाना।","benefit":"उद्योगों में 1 वर्ष की ऑन-जॉब अपरेंटिसशिप के साथ ₹8,000 से ₹10,000 मासिक स्टाइपेंड","department":"तकनीकी शिक्षा, कौशल विकास एवं रोज़गार विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 ITI/डिप्लोमा/डिग्री अंकसूची","🏠 MP मूल निवास","🏦 बैंक खाता पासबुक"],"steps":["MMSKY पोर्टल पर अपरेंटिस के रूप में पंजीयन करें।","अपनी पसंद के संस्थान व ट्रेड में आवेदन करें और साक्षात्कार उपरांत ट्रेनिंग प्रारंभ करें।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 29 वर्ष"},{"field":"age","op":"lte","value":29,"label":"अधिकतम 29 वर्ष"}],"sourceUrl":"https://mmsky.mp.gov.in/","applicationUrl":"https://mmsky.mp.gov.in/","sourceNotes":"कौशल विकास विभाग MP द्वारा युवाओं को उद्योग-उन्मुख बनाने हेतु योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-nikah-yojana','{"slug":"mukhyamantri-nikah-yojana","title":"मध्य प्रदेश मुख्यमंत्री निकाह योजना","english":"Mukhyamantri Nikah Yojana Minority Marriage Aid","category":"mahila","state":"madhya-pradesh","summary":"सामूहिक निकाह कार्यक्रमों के माध्यम से मुस्लिम व अन्य अल्पसंख्यक समाज के जरूरतमंद परिवारों की बेटियों के विवाह हेतु वित्तीय सहायता।","benefit":"अल्पसंख्यक निर्धन परिवारों की कन्याओं, विधवाओं और तलाकशुदा महिलाओं के निकाह पर ₹55,000 सहायता","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 वर और वधू का आधार कार्ड","📋 समग्र परिवार ID","🏠 मूल निवास प्रमाण पत्र","💰 BPL राशन कार्ड या आय प्रमाण पत्र","🎂 आयु प्रमाण पत्र (वर 21+, वधू 18+)","🏦 वधू का बैंक खाता"],"steps":["सामूहिक निकाह आयोजन समिति या नगर निकाय/जनपद में निर्धारित तिथि से पूर्व आवेदन जमा करें।","निकाह संपन्न होने के बाद ₹49,000 वधू के खाते में DBT किए जाते हैं।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"अल्पसंख्यक निर्धन कन्याएं/कल्याणी"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा सामूहिक निकाह में आर्थिक सहायता।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('atal-kisan-jyoti-yojana','{"slug":"atal-kisan-jyoti-yojana","title":"मध्य प्रदेश अटल किसान ज्योति योजना","english":"Atal Kisan Jyoti Yojana Subsidized Farm Power","category":"kisan","state":"madhya-pradesh","summary":"मध्य प्रदेश के लाखों अन्नदाताओं को सिंचाई के लिए निर्बाध और अत्यंत रियायती दरों पर बिजली उपलब्ध कराने वाली योजना।","benefit":"10 हॉर्सपावर तक के कृषि पंपों के लिए फ्लैट रेट पर सस्ती बिजली एवं किसानों को भारी सब्सिडी","department":"ऊर्जा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 कृषि पंप कनेक्शन बिल / उपभोक्ता क्रमांक","🌾 खसरा नकल"],"steps":["विद्युत वितरण कंपनी के नजदीकी वितरण केंद्र पर संपर्क कर कनेक्शन की स्थिति जांचें।","सब्सिडी स्वतः बिजली बिल में समायोजित होकर आती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"कृषि पंप उपभोक्ता किसान"}],"sourceUrl":"https://energy.mp.gov.in/","applicationUrl":"https://energy.mp.gov.in/","sourceNotes":"ऊर्जा विभाग MP द्वारा किसानों को सस्ती बिजली देने हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('shramik-sewa-prasuti-sahayata-yojana','{"slug":"shramik-sewa-prasuti-sahayata-yojana","title":"मुख्यमंत्री श्रमिक सेवा प्रसूति सहायता योजना","english":"Shramik Prasuti Sahayata Maternity Benefit MP","category":"mahila","state":"madhya-pradesh","summary":"असंगठित महिला श्रमिकों को गर्भावस्था में आराम और नवजात शिशु के पोषण के लिए प्रसव काल में मजदूरी की क्षतिपूर्ति सहायता।","benefit":"गर्भवती महिला श्रमिकों को ₹16,000 की नकद सहायता (प्रसव पूर्व जांच पर ₹4,000 + प्रसव उपरांत ₹12,000)","department":"लोक स्वास्थ्य एवं परिवार कल्याण विभाग / श्रम विभाग, मध्य प्रदेश","documents":["🪪 माता और पिता का आधार कार्ड","📋 समग्र परिवार ID","📜 संबल कार्ड या असंगठित श्रमिक पंजीयन","🏥 शासकीय स्वास्थ्य केंद्र का MCP कार्ड (मातृ एवं बाल सुरक्षा कार्ड)","🏦 महिला का बैंक खाता"],"steps":["गर्भावस्था के प्रथम 3-4 माह में नजदीकी आंगनवाड़ी या प्राथमिक स्वास्थ्य केंद्र में पंजीयन कराएं।","कम से कम 4 प्रसव पूर्व जांच (ANC) और शासकीय अस्पताल में प्रसव कराने पर सहायता राशि दो किस्तों में मिलती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"पंजीकृत महिला श्रमिक अथवा श्रमिक की पत्नी"}],"sourceUrl":"https://health.mp.gov.in/","applicationUrl":"https://sambal.mp.gov.in/","sourceNotes":"स्वास्थ्य एवं श्रम विभाग MP द्वारा सुरक्षित मातृत्व संवर्धन योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-jeevan-janani-yojana','{"slug":"mukhyamantri-jeevan-janani-yojana","title":"मध्य प्रदेश मुख्यमंत्री जीवन जननी योजना","english":"Mukhyamantri Jeevan Janani Yojana Pregnancy Care","category":"mahila","state":"madhya-pradesh","summary":"गर्भावस्था के दौरान बेहतर खानपान, एनीमिया रोकथाम और सुरक्षित संस्थागत प्रसव को बढ़ावा देने के लिए आर्थिक संबल।","benefit":"गर्भवती महिलाओं को पोषण आहार हेतु ₹4,000 की वित्तीय सहायता सीधे बैंक खाते में","department":"लोक स्वास्थ्य एवं परिवार कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏥 सरकारी अस्पताल की ANC जांच पर्ची","🏦 आधार लिंक बैंक खाता"],"steps":["नजदीकी शासकीय अस्पताल या स्वास्थ्य केंद्र में गर्भधारण का समय पर पंजीयन कराएं।","आवश्यक जांचें पूर्ण होने पर पोषण सहायता राशि बैंक खाते में भेजी जाती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"गर्भवती महिलाएं"}],"sourceUrl":"https://health.mp.gov.in/","applicationUrl":"https://health.mp.gov.in/","sourceNotes":"स्वास्थ्य विभाग MP द्वारा मातृ-शिशु पोषण सुधार हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('nari-samman-yojana','{"slug":"nari-samman-yojana","title":"मध्य प्रदेश नारी सम्मान योजना","english":"Nari Samman Yojana Women Financial Security","category":"mahila","state":"madhya-pradesh","summary":"महिलाओं को महंगाई से राहत, सामाजिक सुरक्षा और आर्थिक स्वतंत्रता प्रदान करने के उद्देश्य से शुरू की गई सहायता योजना।","benefit":"प्रदेश की पात्र महिलाओं को ₹1,500 प्रति माह आर्थिक सहायता एवं ₹500 में घरेलू गैस सिलिंडर सुविधा","department":"महिला एवं बाल विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र परिवार ID","🏠 मध्य प्रदेश मूल निवास प्रमाण पत्र","🏦 महिला का स्वयं का बैंक खाता","📱 मोबाइल नंबर"],"steps":["विभागीय कैंप अथवा अधिकृत पोर्टल पर निर्धारित प्रारूप में आवेदन पत्र प्रस्तुत करें।","सत्यापन उपरांत पात्र बहनों के बैंक खाते में मासिक सहायता अंतरित होती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"मध्य प्रदेश की निवासी महिलाएं"}],"sourceUrl":"https://mpwcdmis.gov.in/","applicationUrl":"https://mpwcdmis.gov.in/","sourceNotes":"महिला सशक्तिकरण एवं परिवार संबल हेतु विशेष योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mp-seekho-kamao-yojana','{"slug":"mp-seekho-kamao-yojana","title":"मध्य प्रदेश मुख्यमंत्री सीखो-कमाओ योजना","english":"Mukhyamantri Seekho Kamao Yojana MMSKY Stipend","category":"rojgar","state":"madhya-pradesh","summary":"12वीं, ITI, डिप्लोमा और ग्रेजुएट युवाओं को आधुनिक औद्योगिक प्रतिष्ठानों में ऑन-जॉब ट्रेनिंग (OJT) देकर उन्हें तत्काल रोज़गार के लिए तैयार करना।","benefit":"युवाओं को उद्योगों में कौशल सीखने के साथ ₹8,000 से ₹10,000 मासिक स्टाइपेंड एवं SCVT/NCVT प्रमाण पत्र","department":"कौशल विकास एवं रोज़गार विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID (e-KYC सत्यापित)","🎓 12वीं/ITI/डिप्लोमा/स्नातक अंकसूची","🏦 आधार सीडेड बैंक खाता","📱 मोबाइल नंबर"],"steps":["MMSKY पोर्टल (mmsky.mp.gov.in) पर छात्र पंजीयन करें।","पसंदीदा कोर्स और प्रतिष्ठान चुनकर इंटरव्यू दें।","अनुबंध होने पर ट्रेनिंग शुरू करें; स्टाइपेंड का 75% सरकार और 25% कंपनी देती है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 29 वर्ष"},{"field":"age","op":"lte","value":29,"label":"अधिकतम 29 वर्ष"}],"sourceUrl":"https://mmsky.mp.gov.in/","applicationUrl":"https://mmsky.mp.gov.in/","sourceNotes":"कौशल विकास विभाग MP की सबसे सफल युवा रोजगार प्रशिक्षण योजना।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('kanya-abhibhavak-pension-yojana','{"slug":"kanya-abhibhavak-pension-yojana","title":"मध्य प्रदेश मुख्यमंत्री कन्या अभिभावक पेंशन योजना","english":"Kanya Abhibhavak Pension Yojana Parents Aid","category":"pension","state":"madhya-pradesh","summary":"ऐसे माता-पिता जिन्होंने केवल पुत्रियों को जन्म दिया और जिनका कोई जीवित पुत्र नहीं है, उन्हें वृद्धावस्था में सामाजिक सुरक्षा सम्मान।","benefit":"जिन दंपत्तियों की केवल कन्याएं हैं, उन्हें 60 वर्ष की आयु पूर्ण करने पर ₹600 प्रति माह पेंशन","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 माता-पिता का आधार कार्ड","📋 समग्र परिवार ID","🎂 आयु प्रमाण पत्र (60 वर्ष या अधिक)","📜 केवल कन्याएं होने का स्व-घोषणा पत्र / स्थानीय निकाय प्रमाण","🏦 बैंक पासबुक"],"steps":["ग्राम पंचायत सचिव या नगर पालिका कार्यालय में आवेदन जमा करें।","सत्यापन उपरांत नियमित मासिक पेंशन बैंक खाते में प्रारंभ होती है।"],"rules":[{"field":"age","op":"gte","value":60,"label":"आयु 60 वर्ष या अधिक (केवल पुत्रियों वाले माता-पिता)"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा बालिकाओं के प्रति सम्मान बढ़ाने हेतु संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('acharyashri-vidyasagar-gau-samvardhan-yojana','{"slug":"acharyashri-vidyasagar-gau-samvardhan-yojana","title":"मध्य प्रदेश आचार्य विद्यासागर गौ संवर्धन योजना","english":"Acharya Vidyasagar Gau Samvardhan Dairy Subsidy","category":"kisan","state":"madhya-pradesh","summary":"दूध उत्पादन में मध्य प्रदेश को अग्रणी बनाने और पशुपालकों की आय दोगुनी करने हेतु बैंक ऋण व भारी पूंजीगत सब्सिडी।","benefit":"5 या अधिक दुधारू गाय/भैंस डेयरी इकाई स्थापित करने पर सामान्य वर्ग को 50% एवं SC/ST को 75% तक अनुदान","department":"पशुपालन एवं डेयरी विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 न्यूनतम 1 एकड़ सिंचित कृषि भूमि (चारा उत्पादन हेतु)","📜 जाति प्रमाण पत्र (SC/ST के लिए)","🏦 बैंक पासबुक","📑 प्रोजेक्ट कोटेशन"],"steps":["पशु चिकित्सालय या पशुपालन विभाग के जिला कार्यालय में प्रोजेक्ट जमा करें।","बैंक द्वारा ऋण स्वीकृति उपरांत अनुदान राशि बैंक में मार्जिन मनी के रूप में जमा की जाती है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"पशुपालक कृषक"}],"sourceUrl":"https://mpdairyfed.mp.gov.in/","applicationUrl":"https://dahd.nic.in/","sourceNotes":"पशुपालन विभाग MP द्वारा श्वेत क्रांति और गौ संवर्धन हेतु योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('pashudhan-bima-yojana','{"slug":"pashudhan-bima-yojana","title":"मध्य प्रदेश पशुधन बीमा योजना","english":"Pashudhan Bima Yojana Cattle Insurance Subsidy","category":"kisan","state":"madhya-pradesh","summary":"बीमारी, दुर्घटना या आकाशीय बिजली से दुधारू पशु की असमय मृत्यु होने पर पशुपालक को भारी आर्थिक नुकसान से बचाने की बीमा योजना।","benefit":"दुधारू गाय, भैंस, बैल और अन्य पशुओं की मृत्यु पर सुरक्षा हेतु 70% सब्सिडी पर बीमा कवर","department":"पशुपालन एवं डेयरी विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🐄 पशु का स्वास्थ्य प्रमाण पत्र व कान का टैग","🏦 बैंक खाता पासबुक"],"steps":["नजदीकी पशु चिकित्सा अधिकारी से संपर्क कर पशु का स्वास्थ्य परीक्षण और टैगिंग कराएं।","मात्र 30% प्रीमियम देकर 1 से 3 वर्ष का बीमा कराएं।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"पशुपालक किसान"}],"sourceUrl":"https://mpdairyfed.mp.gov.in/","applicationUrl":"https://dahd.nic.in/","sourceNotes":"पशुधन बीमा योजना MP में प्रति परिवार अधिकतम 5 मवेशियों का बीमा अनुमन्य।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('dudharu-pashu-praday-yojana','{"slug":"dudharu-pashu-praday-yojana","title":"मध्य प्रदेश दुधारू पशु प्रदाय योजना","english":"Dudharu Pashu Praday Yojana Tribal Dairy Support","category":"kisan","state":"madhya-pradesh","summary":"विशेष रूप से कमजोर जनजातीय समूहों (PVTG) को नियमित आजीविका और कुपोषण से मुक्ति दिलाने हेतु दुधारू गाय अथवा भैंस प्रदाय करना।","benefit":"विशेष पिछड़ी जनजाति (बैगा, भारिया, सहरिया) के परिवारों को 2 दुधारू मवेशी 90% तक सरकारी अनुदान पर","department":"जनजातीय कार्य विभाग / पशुपालन विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 बैगा, भारिया या सहरिया जनजाति प्रमाण पत्र","🏦 बैंक खाता पासबुक","🖼️ पासपोर्ट फोटो"],"steps":["जनजातीय कार्य विभाग के विकासखंड कार्यालय में निर्धारित प्रपत्र में आवेदन करें।","पशु क्रय समिति द्वारा मवेशी बाजार से पशु खरीद कर हितग्राही को सौंपा जाता है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"बैगा, भारिया या सहरिया जनजाति परिवार"}],"sourceUrl":"https://tribal.mp.gov.in/","applicationUrl":"https://dahd.nic.in/","sourceNotes":"जनजातीय कार्य विभाग MP द्वारा कमजोर जनजातियों के आर्थिक उत्थान हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('pashu-chikitsa-ambulance-yojana','{"slug":"pashu-chikitsa-ambulance-yojana","title":"मध्य प्रदेश पशु चिकित्सा एम्बुलेंस योजना","english":"Pashu Chikitsa Ambulance Yojana 1962 Call Center","category":"kisan","state":"madhya-pradesh","summary":"बीमार पशु को अस्पताल लाने की परेशानी समाप्त करने के लिए आधुनिक चिकित्सा उपकरणों व दवाओं से युक्त मोबाइल वैन घर-घर पहुंचकर उपचार करती है।","benefit":"टोल फ्री नंबर 1962 पर कॉल करने पर घर पर चलित पशु चिकित्सा एम्बुलेंस, डॉक्टर और दवाएं उपलब्ध","department":"पशुपालन एवं डेयरी विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड या समग्र ID (पशुपालक का)","📱 कॉल करने हेतु मोबाइल नंबर"],"steps":["टोल फ्री नंबर 1962 डायल कर अपने बीमार पशु के लक्षण और गांव का पता दर्ज कराएं।","मोबाइल वैन डॉक्टर सहित मौके पर पहुंचकर निःशुल्क/नाममात्र शुल्क पर उपचार करती है।"],"rules":[],"sourceUrl":"https://dahd.nic.in/","applicationUrl":"https://dahd.nic.in/","sourceNotes":"पशुपालन विभाग MP द्वारा पशु संजीवनी 1962 सेवा के तहत पूरे प्रदेश में संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('youth-internship-professional-development','{"slug":"youth-internship-professional-development","title":"मध्य प्रदेश मुख्यमंत्री यूथ इंटर्नशिप फोर प्रोफेशनल डेवलपमेंट प्रोग्राम","english":"Youth Internship Professional Development Program","category":"rojgar","state":"madhya-pradesh","summary":"नीति विश्लेषण, डेटा मॉनिटरिंग और प्रशासनिक प्रक्रियाओं में प्रतिभाशाली युवाओं को सीधे राज्य शासन के साथ काम करने का अवसर।","benefit":"पेशेवर स्नातकों को सरकारी विकास परियोजनाओं में कार्य अनुभव, मेंटरशिप और ₹10,000 मासिक मानदेय","department":"योजना, आर्थिक एवं सांख्यिकी विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 स्नातकोत्तर/प्रोफेशनल डिग्री (MBA, MSW, B.Tech, आदि)","📑 रिज्यूमे और अनुभव प्रमाण पत्र"],"steps":["विभागीय पोर्टल पर ऑनलाइन आवेदन करें।","चयन परीक्षा एवं साक्षात्कार में सफल होने पर कलेक्ट्रेट या मंत्रालय से संबद्ध होकर कार्य करें।"],"rules":[{"field":"age","op":"gte","value":21,"label":"आयु 21 से 30 वर्ष"},{"field":"age","op":"lte","value":30,"label":"अधिकतम 30 वर्ष"}],"sourceUrl":"https://mmsky.mp.gov.in/","applicationUrl":"https://mmsky.mp.gov.in/","sourceNotes":"राज्य योजना आयोग MP द्वारा पेशेवर प्रतिभाओं को सुशासन से जोड़ने का प्रयास।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('gausevak-prashikshan-yojana','{"slug":"gausevak-prashikshan-yojana","title":"मध्य प्रदेश गौसेवक प्रशिक्षण योजना","english":"Gausevak Prashikshan Yojana Animal Husbandry Skill","category":"kisan","state":"madhya-pradesh","summary":"गांव स्तर पर निजी पशु स्वास्थ्य कार्यकर्ता (गौसेवक) तैयार करना, जिससे युवाओं को स्वरोज़गार मिले और पशुपालकों को द्वार पर सेवा।","benefit":"ग्रामीण युवकों को 6 माह का कृत्रिम गर्भाधान व प्राथमिक पशु उपचार प्रशिक्षण, प्रमाण पत्र और टूलकिट","department":"पशुपालन एवं डेयरी विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 न्यूनतम 10वीं पास अंकसूची","🏠 ग्रामीण मूल निवास प्रमाण पत्र","🏦 बैंक पासबुक"],"steps":["जिला उप-संचालक पशुपालन कार्यालय में प्रशिक्षण हेतु आवेदन पत्र जमा करें।","विभागीय प्रशिक्षण केंद्र में 6 माह का व्यावहारिक प्रशिक्षण पूरा करने पर प्रमाण पत्र व किट प्राप्त करें।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 35 वर्ष"},{"field":"age","op":"lte","value":35,"label":"अधिकतम 35 वर्ष"}],"sourceUrl":"https://mpdairyfed.mp.gov.in/","applicationUrl":"https://dahd.nic.in/","sourceNotes":"पशुपालन विभाग MP द्वारा ग्रामीण पशु सेवा नेटवर्क विस्तार हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('nishulk-cycle-vitaran-yojana','{"slug":"nishulk-cycle-vitaran-yojana","title":"मध्य प्रदेश निःशुल्क साइकिल वितरण योजना","english":"Nishulk Cycle Vitaran Yojana School Students","category":"shiksha","state":"madhya-pradesh","summary":"ऐसे छात्र जिनके गांव में माध्यमिक या हाई स्कूल नहीं है और उन्हें दूसरे गांव (न्यूनतम 2 किमी) पढ़ने जाना पड़ता है, उन्हें साइकिल दी जाती है।","benefit":"कक्षा 6वीं और 9वीं में अध्ययनरत छात्र-छात्राओं को विद्यालय आवागमन हेतु निःशुल्क साइकिल या ₹4,500 DBT","department":"स्कूल शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 स्कूल में प्रवेश प्रमाण / उपस्थिति","🏠 निवास और स्कूल के बीच दूरी प्रमाण पत्र","🏦 छात्र/अभिभावक का बैंक खाता"],"steps":["शाला के प्रधानाध्यापक द्वारा समग्र पोर्टल पर पात्र छात्रों की सूची दर्ज की जाती है।","डीबीटी के माध्यम से साइकिल क्रय हेतु राशि बैंक खाते में अंतरित होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"शासकीय स्कूल के कक्षा 6वीं या 9वीं के छात्र"}],"sourceUrl":"https://educationportal.mp.gov.in/","applicationUrl":"https://educationportal.mp.gov.in/","sourceNotes":"स्कूल शिक्षा विभाग MP द्वारा ड्रॉप-आउट दर घटाने हेतु योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mp-gaon-ki-beti-yojana','{"slug":"mp-gaon-ki-beti-yojana","title":"मध्य प्रदेश गांव की बेटी योजना","english":"MP Gaon Ki Beti Yojana Rural Girl Higher Education","category":"shiksha","state":"madhya-pradesh","summary":"गांव की होनहार बेटियों को उच्च शिक्षा में प्रवेश लेने हेतु प्रोत्साहित करने के लिए प्रति शैक्षणिक सत्र 10 माह तक नियमित छात्रवृत्ति।","benefit":"ग्रामीण क्षेत्र की 12वीं में प्रथम श्रेणी (60%+) उत्तीर्ण छात्राओं को कॉलेज पढ़ाई हेतु ₹500 प्रति माह (₹5,000/वर्ष)","department":"उच्च शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 12वीं बोर्ड की अंकसूची (न्यूनतम 60% अंक)","🏠 ग्राम पंचायत द्वारा जारी ''गांव की बेटी'' प्रमाण पत्र","📑 कॉलेज प्रवेश व फीस रसीद","🏦 छात्रा का स्वयं का बैंक खाता"],"steps":["कॉलेज में प्रवेश लेने के बाद स्टेट स्कॉलरशिप पोर्टल (scholarshipportal.mp.nic.in) पर पंजीयन करें।","गांव की बेटी प्रमाण पत्र अपलोड करें और कॉलेज स्तर पर सत्यापन कराएं।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"ग्रामीण क्षेत्र की प्रथम श्रेणी 12वीं पास छात्राएं"},{"field":"occupation","op":"eq","value":"student","label":"उच्च शिक्षा में प्रवेशित छात्राएं"}],"sourceUrl":"https://scholarshipportal.mp.nic.in/","applicationUrl":"https://scholarshipportal.mp.nic.in/","sourceNotes":"उच्च शिक्षा विभाग MP द्वारा ग्रामीण बालिकाओं के सशक्तिकरण हेतु प्रतिष्ठित योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('aahar-anudan-yojana','{"slug":"aahar-anudan-yojana","title":"मध्य प्रदेश आहार अनुदान योजना","english":"Aahar Anudan Yojana PVTG Nutrition Grant","category":"mahila","state":"madhya-pradesh","summary":"कुपोषण मुक्ति और स्वास्थ्य संवर्धन के लिए मध्य प्रदेश के चिन्हित जनजातीय जिलों की बहनों को बिना किसी शर्त के हर माह DBT सहायता।","benefit":"विशेष पिछड़ी जनजाति (बैगा, भारिया, सहरिया) की महिला मुखिया को प्रतिमाह ₹1,500 की पौष्टिक आहार सहायता सीधे बैंक खाते में","department":"जनजातीय कार्य विभाग, मध्य प्रदेश","documents":["🪪 महिला मुखिया का आधार कार्ड","📋 समग्र परिवार ID","📜 बैगा/भारिया/सहरिया जाति प्रमाण पत्र","🏦 स्वयं का बैंक खाता (आधार लिंक)","📱 मोबाइल नंबर"],"steps":["आदिम जाति कल्याण विभाग के पोर्टल या विकासखंड स्तर पर शिविर में पंजीयन कराएं।","सत्यापन उपरांत प्रति माह ₹1,500 सीधे बैंक खाते में अंतरित किए जाते हैं।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"बैगा, भारिया अथवा सहरिया जनजाति की महिला मुखिया"}],"sourceUrl":"https://tribal.mp.gov.in/","applicationUrl":"https://tribal.mp.gov.in/","sourceNotes":"जनजातीय कार्य विभाग MP द्वारा संचालित जीवन-दायिनी पोषण योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('ladli-behna-awas-yojana','{"slug":"ladli-behna-awas-yojana","title":"मध्य प्रदेश मुख्यमंत्री लाड़ली बहना आवास योजना","english":"Ladli Behna Awas Yojana Housing Grant","category":"awas","state":"madhya-pradesh","summary":"प्रधानमंत्री आवास योजना से छूटी हुई लाड़ली बहना लाभार्थी परिवारों को पक्के घर का अधिकार दिलाने वाली विशेष राज्य आवास योजना।","benefit":"बेघर व कच्चे मकानों में रहने वाली लाड़ली बहनों को पक्का मकान निर्माण हेतु ₹1,20,000 की वित्तीय सहायता","department":"पंचायत एवं ग्रामीण विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र परिवार ID","📜 लाड़ली बहना पंजीयन क्रमांक","🏠 वर्तमान कच्चे मकान का फोटो व भूमि विवरण","🏦 DBT सक्रिय बैंक खाता"],"steps":["ग्राम पंचायत स्तर पर आयोजित शिविर में निर्धारित आवेदन पत्र भरकर जमा करें।","जनपद पंचायत द्वारा पात्रता सूची का सत्यापन और जिओ-टैगिंग की जाती है।","किस्तवार राशि सीधे बैंक खाते में निर्माण प्रगति अनुसार अंतरित होती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"लाड़ली बहना लाभार्थी जिनके पास पक्का मकान नहीं है"}],"sourceUrl":"https://cmladlibahna.mp.gov.in/","applicationUrl":"https://cmladlibahna.mp.gov.in/","sourceNotes":"पंचायत एवं ग्रामीण विकास विभाग MP द्वारा आवास विहीन बहनों के लिए।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('akanksha-yojana','{"slug":"akanksha-yojana","title":"मध्य प्रदेश आकांक्षा योजना","english":"MP Akanksha Yojana Free National Coaching ST","category":"shiksha","state":"madhya-pradesh","summary":"जनजातीय वर्ग के होनहार विद्यार्थियों को देश के शीर्ष इंजीनियरिंग, मेडिकल और लॉ कॉलेजों में प्रवेश दिलाने हेतु प्रतिष्ठित कोचिंग संस्थानों से तैयारी।","benefit":"अनुसूचित जनजाति (ST) के मेधावी छात्रों को JEE, NEET और CLAT की भोपाल/इंदौर में पूर्णतः निःशुल्क आवासीय कोचिंग","department":"जनजातीय कार्य विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 ST डिजिटल जाति प्रमाण पत्र","🎓 10वीं बोर्ड परीक्षा अंकसूची (न्यूनतम 60% अंक)","🏦 छात्र का बैंक खाता"],"steps":["जनजातीय कार्य विभाग के पोर्टल पर आकांक्षा प्रवेश परीक्षा हेतु ऑनलाइन आवेदन करें।","राज्य स्तरीय प्रवेश परीक्षा में मेरिट के आधार पर चयनित होकर निःशुल्क कोचिंग व हॉस्टल पाएं।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"ST वर्ग के 10वीं/11वीं के छात्र"}],"sourceUrl":"https://tribal.mp.gov.in/","applicationUrl":"https://tribal.mp.gov.in/","sourceNotes":"जनजातीय कार्य विभाग MP द्वारा राष्ट्रीय स्तर की प्रतियोगी परीक्षाओं हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-gas-cylinder-subsidy-yojana','{"slug":"mukhyamantri-gas-cylinder-subsidy-yojana","title":"मध्य प्रदेश मुख्यमंत्री गैस सिलिंडर सब्सिडी योजना","english":"Mukhyamantri Gas Cylinder 450 Subsidy Yojana","category":"mahila","state":"madhya-pradesh","summary":"रसोई गैस के महंगे सिलिंडर से महिलाओं को राहत देकर धुआं-मुक्त स्वच्छ रसोई और स्वास्थ्य सुरक्षा प्रदान करने हेतु सब्सिडी योजना।","benefit":"लाड़ली बहनों एवं PM उज्ज्वला योजना की हितग्राही महिलाओं को मात्र ₹450 में घरेलू LPG गैस सिलिंडर","department":"खाद्य, नागरिक आपूर्ति एवं उपभोक्ता संरक्षण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🔥 LPG गैस कनेक्शन उपभोक्ता क्रमांक व एजेंसी का नाम","🏦 आधार लिंक बैंक खाता"],"steps":["लाड़ली बहना पोर्टल या ग्राम पंचायत में अपना LPG गैस कनेक्शन नंबर दर्ज कराएं।","बाजार मूल्य पर गैस रिफिल कराने पर शेष सब्सिडी राशि सीधे बैंक खाते में DBT हो जाती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"लाड़ली बहना अथवा उज्ज्वला योजना की महिला लाभार्थी"}],"sourceUrl":"https://cmladlibahna.mp.gov.in/","applicationUrl":"https://food.mp.gov.in/","sourceNotes":"खाद्य विभाग एवं WCD MP द्वारा ₹450 में गैस प्रदाय योजना।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('bal-aashirwad-yojana','{"slug":"bal-aashirwad-yojana","title":"मध्य प्रदेश मुख्यमंत्री बाल आशीर्वाद योजना","english":"Mukhyamantri Bal Aashirwad Yojana After Care","category":"mahila","state":"madhya-pradesh","summary":"अनाथ और बेसहारा बच्चों को बालिग होने के बाद समाज में पुनर्वास, उच्च शिक्षा और आत्मनिर्भरता स्थापित करने हेतु मासिक वित्तीय संबल।","benefit":"18 वर्ष पूर्ण कर बाल देखरेख संस्था से बाहर जाने वाले देखरेख-मुक्त बच्चों को ₹4,000 प्रति माह एवं व्यावसायिक शिक्षा शुल्क","department":"महिला एवं बाल विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 बाल देखरेख संस्था (CCI) का विमुक्ति प्रमाण पत्र","🎓 शैक्षणिक संस्थान में प्रवेश प्रमाण","🏦 बैंक पासबुक"],"steps":["जिला बाल संरक्षण इकाई (DCPU) के माध्यम से आवेदन करें।","सत्यापन उपरांत 24 वर्ष की आयु तक ₹4,000 प्रति माह आर्थिक सहायता मिलती है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 24 वर्ष"},{"field":"age","op":"lte","value":24,"label":"अधिकतम 24 वर्ष"}],"sourceUrl":"https://mpwcdmis.gov.in/","applicationUrl":"https://mpwcdmis.gov.in/","sourceNotes":"महिला एवं बाल विकास विभाग MP द्वारा आफ्टर-केयर सहायता।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('covid-19-bal-kalyan-yojana','{"slug":"covid-19-bal-kalyan-yojana","title":"मध्य प्रदेश मुख्यमंत्री कोविड-19 बाल कल्याण योजना","english":"Covid 19 Bal Kalyan Yojana Orphan Support","category":"mahila","state":"madhya-pradesh","summary":"कोरोना महामारी के दौरान अनाथ हुए बच्चों को भरण-पोषण, सुरक्षा और उज्ज्वल भविष्य देने हेतु ऐतिहासिक मानवीय पहल।","benefit":"कोविड में माता-पिता खो चुके अनाथ बच्चों को ₹5,000 प्रति माह पेंशन, निःशुल्क राशन और पहली से कॉलेज तक मुफ्त शिक्षा","department":"महिला एवं बाल विकास विभाग, मध्य प्रदेश","documents":["🪪 बच्चे का आधार कार्ड","📋 समग्र ID","🏥 माता-पिता दोनों का मृत्यु प्रमाण पत्र (कोविड संक्रमण से)","🏠 मूल निवास प्रमाण पत्र","🏦 बच्चे के नाम बैंक खाता"],"steps":["कलेक्टर कार्यालय अथवा जिला महिला एवं बाल विकास अधिकारी कार्यालय में आवेदन प्रस्तुत करें।","स्वीकृति उपरांत 21 वर्ष की आयु तक प्रति माह ₹5,000 पेंशन व राशन पात्रता पर्ची जारी होती है।"],"rules":[{"field":"age","op":"lte","value":21,"label":"कोविड में माता-पिता खो चुके 21 वर्ष से कम आयु के बच्चे"}],"sourceUrl":"https://mpwcdmis.gov.in/","applicationUrl":"https://mpwcdmis.gov.in/","sourceNotes":"WCD MP द्वारा संचालित विशेष बाल कल्याण योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('padho-aur-padhao-yojana','{"slug":"padho-aur-padhao-yojana","title":"मध्य प्रदेश पढ़ो और पढ़ाओ योजना","english":"Padho Aur Padhao Literacy Volunteer Scheme","category":"shiksha","state":"madhya-pradesh","summary":"उल्लास नव भारत साक्षरता कार्यक्रम के तहत ग्रामीण व शहरी क्षेत्रों में 15 वर्ष से अधिक आयु के असाक्षरों को बुनियादी साक्षरता और संख्यात्मक ज्ञान सिखाना।","benefit":"अक्षर साथी स्वयंसेवकों को निरक्षर वयस्कों को साक्षर बनाने पर प्रोत्साहन राशि, टीएलएम किट और प्रमाण पत्र","department":"स्कूल शिक्षा विभाग / राज्य शिक्षा केंद्र, मध्य प्रदेश","documents":["🪪 स्वयंसेवक और शिक्षार्थी का आधार कार्ड","📋 समग्र ID","🎓 स्वयंसेवक की न्यूनतम 10वीं पास अंकसूची"],"steps":["उल्लास (ULLAS) मोबाइल ऐप पर स्वयंसेवक (अक्षर साथी) के रूप में पंजीयन करें।","अपने क्षेत्र के असाक्षरों को पढ़ाएं और बुनियादी साक्षरता मूल्यांकन परीक्षा में शामिल कराएं।"],"rules":[],"sourceUrl":"https://educationportal.mp.gov.in/","applicationUrl":"https://educationportal.mp.gov.in/","sourceNotes":"राज्य शिक्षा केंद्र MP द्वारा संपूर्ण साक्षरता अभियान।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('ration-aapke-dwar-yojana','{"slug":"ration-aapke-dwar-yojana","title":"मध्य प्रदेश मुख्यमंत्री राशन आपके द्वार योजना","english":"Ration Aapke Dwar Tribal Doorstep Food Scheme","category":"khadya","state":"madhya-pradesh","summary":"मध्य प्रदेश के 89 जनजातीय विकासखंडों के निवासियों को राशन दुकान तक कई किलोमीटर पैदल चलने की परेशानी से मुक्ति दिलाकर वाहन से गांव में ही राशन देना।","benefit":"जनजातीय विकासखंडों के दूरस्थ गांवों में घर-घर (द्वार पर) खाद्यान्न (चावल, गेहूं, नमक) का निःशुल्क परिवहन व वितरण","department":"खाद्य, नागरिक आपूर्ति एवं उपभोक्ता संरक्षण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 राशन पात्रता पर्ची / समग्र ID","📱 आधार लिंक मोबाइल नंबर"],"steps":["गांव में निर्धारित वितरण दिवस पर राशन वाहन आने पर बायोमेट्रिक e-PoS मशीन पर अंगूठा लगाकर उचित मूल्य का राशन प्राप्त करें।"],"rules":[{"field":"rural","op":"eq","value":true,"label":"89 जनजातीय विकासखंडों के ग्रामीण परिवार"}],"sourceUrl":"https://food.mp.gov.in/","applicationUrl":"https://food.mp.gov.in/","sourceNotes":"खाद्य एवं नागरिक आपूर्ति विभाग MP द्वारा संचालित डोरस्टेप डिलीवरी।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('yuva-annadoot-yojana','{"slug":"yuva-annadoot-yojana","title":"मध्य प्रदेश मुख्यमंत्री युवा अन्नदूत योजना","english":"Mukhyamantri Yuva Annadoot Vehicle Loan Scheme","category":"khadya","state":"madhya-pradesh","summary":"उचित मूल्य दुकानों तक खाद्यान्न परिवहन का काम स्थानीय बेरोजगार युवाओं को सौंपकर उन्हें स्वरोज़गार और पक्की मासिक आय प्रदान करना।","benefit":"जनजातीय युवाओं को राशन परिवहन वाहन खरीदने हेतु ₹7.5 लाख तक बैंक ऋण, 3% ब्याज अनुदान एवं मार्जिन मनी सहायता","department":"खाद्य, नागरिक आपूर्ति एवं उपभोक्ता संरक्षण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 न्यूनतम 8वीं पास अंकसूची","🪪 भारी/मध्यम वाणिज्यिक वाहन ड्राइविंग लाइसेंस (LMV/HMV)","🏠 संबंधित सेक्टर का मूल निवासी प्रमाण पत्र"],"steps":["SAMAST पोर्टल पर युवा अन्नदूत योजना घटक में ऑनलाइन आवेदन करें।","कलेक्टर की अध्यक्षता वाली समिति द्वारा चयन होने पर वाहन खरीद हेतु ऋण व सब्सिडी जारी होती है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 45 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}],"sourceUrl":"https://food.mp.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"खाद्य विभाग MP द्वारा युवाओं के लिए आजीविका मॉडल।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mp-mukhyamantri-udyam-kranti-yojana','{"slug":"mp-mukhyamantri-udyam-kranti-yojana","title":"मध्य प्रदेश मुख्यमंत्री उद्यम क्रांति योजना","english":"Mukhyamantri Udyam Kranti Yojana Self Employment","category":"rojgar","state":"madhya-pradesh","summary":"मध्य प्रदेश के 12वीं पास युवाओं को बिना किसी बैंक गारंटी के स्वयं का उद्योग, स्टार्टअप या व्यवसाय शुरू करने के लिए सरकार द्वारा ऋण गारंटी और ब्याज सब्सिडी।","benefit":"विनिर्माण उद्योग हेतु ₹1 लाख से ₹50 लाख एवं सेवा/व्यवसाय हेतु ₹1 लाख से ₹25 लाख तक बैंक ऋण, 3% वार्षिक ब्याज अनुदान","department":"सूक्ष्म, लघु एवं मध्यम उद्यम विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 न्यूनतम 12वीं उत्तीर्ण अंकसूची","🏠 मूल निवास प्रमाण पत्र","📑 प्रोजेक्ट रिपोर्ट (DPR) एवं कोटेशन","🏦 बैंक खाता विवरण"],"steps":["MP Online SAMAST पोर्टल (samast.mponline.gov.in) पर ऑनलाइन पंजीयन करें।","प्रोजेक्ट रिपोर्ट अपलोड कर बैंक शाखा का चयन करें।","बैंक द्वारा ऋण स्वीकृति उपरांत 7 वर्षों तक 3% ब्याज अनुदान और ऋण गारंटी फीस शासन भरता है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 45 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}],"sourceUrl":"https://samast.mponline.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"MSME विभाग MP की सबसे बड़ी स्वरोज़गार योजना।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-krishak-udyami-yojana','{"slug":"mukhyamantri-krishak-udyami-yojana","title":"मध्य प्रदेश मुख्यमंत्री कृषक उद्यमी योजना","english":"Mukhyamantri Krishak Udyami Yojana Agro Business","category":"rojgar","state":"madhya-pradesh","summary":"कृषक परिवारों के युवाओं को कस्टम हायरिंग केंद्र, दाल मिल, तेल मिल, कोल्ड स्टोरेज, बेकरी और फूड प्रोसेसिंग यूनिट लगाने हेतु बड़ा ऋण और 5% ब्याज अनुदान।","benefit":"किसानों के बेटे-बेटियों को कृषि आधारित उद्योग हेतु ₹10 लाख से ₹2 करोड़ तक ऋण एवं 15% पूंजीगत अनुदान","department":"किसान कल्याण तथा कृषि विकास विभाग / MSME, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 माता/पिता के नाम कृषि भूमि का खसरा B1","🎓 न्यूनतम 10वीं पास अंकसूची","📑 विस्तृत प्रोजेक्ट रिपोर्ट (DPR)"],"steps":["SAMAST पोर्टल पर ऑनलाइन आवेदन करें।","जिला स्तरीय टास्क फोर्स समिति द्वारा अनुशंसा उपरांत बैंक से ऋण व सब्सिडी प्राप्त करें।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 45 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}],"sourceUrl":"https://msme.mponline.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"कृषि प्रसंस्करण और मूल्य संवर्धन को बढ़ावा देने हेतु विशेष योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-swarojgar-yojana-general','{"slug":"mukhyamantri-swarojgar-yojana-general","title":"मध्य प्रदेश मुख्यमंत्री स्वरोजगार योजना","english":"Mukhyamantri Swarojgar Yojana General Loan","category":"rojgar","state":"madhya-pradesh","summary":"सभी वर्गों के नागरिकों को खुद की दुकान, सर्विस सेंटर, वर्कशॉप या छोटा व्यवसाय स्थापित करने हेतु वित्तीय सहायता।","benefit":"सेवा एवं व्यापार क्षेत्र हेतु ₹50,000 से ₹10 लाख तक बैंक ऋण एवं 15% से 30% तक मार्जिन मनी सहायता","department":"सूक्ष्म, लघु एवं मध्यम उद्यम विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 न्यूनतम 5वीं पास अंकसूची","🏠 मूल निवास प्रमाण पत्र","🏦 बैंक खाता पासबुक"],"steps":["उद्योग विभाग के ऑनलाइन पोर्टल पर आवेदन करें।","सत्यापन उपरांत बैंक से ऋण और मार्जिन मनी अनुदान प्राप्त करें।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 45 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}],"sourceUrl":"https://msme.mponline.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"उद्योग संचालनालय MP द्वारा संचालित स्वरोज़गार योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-arthik-kalyan-tribal-yojana','{"slug":"mukhyamantri-arthik-kalyan-tribal-yojana","title":"मध्य प्रदेश मुख्यमंत्री आर्थिक कल्याण योजना (जनजातीय)","english":"Mukhyamantri Arthik Kalyan Tribal Micro Loan","category":"rojgar","state":"madhya-pradesh","summary":"जनजातीय वर्ग के अत्यंत गरीब लोगों को हाथ ठेला, साइकिल रिक्शा, सिलाई मशीन, बढ़ईगीरी आदि औजार खरीदकर आजीविका चलाने में मदद।","benefit":"अनुसूचित जनजाति (ST) के बीपीएल परिवारों को कम लागत के उपकरण/व्यवसाय हेतु ₹50,000 तक ऋण व 50% अनुदान","department":"जनजातीय कार्य विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 ST डिजिटल जाति प्रमाण पत्र","💰 BPL राशन कार्ड","🏦 बैंक पासबुक"],"steps":["जनजातीय कार्य विभाग के जिला कार्यालय में निर्धारित प्रपत्र में आवेदन करें।","सत्यापन उपरांत 50% सरकारी अनुदान सहित उपकरण हेतु बैंक ऋण जारी होता है।"],"rules":[{"field":"occupation","op":"eq","value":"self-employed","label":"ST वर्ग के BPL नागरिक"}],"sourceUrl":"https://tribal.mp.gov.in/","applicationUrl":"https://tribal.mp.gov.in/","sourceNotes":"जनजातीय कार्य विभाग MP द्वारा सूक्ष्म आजीविका संवर्धन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-yuva-udyami-general-yojana','{"slug":"mukhyamantri-yuva-udyami-general-yojana","title":"मध्य प्रदेश मुख्यमंत्री युवा उद्यमी योजना (सामान्य)","english":"Mukhyamantri Yuva Udyami General Big Industry","category":"rojgar","state":"madhya-pradesh","summary":"औद्योगिक उत्पादन, पैकेजिंग और असेंबलिंग इकाइयों की स्थापना हेतु प्रदेश के युवाओं को भारी वित्तीय सहायता।","benefit":"नवीन विनिर्माण उद्यमों हेतु ₹10 लाख से ₹1 करोड़ तक बैंक ऋण, 5% ब्याज अनुदान और मार्जिन मनी","department":"उद्योग संचालनालय, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 10वीं/12वीं अंकसूची","📑 उद्योग आधार / Udyam Registration","📑 DPR"],"steps":["उद्योग विभाग के पोर्टल पर विस्तृत कार्ययोजना के साथ आवेदन करें।","समिति द्वारा परीक्षण के बाद बैंक से ऋण स्वीकृत होता है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 40 वर्ष"},{"field":"age","op":"lte","value":40,"label":"अधिकतम 40 वर्ष"}],"sourceUrl":"https://msme.mponline.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"मध्य प्रदेश में विनिर्माण क्रांति लाने हेतु फ्लैगशिप योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
