INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('savitri-bai-phule-shg-yojana','{"slug":"savitri-bai-phule-shg-yojana","title":"मध्य प्रदेश सावित्री बाई फुले स्व-सहायता समूह योजना","english":"Savitri Bai Phule SHG Subsidy Loan Scheme","category":"mahila","state":"madhya-pradesh","summary":"ग्रामीण एवं शहरी महिलाओं के समूहों को खाद्य प्रसंस्करण, सिलाई, अगरबत्ती, हस्तशिल्प आदि उत्पाद बनाकर बाजार में बेचने हेतु आर्थिक सहायता।","benefit":"महिला स्व-सहायता समूहों (SHG) को माइक्रो एंटरप्राइज लगाने हेतु ₹2 लाख तक वित्तीय ऋण और 30% पूंजीगत अनुदान","department":"महिला एवं बाल विकास विभाग / राज्य आजीविका मिशन, मध्य प्रदेश","documents":["🪪 समूह की सभी सदस्यों का आधार कार्ड","📋 समग्र ID","🏦 समूह का बचत बैंक खाता व पासबुक","📝 समूह का प्रस्ताव व आजीविका कार्ययोजना"],"steps":["आजीविका मिशन के विकासखंड प्रबंधक या ग्राम संगठन से संपर्क करें।","समूह की ग्रेडिंग उपरांत वित्तीय सहायता और ब्याज अनुदान का लाभ लें।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"महिला स्व-सहायता समूह सदस्य"}],"sourceUrl":"https://aajeevika.mp.gov.in/","applicationUrl":"https://aajeevika.mp.gov.in/","sourceNotes":"महिला आजीविका स्वावलंबन हेतु सावित्री बाई फुले योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sant-ravidas-swarojgar-yojana','{"slug":"sant-ravidas-swarojgar-yojana","title":"मध्य प्रदेश संत रविदास स्वरोजगार योजना","english":"Sant Ravidas Swarojgar Yojana SC Entrepreneur","category":"rojgar","state":"madhya-pradesh","summary":"अनुसूचित जाति के युवाओं को बड़े उद्यम, विनिर्माण इकाई या सेवा प्रतिष्ठान स्थापित करने हेतु सरकार द्वारा ऋण गारंटी और ब्याज सब्सिडी।","benefit":"SC वर्ग के युवाओं को विनिर्माण हेतु ₹1 लाख से ₹50 लाख व सेवा क्षेत्र हेतु ₹25 लाख तक ऋण व 5% वार्षिक ब्याज अनुदान","department":"मध्य प्रदेश राज्य अनुसूचित जाति वित्त एवं विकास निगम","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 SC डिजिटल जाति प्रमाण पत्र","🎓 न्यूनतम 8वीं पास अंकसूची","📑 प्रोजेक्ट रिपोर्ट (DPR)","🏦 बैंक पासबुक"],"steps":["SAMAST पोर्टल पर संत रविदास स्वरोजगार योजना में आवेदन करें।","स्वीकृति उपरांत 7 वर्षों तक प्रतिवर्ष 5% ब्याज अनुदान राज्य सरकार सीधे बैंक को देती है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 45 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}],"sourceUrl":"https://scdevelopmentmp.nic.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"अनुसूचित जाति कल्याण विभाग MP द्वारा SC युवाओं के लिए शीर्ष उद्यम योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('dr-ambedkar-arthik-kalyan-yojana','{"slug":"dr-ambedkar-arthik-kalyan-yojana","title":"मध्य प्रदेश डॉ भीमराव अम्बेडकर आर्थिक कल्याण योजना","english":"Dr Ambedkar Arthik Kalyan Yojana SC Micro Business","category":"rojgar","state":"madhya-pradesh","summary":"SC वर्ग के गरीब लोगों को अपना छोटा व्यवसाय, मरम्मत दुकान, फल-सब्जी दुकान, टेलरिंग आदि शुरू करने हेतु बिना किसी जटिलता के त्वरित बैंक ऋण।","benefit":"अनुसूचित जाति (SC) के बीपीएल नागरिकों को कम लागत के औजार/व्यवसाय हेतु ₹10,000 से ₹1 लाख तक ऋण व 7% ब्याज अनुदान","department":"मध्य प्रदेश राज्य अनुसूचित जाति वित्त एवं विकास निगम","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 SC जाति प्रमाण पत्र","💰 BPL राशन कार्ड या आय प्रमाण पत्र","🏦 बैंक खाता पासबुक"],"steps":["SAMAST पोर्टल पर ऑनलाइन आवेदन प्रस्तुत करें।","निगम द्वारा प्रकरण बैंक को भेजा जाता है और 5 वर्षों तक 7% ब्याज अनुदान मिलता है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 55 वर्ष"},{"field":"age","op":"lte","value":55,"label":"अधिकतम 55 वर्ष"}],"sourceUrl":"https://scdevelopmentmp.nic.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"अनुसूचित जाति कल्याण विभाग MP द्वारा आर्थिक रूप से कमजोर SC वर्ग हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-aawasiya-bhu-adhikar-yojana','{"slug":"mukhyamantri-aawasiya-bhu-adhikar-yojana","title":"मध्य प्रदेश मुख्यमंत्री आवासीय भू-अधिकार योजना","english":"Mukhyamantri Aawasiya Bhu Adhikar Free Land Plot","category":"awas","state":"madhya-pradesh","summary":"ऐसे ग्रामीण परिवार जिनके पास रहने के लिए खुद का कोई पक्का मकान या जमीन नहीं है, उन्हें सरकार द्वारा गांव की आबादी भूमि पर मुफ्त आवासीय पट्टा देना।","benefit":"ग्रामीण क्षेत्रों में आवासहीन गरीब परिवारों को घर बनाने हेतु निःशुल्क 600 वर्गफीट आबादी आवासीय भूखंड का पट्टा","department":"राजस्व विभाग, मध्य प्रदेश","documents":["🪪 पति और पत्नी दोनों का आधार कार्ड","📋 समग्र परिवार ID","🏠 ग्रामीण मूल निवास प्रमाण पत्र","📜 भूमिहीन होने का स्व-घोषणा पत्र"],"steps":["SAARA पोर्टल (saara.mp.gov.in) पर ऑनलाइन आवेदन करें।","पटवारी और तहसीलदार द्वारा जांच उपरांत ग्राम सभा में दावा-आपत्ति का निराकरण होता है।","पात्र परिवारों को निःशुल्क भू-अधिकार पत्र (पट्टा) कलेक्टर द्वारा वितरित किया जाता है।"],"rules":[{"field":"rural","op":"eq","value":true,"label":"ग्रामीण क्षेत्र के आवासहीन निर्धन परिवार"}],"sourceUrl":"https://saara.mp.gov.in/","applicationUrl":"https://saara.mp.gov.in/","sourceNotes":"राजस्व विभाग MP द्वारा ग्रामीण गरीबों को पक्के घर की जमीन का मालिकाना हक।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('madhya-pradesh-vridhavastha-pension-yojana','{"slug":"madhya-pradesh-vridhavastha-pension-yojana","title":"मध्य प्रदेश वृद्धावस्था पेंशन योजना","english":"MP Vridhavastha Pension Yojana Indira Gandhi National","category":"pension","state":"madhya-pradesh","summary":"बुजुर्ग नागरिकों को जीवन यापन, दवा और दैनिक आवश्यकताओं के लिए नियमित आर्थिक सहायता देने वाली प्रमुख राष्ट्रीय व राज्य सामाजिक सुरक्षा योजना।","benefit":"60 वर्ष या अधिक आयु के गरीबी रेखा (BPL) के वृद्धजनों को ₹600 प्रति माह नियमित पेंशन (80 वर्ष से ऊपर ₹600)","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎂 आयु प्रमाण (वोटर आईडी/जन्म प्रमाण पत्र/10वीं अंकसूची)","💰 BPL राशन कार्ड","🏦 बैंक खाता पासबुक (आधार लिंक)"],"steps":["ग्राम पंचायत सचिव या नगर पालिका के वार्ड कार्यालय में समग्र पेंशन फॉर्म भरें।","सत्यापन उपरांत हर माह सीधे खाते में ₹600 की राशि अंतरित होती है।"],"rules":[{"field":"age","op":"gte","value":60,"label":"आयु 60 वर्ष या अधिक (BPL परिवार)"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP एवं भारत सरकार का संयुक्त पेंशन कार्यक्रम।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('madhya-pradesh-parityakta-pension-yojana','{"slug":"madhya-pradesh-parityakta-pension-yojana","title":"मध्य प्रदेश परित्यक्ता पेंशन योजना","english":"MP Parityakta Pension Yojana Abandoned Women Aid","category":"pension","state":"madhya-pradesh","summary":"पति द्वारा त्याग दी गई ऐसी महिलाएं जिनका कोई सहारा नहीं है, उन्हें सम्मानजनक जीवन जीने के लिए निरंतर मासिक आर्थिक मदद।","benefit":"पति द्वारा परित्यक्त (छोड़ी गई) बेसहारा महिलाओं को ₹600 प्रति माह सामाजिक सुरक्षा पेंशन","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 महिला का आधार कार्ड","📋 समग्र परिवार ID","📜 परित्यक्ता होने का प्रमाण (न्यायालय का आदेश या पंचनामा रिपोर्ट)","💰 BPL राशन कार्ड / आय प्रमाण पत्र","🏦 स्वयं का बैंक खाता"],"steps":["नजदीकी जनपद पंचायत या नगर पालिका कार्यालय में आवेदन जमा करें।","सत्यापन के उपरांत पेंशन की स्वीकृति आदेश जारी होता है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"परित्यक्ता (पति द्वारा छोड़ी गई) महिलाएं"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा निराश्रित महिलाओं के पुनर्वास हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-kalyani-pension-yojana','{"slug":"mukhyamantri-kalyani-pension-yojana","title":"मध्य प्रदेश मुख्यमंत्री कल्याणी पेंशन योजना","english":"Mukhyamantri Kalyani Pension Yojana Widow Support","category":"pension","state":"madhya-pradesh","summary":"पति की मृत्यु के उपरांत महिलाओं को आर्थिक सुरक्षा और सम्मान प्रदान करने हेतु मध्य प्रदेश सरकार द्वारा दी जाने वाली कल्याणी पेंशन।","benefit":"18 वर्ष या अधिक आयु की कल्याणी (विधवा) बहनों को ₹600 प्रति माह नियमित पेंशन","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏥 पति का मृत्यु प्रमाण पत्र","🏠 मूल निवास प्रमाण पत्र","🏦 महिला का आधार लिंक बैंक खाता"],"steps":["समग्र सामाजिक सुरक्षा पोर्टल पर ऑनलाइन या ग्राम पंचायत में आवेदन करें।","सत्यापन उपरांत हर महीने सीधे बैंक खाते में पेंशन जमा होती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"कल्याणी (विधवा) महिलाएं"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-avivahit-mahila-pension-yojana','{"slug":"mukhyamantri-avivahit-mahila-pension-yojana","title":"मध्य प्रदेश मुख्यमंत्री अविवाहित पेंशन योजना","english":"Mukhyamantri Avivahit Mahila Pension MP","category":"pension","state":"madhya-pradesh","summary":"जीवन भर अविवाहित रहने वाली ऐसी महिलाएं जिनकी आयु 50 वर्ष पूर्ण हो चुकी है, उन्हें बुढ़ापे में सम्मानपूर्वक जीवन यापन हेतु सहायता।","benefit":"50 वर्ष या अधिक आयु की अविवाहित महिलाओं को ₹600 प्रति माह आजीवन सामाजिक सुरक्षा पेंशन","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎂 आयु प्रमाण पत्र (50 वर्ष या अधिक)","📜 अविवाहित होने का शपथ पत्र","🏦 बैंक खाता पासबुक"],"steps":["स्थानीय निकाय (ग्राम पंचायत/नगर पालिका) में निर्धारित फॉर्म जमा करें।","जांच उपरांत मासिक पेंशन आदेश जारी होता है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"50 वर्ष से अधिक आयु की अविवाहित महिलाएं"},{"field":"age","op":"gte","value":50,"label":"न्यूनतम आयु 50 वर्ष"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा महिलाओं की सामाजिक सुरक्षा।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('madhya-pradesh-nishakt-pension-yojana','{"slug":"madhya-pradesh-nishakt-pension-yojana","title":"मध्य प्रदेश निःशक्त पेंशन योजना","english":"MP Nishakt Pension Yojana Disability Monthly Support","category":"pension","state":"madhya-pradesh","summary":"मध्य प्रदेश के समस्त दिव्यांगजनों को दैनिक खर्चों, दवाओं और भरण-पोषण के लिए नियमित मासिक पेंशन संबल।","benefit":"6 वर्ष से अधिक आयु के 40% या अधिक दिव्यांग व्यक्तियों को ₹600 प्रति माह सामाजिक सुरक्षा पेंशन","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🦽 40% या अधिक दिव्यांगता प्रमाण पत्र (UDID कार्ड)","💰 BPL राशन कार्ड या आय प्रमाण पत्र","🏦 बैंक खाता पासबुक"],"steps":["समग्र पोर्टल पर दिव्यांग पेंशन हेतु आवेदन करें या ग्राम पंचायत/वार्ड कार्यालय में जमा करें।","सत्यापन उपरांत राशि हर माह सीधे बैंक खाते में आती है।"],"rules":[],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा दिव्यांगजनों के सम्मान हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mandbuddhi-bahuviklang-sahayata-yojana','{"slug":"mandbuddhi-bahuviklang-sahayata-yojana","title":"मध्य प्रदेश मंदबुद्धि/ बहुविकलांग आर्थिक सहायता योजना","english":"Mandbuddhi Bahuviklang Arthik Sahayata Yojana","category":"pension","state":"madhya-pradesh","summary":"गंभीर मानसिक मंदता या एक से अधिक दिव्यांगता से ग्रस्त नागरिकों की विशेष देखभाल, दवाई और पोषण हेतु अभिभावक के बैंक खाते में आर्थिक मदद।","benefit":"मानसिक रूप से अविकसित व बहुदिव्यांग बच्चों एवं व्यक्तियों को ₹600 प्रति माह विशेष आर्थिक सहायता","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 दिव्यांग और अभिभावक का आधार कार्ड","📋 समग्र ID","🏥 मेडिकल बोर्ड द्वारा जारी मानसिक मंदता/बहुदिव्यांगता प्रमाण पत्र","🏦 अभिभावक का बैंक खाता"],"steps":["जिला दिव्यांग पुनर्वास केंद्र (DDRC) या सामाजिक न्याय कार्यालय में आवेदन प्रस्तुत करें।","चिकित्सीय परीक्षण के बाद सहायता राशि स्वीकृत होती है।"],"rules":[],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा गंभीर दिव्यांगजनों के संरक्षण हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('vridhashram-antvasi-pension-yojana','{"slug":"vridhashram-antvasi-pension-yojana","title":"मध्य प्रदेश वृद्धाश्रम निवासरत अंत:वासी पेंशन योजना","english":"Vridhashram Antvasi Pension Yojana Old Age Home","category":"pension","state":"madhya-pradesh","summary":"वृद्धाश्रम में रहने वाले वृद्धजनों को अपनी छोटी-मोटी व्यक्तिगत जरूरतों और दैनिक खर्चों के लिए आत्मनिर्भर बनाने हेतु पेंशन।","benefit":"मान्यता प्राप्त वृद्धाश्रमों में रहने वाले निराश्रित वरिष्ठ नागरिकों को ₹600 प्रति माह व्यक्तिगत व्यय पेंशन","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏠 वृद्धाश्रम में निवासरत होने का संचालक का प्रमाण पत्र","🏦 बैंक या डाकघर खाता पासबुक"],"steps":["वृद्धाश्रम के अधीक्षक/संचालक के माध्यम से उप-संचालक सामाजिक न्याय को आवेदन भेजा जाता है।","सीधे वृद्धजन के खाते में मासिक राशि अंतरित की जाती है।"],"rules":[{"field":"age","op":"gte","value":60,"label":"वृद्धाश्रम में निवासरत 60 वर्ष या अधिक आयु के वृद्धजन"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा अंत:वासियों का सामाजिक संरक्षण।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('divyang-shiksha-protsahan-yojana','{"slug":"divyang-shiksha-protsahan-yojana","title":"मध्य प्रदेश मुख्यमंत्री दिव्यांग शिक्षा प्रोत्साहन योजना","english":"Divyang Shiksha Protsahan Yojana Special Education","category":"shiksha","state":"madhya-pradesh","summary":"कक्षा 1 से उच्च शिक्षा तक अध्ययनरत दिव्यांग विद्यार्थियों की पढ़ाई में आने वाली बाधाओं को दूर कर उन्हें आधुनिक उपकरण और छात्रवृत्ति देना।","benefit":"दिव्यांग छात्र-छात्राओं को विशेष छात्रवृत्ति, मोटराइज्ड ट्राइसाइकिल, हियरिंग एड एवं लैपटॉप सहायता","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🦽 40% या अधिक दिव्यांगता प्रमाण पत्र (UDID)","🎓 विद्यालय/महाविद्यालय में प्रवेश व उपस्थिति प्रमाण","🏦 बैंक खाता पासबुक"],"steps":["संस्थान के माध्यम से सामाजिक न्याय विभाग को प्रस्ताव प्रेषित करें।","कलेक्टर की अध्यक्षता वाली समिति द्वारा उपकरण व प्रोत्साहन राशि स्वीकृत की जाती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"दिव्यांग विद्यार्थी"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा समावेशी शिक्षा को बढ़ावा।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('rani-durgavati-shri-anna-protsahan-yojana','{"slug":"rani-durgavati-shri-anna-protsahan-yojana","title":"मध्य प्रदेश रानी दुर्गावती श्रीअन्न प्रोत्साहन योजना","english":"Rani Durgavati Shri Anna Protsahan Millet Subsidy","category":"kisan","state":"madhya-pradesh","summary":"मध्य प्रदेश के जनजातीय क्षेत्रों के मोटे अनाजों (श्रीअन्न) की खेती को बढ़ावा देने और किसानों को लाभकारी मूल्य दिलाने हेतु सीधी वित्तीय मदद।","benefit":"कोदो-कुटकी, ज्वार, बाजरा, रागी (मिलेट्स) उगाने वाले किसानों को ₹10 प्रति किलो अतिरिक्त प्रोत्साहन राशि","department":"किसान कल्याण तथा कृषि विकास विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 कोदो-कुटकी बुवाई का खसरा गिरदावरी प्रमाण","🏦 बैंक खाता पासबुक (DBT सक्रिय)"],"steps":["ई-उपार्जन पोर्टल पर श्रीअन्न बोवनी का पंजीयन कराएं।","अधिसूचित उपार्जन केंद्र पर फसल बेचने के बाद ₹10 प्रति किलो प्रोत्साहन सीधे बैंक खाते में भेजा जाता है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"श्रीअन्न (मिलेट्स) उत्पादक कृषक"}],"sourceUrl":"https://mpkrishi.mp.gov.in/","applicationUrl":"https://saara.mp.gov.in/","sourceNotes":"कृषि विभाग MP द्वारा अंतर्राष्ट्रीय मिलेट्स मिशन अंतर्गत योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('gramin-path-roshan-yojana','{"slug":"gramin-path-roshan-yojana","title":"मध्य प्रदेश ग्रामीण पथ रोशन योजना","english":"Gramin Path Roshan Yojana Solar Street Light","category":"awas","state":"madhya-pradesh","summary":"ग्रामीण अंचलों में रात्रि के समय सुरक्षा, प्रकाश और सौर ऊर्जा को बढ़ावा देने के लिए ग्राम पंचायतों में रोशनी की व्यवस्था।","benefit":"ग्राम पंचायतों के प्रमुख चौराहों, मोहल्लों और मार्गों पर ऊर्जा-कुशल सोलर स्ट्रीट लाइट की निःशुल्क स्थापना","department":"पंचायत एवं ग्रामीण विकास विभाग, मध्य प्रदेश","documents":["🪪 ग्राम पंचायत का संकल्प पत्र","📋 ग्रामीणों की मांग व स्थल चयन विवरण"],"steps":["ग्राम सभा में सोलर स्ट्रीट लाइट लगाने का प्रस्ताव पारित कराएं।","जनपद पंचायत व जिला पंचायत द्वारा अनुमोदित एजेंसियों से लाइटें लगवाई जाती हैं।"],"rules":[{"field":"rural","op":"eq","value":true,"label":"ग्रामीण क्षेत्र की ग्राम पंचायतें"}],"sourceUrl":"https://prd.mp.gov.in/","applicationUrl":"https://prd.mp.gov.in/","sourceNotes":"पंचायत विभाग MP द्वारा ग्रामीण बुनियादी ढांचा विकास।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('madhya-pradesh-paarth-yojana','{"slug":"madhya-pradesh-paarth-yojana","title":"मध्य प्रदेश पार्थ योजना","english":"MP Paarth Yojana Youth Career Guidance","category":"rojgar","state":"madhya-pradesh","summary":"10वीं, 12वीं और कॉलेज के छात्रों को उनके कौशल और रुचि के अनुसार सही करियर विकल्प चुनने में विशेषज्ञ मेंटरशिप उपलब्ध कराना।","benefit":"युवाओं को करियर काउंसलिंग, प्रतियोगी परीक्षाओं की तैयारी एवं रोजगार मार्गदर्शन की निःशुल्क कार्यशालाएं","department":"तकनीकी शिक्षा, कौशल विकास एवं रोज़गार विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 शैक्षणिक योग्यता अंकसूची"],"steps":["जिला रोजगार कार्यालय या कॉलेज में आयोजित पार्थ करियर परामर्श शिविर में उपस्थित हों।","मनोवैज्ञानिक व योग्यता परीक्षण के बाद करियर मार्गदर्शन प्राप्त करें।"],"rules":[{"field":"age","op":"gte","value":16,"label":"आयु 16 से 28 वर्ष"},{"field":"age","op":"lte","value":28,"label":"अधिकतम 28 वर्ष"}],"sourceUrl":"https://ssdm.mp.gov.in/","applicationUrl":"https://mprgp.gov.in/","sourceNotes":"रोजगार संचालनालय MP द्वारा युवाओं के करियर संवर्धन हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('pratibhashali-vidyarthi-protsahan-yojana','{"slug":"pratibhashali-vidyarthi-protsahan-yojana","title":"मध्य प्रदेश प्रतिभाशाली विद्यार्थी प्रोत्साहन योजना","english":"Pratibhashali Vidyarthi Protsahan Laptop Scheme","category":"shiksha","state":"madhya-pradesh","summary":"डिजिटल शिक्षा को बढ़ावा देने और उच्च शिक्षा की तैयारी में मदद के लिए 12वीं में उत्कृष्ट प्रदर्शन करने वाले छात्रों को लैपटॉप राशि प्रदान करना।","benefit":"12वीं बोर्ड परीक्षा में 75% या अधिक अंक प्राप्त करने वाले मेधावी छात्र-छात्राओं को लैपटॉप खरीदने हेतु ₹25,000 DBT","department":"स्कूल शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 12वीं बोर्ड की अंकसूची (75% या अधिक अंक)","🏦 छात्र का स्वयं का बैंक खाता (आधार लिंक)"],"steps":["माध्यमिक शिक्षा मंडल के परीक्षा परिणाम के आधार पर स्कूल शिक्षा विभाग स्वतः सूची तैयार करता है।","शिक्षा पोर्टल पर अपने बैंक खाते का मिलान करें; राशि सीधे खाते में अंतरित होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"12वीं बोर्ड में 75% या अधिक अंक पाने वाले विद्यार्थी"}],"sourceUrl":"https://educationportal.mp.gov.in/","applicationUrl":"https://educationportal.mp.gov.in/","sourceNotes":"स्कूल शिक्षा विभाग MP की सबसे लोकप्रिय छात्र प्रोत्साहन योजना।","status":"ACTIVE","priority":true,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('madhya-pradesh-samadhan-yojana','{"slug":"madhya-pradesh-samadhan-yojana","title":"Madhya Pradesh Samadhan Yojana","english":"MP Samadhan Yojana Online Citizen Grievance Portal","category":"rojgar","state":"madhya-pradesh","summary":"CM Helpline 181 और समाधान ऑनलाइन के माध्यम से सरकारी विभागों की सेवाओं और बिजली बिल संबंधी मामलों का पारदर्शी व त्वरित निस्तारण।","benefit":"नागरिकों की समस्याओं, शिकायतों और बिजली बिल विवादों का निश्चित समय-सीमा में ऑनलाइन समाधान","department":"लोक सेवा प्रबंधन विभाग / ऊर्जा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📱 मोबाइल नंबर","📑 शिकायत या विवादित बिल की प्रति"],"steps":["टोल फ्री नंबर 181 पर कॉल करें या cmhelpline.mp.gov.in पर अपनी शिकायत दर्ज करें।","शिकायत क्रमांक (Complaint ID) प्राप्त कर समाधान की स्थिति ट्रैक करें।"],"rules":[],"sourceUrl":"https://cmhelpline.mp.gov.in/","applicationUrl":"https://cmhelpline.mp.gov.in/","sourceNotes":"लोक सेवा प्रबंधन विभाग MP द्वारा सुशासन पहल।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-dairy-plus-yojana','{"slug":"mukhyamantri-dairy-plus-yojana","title":"Madhya Pradesh Mukhyamantri Dairy Plus Yojana","english":"Mukhyamantri Dairy Plus Yojana Murrah Cattle","category":"kisan","state":"madhya-pradesh","summary":"सीहोर, विदिशा और रायसेन सहित चयनित जिलों में पायलट प्रोजेक्ट के तहत उच्च दुग्ध क्षमता वाले मवेशियों की खरीद पर भारी सब्सिडी।","benefit":"पशुपालकों को 2 उन्नत मुर्राह नस्ल की भैंस या साहीवाल गाय क्रय करने पर सामान्य को 50% एवं SC/ST को 75% तक अनुदान","department":"पशुपालन एवं डेयरी विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 पशु आहार व चारे हेतु कृषि भूमि रिकॉर्ड","📜 जाति प्रमाण पत्र","🏦 बैंक खाता पासबुक"],"steps":["पशु चिकित्सालय में निर्धारित फॉर्म भरकर आवेदन करें।","विभागीय क्रय समिति के साथ हरियाणा/पंजाब से उन्नत नस्ल के दुधारू पशु खरीदें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"पशुपालक किसान"}],"sourceUrl":"https://mpdairyfed.mp.gov.in/","applicationUrl":"https://dahd.nic.in/","sourceNotes":"पशुपालन विभाग MP द्वारा दुग्ध उत्पादन क्रांति हेतु योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('shaurya-sankalp-prashikshan-yojana','{"slug":"shaurya-sankalp-prashikshan-yojana","title":"मध्य प्रदेश शौर्य संकल्प प्रशिक्षण योजना","english":"Shaurya Sankalp Prashikshan Defence Police Coaching","category":"shiksha","state":"madhya-pradesh","summary":"मध्य प्रदेश के ग्रामीण और आदिवासी युवाओं को अग्निपथ योजना और सुरक्षा बलों की भर्ती परीक्षाओं में सफलता दिलाने हेतु खेल विभाग द्वारा विशेष प्रशिक्षण।","benefit":"सेना, नौसेना, वायुसेना, पुलिस और अर्धसैनिक बलों में भर्ती हेतु युवाओं को पूर्णतः निःशुल्क आवासीय शारीरिक व लिखित कोचिंग","department":"खेल एवं युवा कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 10वीं/12वीं अंकसूची","🏥 स्वास्थ्य/फिटनेस प्रमाण पत्र","🏠 मूल निवास प्रमाण पत्र"],"steps":["जिला खेल एवं युवा कल्याण अधिकारी कार्यालय में भर्ती सूचना आने पर आवेदन करें।","शारीरिक दक्षता परीक्षण में सफल होने पर प्रशिक्षण शिविर में निःशुल्क प्रवेश पाएं।"],"rules":[{"field":"age","op":"gte","value":17,"label":"आयु 17.5 से 23 वर्ष"},{"field":"age","op":"lte","value":23,"label":"अधिकतम 23 वर्ष"}],"sourceUrl":"https://sports.mp.gov.in/","applicationUrl":"https://sports.mp.gov.in/","sourceNotes":"खेल एवं युवा कल्याण विभाग MP द्वारा राष्ट्र रक्षा में युवाओं की भागीदारी बढ़ाने हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('yashoda-dugdh-praday-yojana','{"slug":"yashoda-dugdh-praday-yojana","title":"Madhya Pradesh Yashoda Dugdh Praday Yojana","english":"Yashoda Dugdh Praday Yojana Nutrition Scheme","category":"kisan","state":"madhya-pradesh","summary":"कुपोषण उन्मूलन और बाल स्वास्थ्य सुधार हेतु दुग्ध संघों (सांची) के माध्यम से आंगनवाड़ियों में पौष्टिक दूध का निःशुल्क वितरण।","benefit":"आंगनवाड़ी के बच्चों और धात्री माताओं को सप्ताह में 3 दिन सुगंधित मीठा पाश्चुरीकृत दूध (फ्लेवर्ड मिल्क) प्रदाय","department":"महिला एवं बाल विकास विभाग, मध्य प्रदेश","documents":["🪪 बच्चे/माता का आधार कार्ड","📋 समग्र ID","📜 आंगनवाड़ी केंद्र में नियमित पंजीयन"],"steps":["गांव या वार्ड के नजदीकी आंगनवाड़ी केंद्र में बच्चे का नाम दर्ज कराएं।","नियमित उपस्थिति के दौरान निर्धारित दिनों में पौष्टिक दूध का लाभ लें।"],"rules":[],"sourceUrl":"https://mpwcdmis.gov.in/","applicationUrl":"https://mpdairyfed.mp.gov.in/","sourceNotes":"WCD MP द्वारा बच्चों के पोषण स्तर में सुधार हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('social-security-old-age-pension-scheme','{"slug":"social-security-old-age-pension-scheme","title":"Madhya Pradesh Social Security Old Age Pension Scheme","english":"Social Security Old Age Pension MP 600 Monthly","category":"pension","state":"madhya-pradesh","summary":"मध्य प्रदेश के समस्त पात्र वृद्धजनों को बुढ़ापे में सम्मानपूर्वक जीवन यापन हेतु सतत वित्तीय सुरक्षा देने वाली योजना।","benefit":"60 वर्ष या अधिक आयु के निराश्रित वृद्धजनों को ₹600 प्रति माह नियमित पेंशन सीधे बैंक खाते में","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र परिवार एवं सदस्य ID","🎂 आयु प्रमाण पत्र (60 वर्ष या अधिक)","🏦 आधार लिंक बैंक खाता पासबुक"],"steps":["ग्राम पंचायत या नगरीय निकाय कार्यालय में आवेदन प्रस्तुत करें।","सत्यापन उपरांत नियमित रूप से हर माह ₹600 पेंशन बैंक खाते में DBT होती है।"],"rules":[{"field":"age","op":"gte","value":60,"label":"आयु 60 वर्ष या अधिक"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा संचालित बुनियादी वृद्धावस्था संबल।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('samagra-vridhashram-antvasi-pension-yojana','{"slug":"samagra-vridhashram-antvasi-pension-yojana","title":"Madhya Pradesh Samagra Samajik Suraksha Vridh Ashram Mai Ant-vasi Pension Yojana","english":"Samagra Samajik Suraksha Vridhashram Pension","category":"pension","state":"madhya-pradesh","summary":"वृद्धाश्रम में रह रहे असहाय वृद्धजनों को अपनी छोटी-मोटी व्यक्तिगत व धार्मिक जरूरतों के लिए स्वावलंबी बनाने हेतु पेंशन।","benefit":"शासकीय अथवा अनुदान प्राप्त वृद्धाश्रमों में निवासरत वरिष्ठ नागरिकों को ₹600 प्रति माह व्यक्तिगत खर्च पेंशन","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏠 वृद्धाश्रम में निवासरत होने का अधीक्षक का प्रमाण पत्र","🏦 बैंक पासबुक"],"steps":["वृद्धाश्रम अधीक्षक के माध्यम से जिला सामाजिक न्याय विभाग को आवेदन प्रेषित होता है।","राशि सीधे वृद्धजन के बैंक खाते में जमा की जाती है।"],"rules":[{"field":"age","op":"gte","value":60,"label":"वृद्धाश्रम में निवासरत 60 वर्ष से अधिक आयु के नागरिक"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा अंत:वासियों का संरक्षण।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('mukhyamantri-kalyani-vivah-sahayata-yojana','{"slug":"mukhyamantri-kalyani-vivah-sahayata-yojana","title":"Madhya Pradesh Mukhyamantri Kalyani Vivah Sahayata Yojana","english":"Mukhyamantri Kalyani Vivah Sahayata Two Lakhs","category":"mahila","state":"madhya-pradesh","summary":"विधवा पुनर्विवाह को सामाजिक मान्यता देने और कल्याणी बहनों के सुखद पुनर्वास के लिए मध्य प्रदेश सरकार की प्रगतिशील योजना।","benefit":"कल्याणी (विधवा) महिला के पुनर्विवाह करने पर दांपत्य जीवन प्रारंभ करने हेतु ₹2,00,000 (दो लाख रुपये) की आर्थिक सहायता","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 कल्याणी और नए पति का आधार कार्ड","📋 समग्र ID","🏥 पूर्व पति का मृत्यु प्रमाण पत्र","💍 पुनर्विवाह प्रमाण पत्र / मैरिज सर्टिफिकेट","🏦 कल्याणी का स्वयं का बैंक खाता"],"steps":["पुनर्विवाह की तिथि से 1 वर्ष के भीतर जनपद पंचायत या नगर पालिका में आवेदन प्रस्तुत करें।","कलेक्टर द्वारा जांच उपरांत ₹2,00,000 की राशि सीधे कल्याणी के बैंक खाते में अंतरित होती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"पुनर्विवाह करने वाली कल्याणी (विधवा) महिला"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा विधवा पुनर्विवाह प्रोत्साहन योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('shaikshanik-chatravriti-yojana','{"slug":"shaikshanik-chatravriti-yojana","title":"Madhya Pradesh Shaikshanik Chatravriti Yojana","english":"Shaikshanik Chatravriti Yojana Class 1 to 10","category":"shiksha","state":"madhya-pradesh","summary":"प्राथमिक एवं माध्यमिक कक्षाओं में अध्ययनरत कमजोर वर्ग के बच्चों को स्कूल की किताबें, कॉपियां और यूनिफॉर्म खरीदने हेतु नकद छात्रवृत्ति।","benefit":"कक्षा 1 से 10वीं तक अध्ययनरत SC, ST, OBC एवं घुमन्तु जातियों के विद्यार्थियों को वार्षिक छात्रवृत्ति","department":"स्कूल शिक्षा विभाग / आदिम जाति कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 डिजिटल जाति प्रमाण पत्र (SC/ST/OBC)","🎓 शाला में प्रवेश व उपस्थिति रिकॉर्ड","🏦 छात्र/अभिभावक का बैंक खाता"],"steps":["शाला के प्रधान पाठक द्वारा शिक्षा पोर्टल (educationportal.mp.gov.in) पर प्रोफाइल दर्ज की जाती है।","सत्यापन उपरांत छात्रवृत्ति राशि सीधे खाते में DBT होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"कक्षा 1 से 10वीं तक के स्कूली छात्र"}],"sourceUrl":"https://scholarshipportal.mp.nic.in/","applicationUrl":"https://educationportal.mp.gov.in/","sourceNotes":"स्कूल शिक्षा विभाग MP द्वारा समेकित छात्रवृत्ति योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('shiksha-protsahan-puraskar-yojana','{"slug":"shiksha-protsahan-puraskar-yojana","title":"Madhya Pradesh Shiksha Protsahan Puraskar Yojana","english":"Shiksha Protsahan Puraskar Board Merit Award","category":"shiksha","state":"madhya-pradesh","summary":"कमजोर वर्ग के होनहार विद्यार्थियों में प्रतिस्पर्धा और शैक्षणिक उत्कृष्टता को प्रोत्साहित करने हेतु मेरिट पुरस्कार।","benefit":"कक्षा 10वीं एवं 12वीं में प्रथम श्रेणी में उत्तीर्ण आरक्षित वर्ग के छात्रों को ₹5,000 से ₹15,000 तक नकद प्रोत्साहन","department":"अनुसूचित जाति / जनजाति कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 जाति प्रमाण पत्र","🎓 10वीं या 12वीं बोर्ड की अंकसूची","🏦 छात्र का बैंक खाता"],"steps":["बोर्ड परिणाम आने के बाद स्कूल प्राचार्य के माध्यम से आवेदन अग्रेषित होता है।","मेरिट अनुसार राशि सीधे बैंक खाते में जमा होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"प्रथम श्रेणी में बोर्ड परीक्षा उत्तीर्ण छात्र"}],"sourceUrl":"https://scdevelopmentmp.nic.in/","applicationUrl":"https://educationportal.mp.gov.in/","sourceNotes":"अजाक एवं जनजातीय कार्य विभाग MP द्वारा शिक्षा संवर्धन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('kalyani-sahayata-yojana','{"slug":"kalyani-sahayata-yojana","title":"Madhya Pradesh Kalyani Sahayata Yojana","english":"Kalyani Sahayata Yojana Financial Relief","category":"mahila","state":"madhya-pradesh","summary":"परिवार के मुख्य कमाऊ मुखिया की मृत्यु होने पर कल्याणी बहन और बच्चों को तत्काल भरण-पोषण और सहारा देने वाली योजना।","benefit":"पति की आकस्मिक मृत्यु होने पर पीड़ित परिवार की महिला को आपातकालीन वित्तीय सहायता व पेंशन संबल","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏥 पति का मृत्यु प्रमाण पत्र","💰 BPL राशन कार्ड / आय प्रमाण","🏦 बैंक खाता पासबुक"],"steps":["तहसीलदार अथवा नगर पालिका कार्यालय में आवेदन जमा करें।","जांच उपरांत तात्कालिक सहायता और कल्याणी पेंशन तुरंत स्वीकृत होती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"कल्याणी (विधवा) बहनें"}],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा पारिवारिक संकट में संबल।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('vivah-sahayata-yojana','{"slug":"vivah-sahayata-yojana","title":"Madhya Pradesh Vivah Sahayata Yojana","english":"BOCW Vivah Sahayata Construction Labor Marriage","category":"mahila","state":"madhya-pradesh","summary":"निर्माण श्रमिकों (राजमिस्त्री, मजदूर, प्लंबर, इलेक्ट्रीशियन) के परिवार में विवाह के भारी खर्च में मदद करने हेतु एकमुश्त अनुदान।","benefit":"भवन एवं संनिर्माण कर्मकार मंडल में पंजीकृत श्रमिकों के स्वयं अथवा पुत्र/पुत्री के विवाह पर ₹51,000 आर्थिक सहायता","department":"मध्य प्रदेश भवन एवं अन्य संनिर्माण कर्मकार कल्याण मंडल (BOCW)","documents":["🪪 वर-वधू और श्रमिक का आधार कार्ड","📋 समग्र ID","📜 वैध निर्माण श्रमिक पंजीयन कार्ड (कम से कम 90 दिन पुराना)","💍 विवाह प्रमाण पत्र / निमंत्रण पत्र","🏦 श्रमिक का बैंक खाता"],"steps":["विवाह संपन्न होने के 90 दिन के भीतर श्रम सेवा पोर्टल पर ऑनलाइन आवेदन करें।","श्रम अधिकारी द्वारा सत्यापन के बाद ₹51,000 की राशि बैंक खाते में DBT होती है।"],"rules":[{"field":"occupation","op":"eq","value":"worker","label":"पंजीकृत निर्माण श्रमिक"}],"sourceUrl":"https://labour.mp.gov.in/","applicationUrl":"https://shramsewa.mp.gov.in/","sourceNotes":"मध्य प्रदेश BOCW मंडल द्वारा निर्माण श्रमिकों के लिए।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('ambedkar-kamdhenu-yojana','{"slug":"ambedkar-kamdhenu-yojana","title":"मध्य प्रदेश डॉ. भीमराव अंबेडकर कामधेनु योजना","english":"Ambedkar Kamdhenu Yojana SC Dairy Animal Grant","category":"kisan","state":"madhya-pradesh","summary":"अनुसूचित जाति के भूमिहीन और सीमांत परिवारों को दुग्ध व्यवसाय से जोड़कर स्थायी स्वरोज़गार और नियमित आय का साधन देना।","benefit":"अनुसूचित जाति (SC) के पशुपालकों को 2 दुधारू पशु (गाय/भैंस) खरीदने पर 75% तक सरकारी अनुदान","department":"मध्य प्रदेश राज्य अनुसूचित जाति वित्त एवं विकास निगम","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 SC डिजिटल जाति प्रमाण पत्र","💰 आय प्रमाण पत्र (BPL प्राथमिकता)","🏦 बैंक पासबुक"],"steps":["अजा वित्त विकास निगम के जिला कार्यालय में कामधेनु योजना का आवेदन जमा करें।","स्वीकृति उपरांत पशु मेले से दुधारू पशु क्रय करने हेतु अनुदान जारी होता है।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"SC वर्ग के पशुपालक"}],"sourceUrl":"https://scdevelopmentmp.nic.in/","applicationUrl":"https://dahd.nic.in/","sourceNotes":"अजाक विभाग MP द्वारा पशुपालन स्वरोज़गार संवर्धन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('delhi-chhatragrih-yojana','{"slug":"delhi-chhatragrih-yojana","title":"मध्य प्रदेश दिल्ली छात्रगृह योजना","english":"MP Delhi Chhatragrih Yojana UPSC Aspirants Hostel","category":"shiksha","state":"madhya-pradesh","summary":"राष्ट्रीय राजधानी दिल्ली में उच्चस्तरीय कोचिंग कर रहे मध्य प्रदेश के प्रतिभावान कमजोर वर्ग के छात्रों को निःशुल्क आवास, लाइब्रेरी और मेस सुविधा।","benefit":"दिल्ली में रहकर संघ लोक सेवा आयोग (UPSC) सिविल सेवा की तैयारी करने वाले MP के SC/ST/OBC छात्रों को निःशुल्क आवासीय छात्रावास","department":"जनजातीय कार्य विभाग / आदिम जाति कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 जाति प्रमाण पत्र (SC/ST/OBC)","🎓 स्नातक डिग्री अंकसूची","📑 दिल्ली के प्रतिष्ठित कोचिंग संस्थान में प्रवेश प्रमाण पत्र"],"steps":["विभागीय पोर्टल पर दिल्ली छात्रगृह प्रवेश हेतु ऑनलाइन आवेदन प्रस्तुत करें।","मेरिट सूची अनुसार दिल्ली स्थित मध्य प्रदेश भवन/छात्रावास में सीट आवंटित होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"दिल्ली में सिविल सेवा की तैयारी कर रहे MP के छात्र"}],"sourceUrl":"https://tribal.mp.gov.in/","applicationUrl":"https://scdevelopmentmp.nic.in/","sourceNotes":"जनजातीय एवं अनुसूचित जाति कल्याण विभाग MP द्वारा प्रशासनिक प्रतिभा प्रोत्साहन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('resham-samriddhi-yojana','{"slug":"resham-samriddhi-yojana","title":"मध्य प्रदेश रेशम समृद्धि योजना","english":"Resham Samriddhi Yojana Sericulture Silk Farming","category":"kisan","state":"madhya-pradesh","summary":"कम पानी और कम लागत में साल भर रेशम कोकून बेचकर किसानों और विशेषकर महिला समूहों को नियमित नगद आमदनी कराने की योजना।","benefit":"मलबरी (शहतूत) वृक्षारोपण, कीटपालन शेड निर्माण एवं रेशम कोकून उत्पादन पर 75% से 90% तक अनुदान","department":"रेशम संचालनालय, कुटीर एवं ग्रामोद्योग विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🌾 न्यूनतम 0.5 से 1 एकड़ कृषि भूमि खसरा","🏦 बैंक खाता पासबुक"],"steps":["जिला रेशम अधिकारी कार्यालय में रेशम कृषक के रूप में पंजीयन कराएं।","निःशुल्क शहतूत पौधे और शेड निर्माण हेतु अनुदान प्राप्त कर रेशम पालन शुरू करें।"],"rules":[{"field":"occupation","op":"eq","value":"farmer","label":"रेशम कीट पालन करने के इच्छुक कृषक"}],"sourceUrl":"https://sericulture.mp.gov.in/","applicationUrl":"https://sericulture.mp.gov.in/","sourceNotes":"कुटीर एवं ग्रामोद्योग विभाग MP द्वारा रेशम उद्योग विस्तार।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sardar-patel-coaching-yojana','{"slug":"sardar-patel-coaching-yojana","title":"मध्य प्रदेश सरदार पटेल कोचिंग प्रशिक्षण योजना","english":"Sardar Patel Coaching Yojana Free UPSC MPPSC","category":"shiksha","state":"madhya-pradesh","summary":"प्रतिभाशाली ओबीसी युवाओं को बड़े शहरों के प्रतिष्ठित कोचिंग संस्थानों के माध्यम से प्रतियोगी परीक्षाओं की तैयारी कराने की महत्वाकांक्षी योजना।","benefit":"अन्य पिछड़ा वर्ग (OBC) के मेधावी छात्र-छात्राओं को सिविल सेवा (UPSC, MPPSC) एवं बैंकिंग परीक्षाओं की निःशुल्क गुणवत्तापूर्ण कोचिंग","department":"पिछड़ा वर्ग एवं अल्पसंख्यक कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 OBC जाति प्रमाण पत्र (नॉन-क्रीमीलेयर)","🎓 स्नातक उपाधि अंकसूची","💰 पारिवारिक वार्षिक आय ₹3 लाख से कम प्रमाण"],"steps":["विभाग के पोर्टल पर कोचिंग प्रवेश परीक्षा हेतु ऑनलाइन आवेदन करें।","प्रवेश परीक्षा में चयनित होने पर प्रतिष्ठित कोचिंग में निःशुल्क प्रशिक्षण और पुस्तक भत्ता प्राप्त करें।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"OBC वर्ग के स्नातक छात्र"}],"sourceUrl":"https://backwardwelfare.mp.gov.in/","applicationUrl":"https://backwardwelfare.mp.gov.in/","sourceNotes":"पिछड़ा वर्ग कल्याण विभाग MP द्वारा प्रशासनिक सेवाओं में प्रतिनिधित्व बढ़ाने हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('kanya-saksharta-protsahan-yojana','{"slug":"kanya-saksharta-protsahan-yojana","title":"मध्य प्रदेश कन्या साक्षरता प्रोत्साहन योजना","english":"Kanya Saksharta Protsahan School Cash Incentive","category":"shiksha","state":"madhya-pradesh","summary":"अनुसूचित जाति एवं जनजाति वर्ग की बालिकाओं को 8वीं और 10वीं के बाद स्कूल छोड़ने से रोकने और उच्च माध्यमिक शिक्षा पूरी कराने हेतु प्रोत्साहन।","benefit":"कक्षा 9वीं में नियमित प्रवेश लेने पर ₹1,000 एवं कक्षा 11वीं में प्रवेश लेने पर ₹2,000 की नकद प्रोत्साहन राशि","department":"जनजातीय कार्य विभाग / स्कूल शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 छात्रा का आधार कार्ड","📋 समग्र ID","📜 SC/ST जाति प्रमाण पत्र","🎓 पूर्व कक्षा (8वीं या 10वीं) उत्तीर्ण अंकसूची","🏦 छात्रा का स्वयं का बैंक खाता"],"steps":["विद्यालय में प्रवेश लेते समय समग्र छात्रवृत्ति फॉर्म में योजना का चयन करें।","सत्यापन उपरांत प्रोत्साहन राशि सीधे छात्रा के बैंक खाते में जमा होती है।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"कक्षा 9वीं या 11वीं में प्रवेशित SC/ST छात्राएं"},{"field":"occupation","op":"eq","value":"student","label":"स्कूली छात्राएं"}],"sourceUrl":"https://educationportal.mp.gov.in/","applicationUrl":"https://tribal.mp.gov.in/","sourceNotes":"आदिम जाति कल्याण विभाग MP द्वारा बालिका साक्षरता दर बढ़ाने हेतु।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('obc-minority-udyam-yojana','{"slug":"obc-minority-udyam-yojana","title":"मध्य प्रदेश पिछड़ा वर्ग तथा अल्पसंख्यक उद्यम योजना","english":"OBC Minority Udyam Yojana Big Enterprise Loan","category":"rojgar","state":"madhya-pradesh","summary":"ओबीसी और अल्पसंख्यक समुदाय के युवाओं को आधुनिक उद्योग, राइस मिल, फैब्रिकेशन या बड़े व्यावसायिक प्रोजेक्ट लगाने हेतु रियायती ऋण।","benefit":"विनिर्माण एवं सेवा क्षेत्र में उद्योग लगाने हेतु ₹10 लाख से ₹50 लाख तक ऋण, 5% ब्याज अनुदान और मार्जिन मनी","department":"मध्य प्रदेश पिछड़ा वर्ग तथा अल्पसंख्यक वित्त एवं विकास निगम","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 OBC या अल्पसंख्यक प्रमाण पत्र","🎓 न्यूनतम 10वीं पास अंकसूची","📑 विस्तृत प्रोजेक्ट रिपोर्ट (DPR)","🏦 बैंक पासबुक"],"steps":["SAMAST पोर्टल पर ऑनलाइन आवेदन प्रस्तुत करें।","निगम की टास्क फोर्स समिति द्वारा स्वीकृति मिलने पर बैंक ऋण और 5 वर्षों तक ब्याज अनुदान जारी होता है।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 45 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}],"sourceUrl":"https://backwardwelfare.mp.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"पिछड़ा वर्ग एवं अल्पसंख्यक वित्त निगम MP द्वारा संचालित।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('obc-minority-swarojgar-yojana','{"slug":"obc-minority-swarojgar-yojana","title":"मध्य प्रदेश पिछड़ा वर्ग तथा अल्पसंख्यक स्वरोजगार योजना","english":"OBC Minority Swarojgar Yojana Self Employment","category":"rojgar","state":"madhya-pradesh","summary":"ओबीसी और अल्पसंख्यक वर्ग के बेरोजगार युवक-युवतियों को सर्विस सेंटर, दुकान, वर्कशॉप आदि स्थापित करने हेतु आसान ऋण व सब्सिडी।","benefit":"नया व्यवसाय/स्वरोज़गार शुरू करने हेतु ₹1 लाख से ₹10 लाख तक बैंक ऋण एवं 25% (अधिकतम ₹2 लाख) मार्जिन मनी अनुदान","department":"मध्य प्रदेश पिछड़ा वर्ग तथा अल्पसंख्यक वित्त एवं विकास निगम","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 OBC या अल्पसंख्यक वर्ग प्रमाण","🎓 न्यूनतम 5वीं पास अंकसूची","🏠 मूल निवास प्रमाण पत्र","🏦 बैंक खाता विवरण"],"steps":["SAMAST पोर्टल पर स्वरोजगार योजना घटक चुनकर ऑनलाइन आवेदन करें।","सत्यापन उपरांत बैंक से ऋण और मार्जिन मनी अनुदान प्राप्त करें।"],"rules":[{"field":"age","op":"gte","value":18,"label":"आयु 18 से 45 वर्ष"},{"field":"age","op":"lte","value":45,"label":"अधिकतम 45 वर्ष"}],"sourceUrl":"https://backwardwelfare.mp.gov.in/","applicationUrl":"https://samast.mponline.gov.in/","sourceNotes":"पिछड़ा वर्ग एवं अल्पसंख्यक कल्याण विभाग MP द्वारा स्वरोज़गार विस्तार।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('dnt-swarojgar-yojana','{"slug":"dnt-swarojgar-yojana","title":"मध्य प्रदेश मुख्यमंत्री विमुक्त घुमन्तु और अर्द्ध घुमन्तु स्वरोजगार योजना","english":"DNT Swarojgar Yojana Denotified Nomadic Tribes","category":"rojgar","state":"madhya-pradesh","summary":"कंजड़, बंजारा, कालबेलिया, नट, बांछड़ा जैसी विमुक्त जनजातियों के पारंपरिक हुनर को बढ़ावा देकर उन्हें स्थायी आजीविका और रोज़गार देना।","benefit":"विमुक्त, घुमन्तु और अर्द्ध-घुमन्तु जातियों के नागरिकों को व्यक्तिगत व्यवसाय हेतु ₹1 लाख तक का ऋण व 25% सरकारी अनुदान","department":"विमुक्त, घुमन्तु एवं अर्द्धघुमन्तु जनजाति कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 विमुक्त/घुमन्तु जाति प्रमाण पत्र","🏠 मूल निवास प्रमाण पत्र","🏦 बैंक खाता पासबुक"],"steps":["जिला विमुक्त जाति कल्याण अधिकारी कार्यालय में आवेदन प्रस्तुत करें।","सत्यापन के बाद उपकरण व कार्यशील पूंजी हेतु अनुदान और ऋण उपलब्ध कराया जाता है।"],"rules":[{"field":"occupation","op":"eq","value":"self-employed","label":"विमुक्त, घुमन्तु व अर्द्ध-घुमन्तु जाति सदस्य"}],"sourceUrl":"https://denotifiedtribes.mp.gov.in/","applicationUrl":"https://denotifiedtribes.mp.gov.in/","sourceNotes":"विमुक्त जाति कल्याण विभाग MP द्वारा उपेक्षित वर्गों का उत्थान।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sambal-shiksha-protsahan-yojana','{"slug":"sambal-shiksha-protsahan-yojana","title":"मध्य प्रदेश मुख्यमंत्री जन कल्याण (शिक्षा प्रोत्साहन) योजना","english":"Sambal Shiksha Protsahan Yojana College Fee Waiver","category":"shiksha","state":"madhya-pradesh","summary":"गरीब मजदूर के बच्चों को पैसे की कमी के कारण डॉक्टर, इंजीनियर या उच्च शिक्षा से वंचित न होना पड़े, इसके लिए राज्य शासन द्वारा शत-प्रतिशत फीस वहन।","benefit":"संबल कार्डधारी असंगठित श्रमिकों के बच्चों की उच्च शिक्षा, इंजीनियरिंग, MBBS, MBA, ITI, पॉलिटेक्निक की पूरी ट्यूशन फीस सरकार देती है","department":"श्रम विभाग, मध्य प्रदेश","documents":["🪪 छात्र और अभिभावक का आधार कार्ड","📋 समग्र परिवार ID","📜 वैध संबल कार्ड","🎓 12वीं की अंकसूची एवं राष्ट्रीय प्रवेश परीक्षा (NEET, JEE) आवंटन पत्र","📑 कॉलेज प्रवेश व फीस विवरण"],"steps":["कॉलेज में प्रवेश लेने के बाद संबल पोर्टल या स्कॉलरशिप पोर्टल पर शिक्षा प्रोत्साहन हेतु आवेदन करें।","सत्यापन उपरांत पूरी शिक्षण फीस सीधे कॉलेज के खाते में जमा हो जाती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"संबल कार्डधारी श्रमिकों के अध्ययनरत बच्चे"}],"sourceUrl":"https://sambal.mp.gov.in/","applicationUrl":"https://scholarshipportal.mp.nic.in/","sourceNotes":"श्रम विभाग MP की सबसे क्रांतिकारी छात्र हितैषी योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sindhu-darshan-yojana','{"slug":"sindhu-darshan-yojana","title":"मध्य प्रदेश सिंधु दर्शन योजना","english":"Sindhu Darshan Pilgrimage Grant Scheme","category":"pension","state":"madhya-pradesh","summary":"लेह-लद्दाख में प्रतिवर्ष आयोजित होने वाले ऐतिहासिक सिंधु दर्शन महोत्सव में भाग लेने वाले राज्य के तीर्थयात्रियों को वित्तीय सहायता।","benefit":"लद्दाख में सिंधु दर्शन तीर्थ यात्रा पर जाने वाले मध्य प्रदेश के श्रद्धालुओं को प्रति यात्री ₹25,000 का यात्रा अनुदान","department":"धार्मिक न्यास एवं धर्मस्व विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🏠 मध्य प्रदेश मूल निवास प्रमाण पत्र","📑 यात्रा टिकट / सिंधु दर्शन उत्सव समिति पंजीयन रसीद","🏦 बैंक पासबुक"],"steps":["यात्रा संपन्न करने के 60 दिन के भीतर यात्रा प्रमाणों सहित कलेक्टर कार्यालय में आवेदन जमा करें।","सत्यापन उपरांत ₹25,000 की अनुदान राशि सीधे बैंक खाते में अंतरित होती है।"],"rules":[],"sourceUrl":"https://tirthdarshan.mp.gov.in/","applicationUrl":"https://tirthdarshan.mp.gov.in/","sourceNotes":"धार्मिक न्यास विभाग MP द्वारा राष्ट्रीय एकात्मता तीर्थ यात्रा अनुदान।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('divyang-vivah-protsahan-yojana','{"slug":"divyang-vivah-protsahan-yojana","title":"मध्य प्रदेश दिव्यांग विवाह प्रोत्साहन योजना","english":"Divyang Vivah Protsahan Two Lakhs Scheme","category":"mahila","state":"madhya-pradesh","summary":"दिव्यांगजनों के पुनर्वास, सामाजिक स्वीकृति और गरिमापूर्ण दांपत्य जीवन को बढ़ावा देने के लिए दिया जाने वाला बड़ा आर्थिक संबल।","benefit":"दिव्यांग व्यक्ति से विवाह करने वाले सामान्य युवक अथवा युवती को ₹2,00,000 (दो लाख रुपये) की एकमुश्त प्रोत्साहन राशि","department":"सामाजिक न्याय एवं दिव्यांगजन सशक्तिकरण विभाग, मध्य प्रदेश","documents":["🪪 पति और पत्नी दोनों का आधार कार्ड","📋 समग्र ID","🦽 जीवनसाथी का 40% या अधिक दिव्यांगता प्रमाण पत्र (UDID)","💍 विवाह पंजीयन प्रमाण पत्र","🏦 संयुक्त बैंक खाता विवरण"],"steps":["विवाह के 1 वर्ष के भीतर जनपद पंचायत या जिला सामाजिक न्याय कार्यालय में आवेदन करें।","सत्यापन उपरांत ₹2 लाख की राशि सीधे बैंक खाते में जमा होती है।"],"rules":[],"sourceUrl":"https://socialjustice.mp.gov.in/","applicationUrl":"https://samagra.gov.in/","sourceNotes":"सामाजिक न्याय विभाग MP द्वारा दिव्यांग विवाह प्रोत्साहन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('sainik-school-shulk-pratipurti-yojana','{"slug":"sainik-school-shulk-pratipurti-yojana","title":"मध्य प्रदेश सैनिक/सार्वजनिक स्कूलों की शिक्षण शुल्क प्रतिपूर्ति योजना","english":"Sainik School Tuition Fee Reimbursement","category":"shiksha","state":"madhya-pradesh","summary":"रक्षा सेवाओं में मध्य प्रदेश के युवाओं की भागीदारी बढ़ाने और सैनिक स्कूल में अध्ययनरत छात्रों के अभिभावकों पर फीस का बोझ समाप्त करना।","benefit":"सैनिक स्कूल रीवा में चयनित मध्य प्रदेश के मूल निवासी छात्रों की शिक्षण फीस व मेस शुल्क की शत-प्रतिशत प्रतिपूर्ति","department":"स्कूल शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 छात्र और अभिभावक का आधार कार्ड","📋 समग्र ID","🏠 मध्य प्रदेश मूल निवास प्रमाण पत्र","📑 सैनिक स्कूल रीवा का प्रवेश पत्र व फीस रसीद","🏦 बैंक खाता पासबुक"],"steps":["सैनिक स्कूल रीवा के प्राचार्य के माध्यम से राज्य शिक्षा संचालनालय को प्रतिपूर्ति प्रस्ताव प्रस्तुत करें।","फीस सीधे स्कूल को अथवा छात्र के अभिभावक के खाते में प्रतिपूर्ति की जाती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"सैनिक स्कूल रीवा में अध्ययनरत MP के छात्र"}],"sourceUrl":"https://educationportal.mp.gov.in/","applicationUrl":"https://educationportal.mp.gov.in/","sourceNotes":"स्कूल शिक्षा विभाग MP द्वारा सैन्य सेवा तैयारी प्रोत्साहन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('civil-seva-protsahan-yojana','{"slug":"civil-seva-protsahan-yojana","title":"मध्य प्रदेश सिविल सेवा प्रोत्साहन योजना","english":"Civil Seva Protsahan Yojana UPSC Pre Mains Award","category":"shiksha","state":"madhya-pradesh","summary":"संघ लोक सेवा आयोग की परीक्षा के विभिन्न चरणों में सफल होने वाले कमजोर वर्ग के युवाओं को अगले चरण की तैयारी हेतु वित्तीय सहारा।","benefit":"UPSC सिविल सेवा प्रारंभिक परीक्षा उत्तीर्ण करने पर ₹1,00,000 एवं मुख्य परीक्षा उत्तीर्ण करने पर ₹50,000 नकद प्रोत्साहन","department":"जनजातीय कार्य विभाग / पिछड़ा वर्ग कल्याण विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","📜 जाति प्रमाण पत्र (ST/SC/OBC)","📑 UPSC सिविल सेवा परीक्षा का रोल नंबर व उत्तीर्ण परिणाम पत्र","🏦 छात्र का बैंक खाता"],"steps":["परिणाम घोषित होने के 45 दिन के भीतर संबंधित विभाग के पोर्टल पर आवेदन प्रस्तुत करें।","सत्यापन उपरांत प्रोत्साहन राशि सीधे खाते में अंतरित होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"UPSC प्रारंभिक/मुख्य परीक्षा उत्तीर्ण छात्र"}],"sourceUrl":"https://tribal.mp.gov.in/","applicationUrl":"https://backwardwelfare.mp.gov.in/","sourceNotes":"जनजातीय एवं पिछड़ा वर्ग कल्याण विभाग MP द्वारा सिविल सेवा प्रोत्साहन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('bhagwan-shri-krishna-medhavi-chatravriti-yojana','{"slug":"bhagwan-shri-krishna-medhavi-chatravriti-yojana","title":"Madhya Pradesh Bhagwan Shri Krishna Medhavi Chatravriti Yojana","english":"Bhagwan Shri Krishna Medhavi Chatravriti Scheme","category":"shiksha","state":"madhya-pradesh","summary":"संस्कृति, साहित्य और मेधावी अध्ययन में संलग्न विद्यार्थियों को आर्थिक कठिनाइयों से मुक्त रखकर अपनी शिक्षा में उत्कृष्ट प्रदर्शन हेतु सहायता।","benefit":"पारंपरिक कला, संस्कृति, वेद अध्ययन एवं मेधावी छात्रों को उच्च शिक्षा हेतु वार्षिक विशेष छात्रवृत्ति","department":"उच्च शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 पूर्व परीक्षा में 60% से अधिक अंकसूची","📑 कॉलेज/संस्थान में प्रवेश प्रमाण पत्र","🏦 छात्र का बैंक खाता"],"steps":["स्टेट स्कॉलरशिप पोर्टल पर ऑनलाइन आवेदन प्रस्तुत करें।","कॉलेज प्राचार्य से सत्यापन उपरांत छात्रवृत्ति सीधे बैंक खाते में जमा होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"उच्च शिक्षा में अध्ययनरत मेधावी छात्र"}],"sourceUrl":"https://scholarshipportal.mp.nic.in/","applicationUrl":"https://highereducation.mp.gov.in/","sourceNotes":"उच्च शिक्षा विभाग MP द्वारा मेधावी प्रतिभा संवर्धन।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('vikramaditya-scholarship-yojana','{"slug":"vikramaditya-scholarship-yojana","title":"Madhya Pradesh Vikramaditya Scholarship Yojana","english":"Vikramaditya Scholarship General Category Poor Students","category":"shiksha","state":"madhya-pradesh","summary":"सामान्य वर्ग के ऐसे निर्धन छात्र-छात्राएं जिनके परिवार की वार्षिक आय ₹1.18 लाख से कम है, उन्हें कॉलेज की पढ़ाई पूरी करने हेतु आर्थिक संबल।","benefit":"सामान्य निर्धन वर्ग (General BPL) के स्नातक कॉलेज विद्यार्थियों को शिक्षण शुल्क व पुस्तकों हेतु ₹2,500 प्रति वर्ष","department":"उच्च शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 12वीं में 60% या अधिक अंकसूची","💰 BPL राशन कार्ड या ₹1,18,000 से कम आय प्रमाण पत्र","🏦 छात्र का बैंक खाता"],"steps":["मध्य प्रदेश स्टेट स्कॉलरशिप पोर्टल (scholarshipportal.mp.nic.in) पर ऑनलाइन आवेदन करें।","कॉलेज प्राचार्य द्वारा सत्यापन के बाद छात्रवृत्ति सीधे बैंक खाते में DBT होती है।"],"rules":[{"field":"occupation","op":"eq","value":"student","label":"सामान्य वर्ग के निर्धन स्नातक विद्यार्थी"}],"sourceUrl":"https://scholarshipportal.mp.nic.in/","applicationUrl":"https://highereducation.mp.gov.in/","sourceNotes":"उच्च शिक्षा विभाग MP द्वारा सामान्य निर्धन वर्ग हेतु समर्पित योजना।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');
INSERT OR IGNORE INTO schemes (slug,data,status,next_review_at,updated_at) VALUES ('shri-medha-scheme-yojana','{"slug":"shri-medha-scheme-yojana","title":"Madhya Pradesh Shri Medha Scheme","english":"MP Shri Medha Scheme Free Coaching Financial Aid","category":"shiksha","state":"madhya-pradesh","summary":"कॉलेज स्तर पर उत्कृष्ट शैक्षणिक रिकॉर्ड वाली छात्राओं को राष्ट्रीय स्तर की प्रतियोगी परीक्षाओं में चयन हेतु मेंटरशिप और वित्तीय सहायता।","benefit":"प्रतिभाशाली बालिकाओं को प्रतियोगी परीक्षाओं की निःशुल्क उच्चस्तरीय कोचिंग, हॉस्टल सुविधा और पुस्तक अनुदान","department":"उच्च शिक्षा विभाग, मध्य प्रदेश","documents":["🪪 आधार कार्ड","📋 समग्र ID","🎓 स्नातक पूर्व वर्षों की अंकसूची (न्यूनतम 60% अंक)","🏠 मध्य प्रदेश मूल निवास प्रमाण पत्र","🏦 छात्रा का बैंक खाता"],"steps":["उच्च शिक्षा विभाग के पोर्टल पर श्री मेधा योजना अंतर्गत ऑनलाइन आवेदन दर्ज करें।","कॉलेज के माध्यम से सत्यापन उपरांत निःशुल्क कोचिंग व छात्रवृत्ति का लाभ प्राप्त करें।"],"rules":[{"field":"gender","op":"eq","value":"female","label":"उच्च शिक्षा अध्ययनरत प्रतिभाशाली छात्राएं"},{"field":"occupation","op":"eq","value":"student","label":"छात्राएं"}],"sourceUrl":"https://highereducation.mp.gov.in/","applicationUrl":"https://scholarshipportal.mp.nic.in/","sourceNotes":"उच्च शिक्षा विभाग MP द्वारा महिला सशक्तिकरण एवं प्रतिभा विकास।","status":"ACTIVE","priority":false,"isSample":false,"verifiedAt":"2026-09-14T00:00:00.000Z","nextReviewAt":"2026-12-14T00:00:00.000Z"}','ACTIVE','2026-12-14T00:00:00.000Z','2026-09-14T00:00:00.000Z');